import time, random, heapq

def _parse(inp):
    res = inp.get("resources", {}) or {}
    rnames = list(res.keys())
    ridx = {n: i for i, n in enumerate(rnames)}
    cals = []
    for n in rnames:
        cal = res[n].get("calendar", []) or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
    jobs = inp.get("jobs", []) or []
    ids = [str(j["id"]) for j in jobs]
    jidx = {s: i for i, s in enumerate(ids)}
    return rnames, ridx, cals, jobs, ids, jidx

def solve(state, params):
    t0 = time.process_time()
    budget = 0.72
    inp = state["input"]
    rnames, ridx, cals, jobs, ids, jidx = _parse(inp)
    n = len(jobs)
    maxcap = [c[-1][1] if c else 0 for c in cals]
    preds = [[] for _ in range(n)]
    for i, jb in enumerate(jobs):
        for p in jb.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "job %s references unknown predecessor %s" % (ids[i], p)}
                return state
            pi = jidx[p]
            if pi not in preds[i]:
                preds[i].append(pi)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]; k += 1
        for v in succs[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                topo.append(v)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []  # per job list of (orig_idx, dur, [(r,u)])
    for i, jb in enumerate(jobs):
        ml = []
        for mi, m in enumerate(jb.get("modes", []) or []):
            ok = True
            req = []
            for rn, u in (m.get("requires", {}) or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False; break
                if u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    req.append((ridx[rn], u))
            if ok:
                ml.append((mi, int(m["duration"]), req))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    rel = [int(jb.get("release", 0) or 0) for jb in jobs]
    due = [jb.get("due") for jb in jobs]
    due = [None if d is None else int(d) for d in due]
    wt = [int(jb.get("weight", 0) or 0) for jb in jobs]
    lastbp = max([c[-1][0] for c in cals] + [0])
    H = max(lastbp, max(rel)) + sum(max(m[1] for m in ml) for ml in modes) + 2
    base = []
    for c in cals:
        a = [0] * H
        for s, (tb, cap) in enumerate(c):
            te = c[s + 1][0] if s + 1 < len(c) else H
            tb = max(tb, 0); te = min(te, H)
            if te > tb:
                a[tb:te] = [cap] * (te - tb)
        base.append(a)
    tard_jobs = [i for i in range(n) if due[i] is not None and wt[i] > 0]

    def ssgs(order, mfix):
        avail = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        md = [0] * n
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            ml = modes[j]
            cand = (ml[mfix[j]],) if mfix[j] >= 0 else ml
            best = None
            for mk, (mi, d, req) in enumerate(cand):
                t = est
                while True:
                    ok = True
                    for (r, u) in req:
                        a = avail[r]
                        for x in range(t, t + d):
                            if a[x] < u:
                                t = x + 1; ok = False; break
                        if not ok:
                            break
                    if ok:
                        break
                f = t + d
                if best is None or f < best[0]:
                    best = (f, t, mk if mfix[j] < 0 else mfix[j], d, req)
            f, t, mk, d, req = best
            for (r, u) in req:
                a = avail[r]
                for x in range(t, f):
                    a[x] -= u
            st[j] = t; fin[j] = f; md[j] = mk
        cost = max(fin)
        for j in tard_jobs:
            if fin[j] > due[j]:
                cost += wt[j] * (fin[j] - due[j])
        return cost, st, md

    dmin = [min(m[1] for m in ml) for ml in modes]
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            if es[p] + dmin[p] > e:
                e = es[p] + dmin[p]
        es[j] = e
    cp = max(es[j] + dmin[j] for j in range(n))
    lf = [cp] * n
    for j in reversed(topo):
        v = cp
        for s in succs[j]:
            if lf[s] - dmin[s] < v:
                v = lf[s] - dmin[s]
        lf[j] = v
    lfd = lf[:]
    for j in reversed(topo):
        v = lfd[j]
        if due[j] is not None and wt[j] > 0:
            v = min(v, due[j])
        for s in succs[j]:
            if lfd[s] - dmin[s] < v:
                v = lfd[s] - dmin[s]
        lfd[j] = v
    nsucc = [len(succs[j]) for j in range(n)]

    def order_from_key(key):
        ind = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if ind[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, u = heapq.heappop(h)
            out.append(u)
            for v in succs[u]:
                ind[v] -= 1
                if ind[v] == 0:
                    heapq.heappush(h, (key[v], v))
        return out

    rng = random.Random(12345)
    auto = [-1] * n
    best = None
    keys = [
        [lfd[i] - dmin[i] for i in range(n)],
        [lf[i] - dmin[i] for i in range(n)],
        [lfd[i] for i in range(n)],
        [es[i] for i in range(n)],
        [(lfd[i] - dmin[i]) - 0.01 * nsucc[i] for i in range(n)],
        [min(lf[i], due[i] if due[i] is not None else lf[i]) - 0.1 * wt[i] for i in range(n)],
    ]
    pool = []
    for key in keys:
        o = order_from_key(key)
        c, st, md = ssgs(o, auto)
        pool.append((c, o, auto[:]))
        if best is None or c < best[0]:
            best = (c, st, md)
    shortm = [min(range(len(modes[i])), key=lambda m: modes[i][m][1]) for i in range(n)]
    o = order_from_key(keys[0])
    c, st, md = ssgs(o, shortm)
    pool.append((c, o, shortm[:]))
    if c < best[0]:
        best = (c, st, md)
    spread = max(1.0, cp * 0.15)
    t_samp = t0 + budget * 0.25
    while time.process_time() < t_samp:
        kb = keys[rng.randrange(len(keys))]
        key = [kb[i] + rng.random() * spread for i in range(n)]
        o = order_from_key(key)
        c, st, md = ssgs(o, auto)
        pool.append((c, o, auto[:]))
        if c < best[0]:
            best = (c, st, md)
    pool.sort(key=lambda x: x[0])
    cur_c, cur_o, cur_m = pool[0][0], pool[0][1][:], pool[0][2][:]
    _c, cur_st, cur_md = ssgs(cur_o, cur_m)
    pos = [0] * n
    T = max(0.5, 0.02 * cur_c)
    tend = t0 + budget
    it = 0
    while True:
        it += 1
        if (it & 7) == 0:
            now = time.process_time()
            if now > tend:
                break
            frac = (now - t_samp) / max(1e-6, tend - t_samp)
            T = max(0.05, 0.02 * best[0] * (1 - frac) ** 2)
        o = cur_o
        m = cur_m
        r = rng.random()
        if r < 0.75:
            for i, j in enumerate(o):
                pos[j] = i
            if tard_jobs and rng.random() < 0.3:
                j = tard_jobs[rng.randrange(len(tard_jobs))]
                fj = cur_st[j] + modes[j][cur_md[j]][1]
                if fj <= due[j]:
                    j = o[rng.randrange(n)]
                    early = False
                else:
                    early = True
            else:
                j = o[rng.randrange(n)]
                early = False
            lo = max([pos[p] for p in preds[j]] + [-1]) + 1
            hi = min([pos[s] for s in succs[j]] + [n]) - 1
            if hi <= lo:
                continue
            p0 = pos[j]
            if early:
                if p0 <= lo:
                    continue
                np_ = rng.randint(lo, p0 - 1)
            else:
                np_ = rng.randint(lo, hi)
            if np_ == p0:
                continue
            no = o[:p0] + o[p0 + 1:]
            no.insert(np_, j)
            nm = m
        else:
            j = rng.randrange(n)
            k = len(modes[j])
            if k == 1:
                continue
            nm = m[:]
            choices = [x for x in range(-1, k) if x != m[j]]
            nm[j] = choices[rng.randrange(len(choices))]
            no = o
        c, st, md = ssgs(no, nm)
        if c < best[0]:
            best = (c, st, md)
        d = c - cur_c
        if d <= 0 or rng.random() < pow(2.718281828, -d / T):
            cur_c, cur_o, cur_m = c, no, nm
            cur_st, cur_md = st, md
    c, st, md = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][md[j]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

