import time, heapq, random


def noop(state, params):
    return state


def check_feasible(state, params):
    t0 = time.process_time()
    inp = state["input"]
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    maxcap = {}
    for r, v in res.items():
        cal = v.get("calendar") or [[0, 0]]
        maxcap[r] = cal[-1][1]
    ids = [j["id"] for j in jobs]
    idset = set(ids)
    reason = None
    for j in jobs:
        for p in j.get("after", []) or []:
            if p not in idset:
                reason = "job %s references unknown predecessor %s" % (j["id"], p)
                break
        if reason:
            break
    if not reason:
        for j in jobs:
            okm = False
            for m in j.get("modes", []) or []:
                good = True
                for r, q in (m.get("requires") or {}).items():
                    if r not in maxcap or q > maxcap[r]:
                        good = False
                        break
                if good:
                    okm = True
                    break
            if not okm:
                reason = "job %s has no executable mode" % j["id"]
                break
    if not reason:
        uid = list(dict.fromkeys(ids))
        indeg = {i: 0 for i in uid}
        succ = {i: [] for i in uid}
        for j in jobs:
            for p in set(j.get("after", []) or []):
                indeg[j["id"]] += 1
                succ[p].append(j["id"])
        st = [i for i in uid if indeg[i] == 0]
        cnt = 0
        while st:
            x = st.pop()
            cnt += 1
            for s in succ[x]:
                indeg[s] -= 1
                if indeg[s] == 0:
                    st.append(s)
        if cnt < len(uid):
            reason = "precedence relation has a cycle"
    state["t0"] = t0
    if reason:
        state["feasible"] = False
        state["output"] = {"status": "infeasible", "reason": reason}
    else:
        state["feasible"] = True
    return state


def solve(state, params):
    t0 = state.get("t0", time.process_time())
    deadline = t0 + 0.68
    inp = state["input"]
    res = inp["resources"]
    jobs = inp["jobs"]
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    rnames = list(res.keys())
    ridx = {r: k for k, r in enumerate(rnames)}
    cals = [res[r]["calendar"] for r in rnames]
    maxcap = [c[-1][1] for c in cals]
    idx = {j["id"]: k for k, j in enumerate(jobs)}
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    due = [j.get("due") for j in jobs]
    w = [int(j.get("weight", 0) or 0) for j in jobs]
    preds = [sorted(set(idx[p] for p in (j.get("after") or []))) for j in jobs]
    succs = [[] for _ in range(n)]
    for k in range(n):
        for p in preds[k]:
            succs[p].append(k)
    modes = []
    for j in jobs:
        ml = []
        for mi, m in enumerate(j["modes"]):
            req = m.get("requires") or {}
            good = True
            for r, q in req.items():
                if r not in ridx or q > maxcap[ridx[r]]:
                    good = False
                    break
            if good:
                rq = [(ridx[r], int(q)) for r, q in req.items() if q > 0]
                ml.append((mi, int(m["duration"]), rq))
        modes.append(ml)
    lastbp = max(c[-1][0] for c in cals) if cals else 0
    H = max(rel) + lastbp + sum(max(m[1] for m in ml) for ml in modes) + 2
    base = []
    for c in cals:
        arr = [0] * H
        for bi in range(len(c)):
            a = min(c[bi][0], H)
            b = min(c[bi + 1][0] if bi + 1 < len(c) else H, H)
            cap = c[bi][1]
            for t in range(a, b):
                arr[t] = cap
        base.append(arr)
    indeg = [len(preds[k]) for k in range(n)]
    topo = []
    st = [k for k in range(n) if indeg[k] == 0]
    while st:
        x = st.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                st.append(s)
    mind = [min(m[1] for m in ml) for ml in modes]
    es = [0] * n
    for k in topo:
        e = rel[k]
        for p in preds[k]:
            if es[p] + mind[p] > e:
                e = es[p] + mind[p]
        es[k] = e
    cpm = max(es[k] + mind[k] for k in range(n))
    lf = [cpm] * n
    for k in reversed(topo):
        v = cpm
        if due[k] is not None:
            v = min(v, due[k])
        for s in succs[k]:
            v = min(v, lf[s] - mind[s])
        lf[k] = v
    lfc = [cpm] * n
    for k in reversed(topo):
        v = cpm
        for s in succs[k]:
            v = min(v, lfc[s] - mind[s])
        lfc[k] = v
    tw = [w[k] if due[k] is not None else 0 for k in range(n)]
    for k in reversed(topo):
        for s in succs[k]:
            if tw[s] > tw[k]:
                tw[k] = tw[s]
    nsucc = [len(succs[k]) for k in range(n)]

    def decode(keys, mpref):
        free = [a[:] for a in base]
        fin = [0] * n
        start = [0] * n
        mch = [0] * n
        deg = [len(preds[k]) for k in range(n)]
        hp = [(keys[k], k) for k in range(n) if deg[k] == 0]
        heapq.heapify(hp)
        cost_t = 0
        mk = 0
        while hp:
            _, k = heapq.heappop(hp)
            e = rel[k]
            for p in preds[k]:
                if fin[p] > e:
                    e = fin[p]
            ml = modes[k]
            pm = mpref[k]
            best = None
            cand = ml if (pm < 0 or pm >= len(ml)) else (ml[pm],)
            dk = due[k]
            for (mi, d, rq) in cand:
                t = e
                while True:
                    bad = -1
                    u = t + d - 1
                    while u >= t:
                        for (r, q) in rq:
                            if free[r][u] < q:
                                bad = u
                                break
                        if bad >= 0:
                            break
                        u -= 1
                    if bad < 0:
                        break
                    t = bad + 1
                f = t + d
                c = f
                if dk is not None and f > dk:
                    c += w[k] * (f - dk) + 0.5 * (f - dk)
                load = 0.0
                for (r, q) in rq:
                    load += d * q / maxcap[r]
                sc = (c, load)
                if best is None or sc < best[0]:
                    best = (sc, mi, t, d, rq)
            _, mi, t, d, rq = best
            for (r, q) in rq:
                fr = free[r]
                for u in range(t, t + d):
                    fr[u] -= q
            start[k] = t
            fin[k] = t + d
            mch[k] = mi
            if t + d > mk:
                mk = t + d
            if dk is not None and t + d > dk:
                cost_t += w[k] * (t + d - dk)
            for s in succs[k]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(hp, (keys[s], s))
        return mk + cost_t, start, mch

    rng = random.Random(12345)
    noguide = [-1] * n
    inits = [
        [lf[k] for k in range(n)],
        [lfc[k] for k in range(n)],
        [lf[k] - mind[k] - 0.01 * tw[k] for k in range(n)],
        [es[k] for k in range(n)],
        [es[k] + lf[k] for k in range(n)],
        [lf[k] - 0.1 * nsucc[k] for k in range(n)],
    ]
    best = None
    for keys in inits:
        keys = [keys[k] + 1e-6 * k for k in range(n)]
        r = decode(keys, noguide)
        if best is None or r[0] < best[0]:
            best = (r[0], keys, noguide[:], r[1], r[2])
        if time.process_time() > deadline:
            break
    cur_cost, cur_keys, cur_m, cur_start = best[0], best[1], best[2], best[3]
    it = 0
    span = max(3.0, cpm * 0.1)
    while time.process_time() < deadline:
        it += 1
        if rng.random() < 0.2:
            keys = [cur_start[k] + rng.random() * 0.5 for k in range(n)]
            mp = cur_m[:]
        else:
            keys = cur_keys[:]
            mp = cur_m[:]
            nm = 1 + int(rng.random() * 3)
            for _ in range(nm):
                op = rng.random()
                k = rng.randrange(n)
                if op < 0.5:
                    keys[k] += (rng.random() - 0.5) * 2 * span
                elif op < 0.8:
                    k2 = rng.randrange(n)
                    keys[k], keys[k2] = keys[k2], keys[k]
                else:
                    if len(modes[k]) > 1:
                        mp[k] = rng.randrange(-1, len(modes[k]))
        r = decode(keys, mp)
        if r[0] <= cur_cost or rng.random() < 0.02:
            cur_cost, cur_keys, cur_m, cur_start = r[0], keys, mp, r[1]
            if r[0] < best[0]:
                best = (r[0], keys, mp, r[1], r[2])
        if it % 150 == 0 and cur_cost > best[0]:
            cur_cost, cur_keys, cur_m, cur_start = best[0], best[1], best[2], best[3]
    sched = {}
    for k in range(n):
        sched[jobs[k]["id"]] = {"start": int(best[3][k]), "mode": int(best[4][k])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = best[0]
    state["iters"] = it
    return state

import time, random, heapq

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = sorted([(int(a), int(b)) for a, b in (res[r].get("calendar") or [[0, 0]])])
        if not cal:
            cal = [(0, 0)]
        cals.append(cal)
        maxcap.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    ids = [str(j["id"]) for j in jobs]
    n = len(ids)
    jidx = {}
    for i, s in enumerate(ids):
        if s in jidx:
            state["output"] = {"status": "infeasible", "reason": "duplicate job id " + s}
            return state
        jidx[s] = i
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "unknown predecessor " + p + " of job " + ids[i]}
                return state
            if jidx[p] not in preds[i]:
                preds[i].append(jidx[p])
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]; k += 1
        for v in succs[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                topo.append(v)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            d = int(m.get("duration", 1))
            ok = True
            reqs = []
            for rn, u in (m.get("requires", {}) or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False; break
                if u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    reqs.append((ridx[rn], u))
            if ok:
                ml.append((mi, d, reqs))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job " + ids[i] + " has no feasible mode"}
            return state
        modes.append(ml)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    for i in range(n):
        if due[i] is not None:
            due[i] = int(due[i])
    H = lastbp + max(rel + [0]) + sum(max(m[1] for m in ml) for ml in modes) + 15
    R = len(rnames)
    base = []
    for r in range(R):
        arr = [0] * H
        cal = cals[r]
        for b in range(len(cal)):
            a = max(0, cal[b][0])
            e = cal[b + 1][0] if b + 1 < len(cal) else H
            e = min(e, H)
            c = cal[b][1]
            for t in range(a, e):
                arr[t] = c
        base.append(arr)

    def schedule(keys, mgen, rule):
        avail = [a[:] for a in base]
        cnt = [len(preds[i]) for i in range(n)]
        heap = [(keys[i], i) for i in range(n) if cnt[i] == 0]
        heapq.heapify(heap)
        st = [0] * n
        fin = [0] * n
        mo = [0] * n
        cost = 0
        ms = 0
        while heap:
            _, j = heapq.heappop(heap)
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            ml = modes[j]
            g = mgen[j]
            cand = ml if g < 0 else (ml[g],)
            best = None
            for mk, (mi, d, reqs) in enumerate(cand):
                t = est
                while True:
                    e = t + d
                    bad = -1
                    for (r, u) in reqs:
                        ar = avail[r]
                        for x in range(e - 1, t - 1, -1):
                            if ar[x] < u:
                                if x > bad:
                                    bad = x
                                break
                    if bad < 0:
                        break
                    t = bad + 1
                f = t + d
                sc = f
                if due[j] is not None and f > due[j]:
                    sc += wt[j] * (f - due[j])
                if rule == 1:
                    sc = sc * 1000 + d * sum(u for _, u in reqs)
                else:
                    sc = sc * 1000 + d
                if best is None or sc < best[0]:
                    best = (sc, t, d, reqs, (mk if g < 0 else g))
            _, t, d, reqs, mk = best
            for (r, u) in reqs:
                ar = avail[r]
                for x in range(t, t + d):
                    ar[x] -= u
            st[j] = t; fin[j] = t + d; mo[j] = mk
            if fin[j] > ms:
                ms = fin[j]
            if due[j] is not None and fin[j] > due[j]:
                cost += wt[j] * (fin[j] - due[j])
            for s in succs[j]:
                cnt[s] -= 1
                if cnt[s] == 0:
                    heapq.heappush(heap, (keys[s], s))
        return cost + ms, st, mo

    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    tail = [0] * n
    for u in reversed(topo):
        tl = 0
        for v in succs[u]:
            if tail[v] > tl:
                tl = tail[v]
        tail[u] = tl + mind[u]
    head = [0] * n
    for u in topo:
        h = rel[u]
        for p in preds[u]:
            if head[p] + mind[p] > h:
                h = head[p] + mind[p]
        head[u] = h
    LB = max([head[i] + mind[i] for i in range(n)] + [0])
    seeds = []
    seeds.append([-float(tail[i]) for i in range(n)])
    seeds.append([float(head[i]) for i in range(n)])
    seeds.append([float((due[i] if due[i] is not None else LB + tail[i]) - tail[i]) for i in range(n)])

    def slackkey(i):
        lst = LB - tail[i]
        if due[i] is not None:
            lst = min(lst, due[i] - tail[i])
        return float(lst) - 0.01 * wt[i]
    seeds.append([slackkey(i) for i in range(n)])
    seeds.append([float(head[i]) - tail[i] for i in range(n)])
    rng = random.Random(12345)
    budget = 0.75
    best = None
    pool = []
    for sk in seeds:
        for rule in (0, 1):
            mg = [-1] * n
            c, st, mo = schedule(sk, mg, rule)
            pool.append((c, sk[:], mg[:], rule))
            if best is None or c < best[0]:
                best = (c, st, mo)
        if time.process_time() - t0 > budget:
            break
    pool.sort(key=lambda x: x[0])
    cur = pool[0]
    curc, keys, mg, rule = cur[0], cur[1][:], cur[2][:], cur[3]

    def norm(kk):
        o = sorted(range(n), key=lambda i: kk[i])
        nk = [0.0] * n
        for r, i in enumerate(o):
            nk[i] = float(r)
        return nk
    keys = norm(keys)
    it = 0
    since = 0
    while best[0] > LB and time.process_time() - t0 < budget:
        it += 1
        nk = keys[:]
        nmg = mg[:]
        nrule = rule
        mv = rng.random()
        if mv < 0.45:
            j = rng.randrange(n)
            nk[j] = rng.uniform(-1, n)
        elif mv < 0.65:
            a = rng.randrange(n); b = rng.randrange(n)
            nk[a], nk[b] = nk[b], nk[a]
        elif mv < 0.9:
            j = rng.randrange(n)
            nmg[j] = rng.randrange(-1, len(modes[j]))
        elif mv < 0.95:
            nrule = 1 - rule
        else:
            for _ in range(3):
                j = rng.randrange(n)
                nk[j] += rng.uniform(-3, 3)
        c, st, mo = schedule(nk, nmg, nrule)
        if c <= curc:
            if c < curc:
                since = 0
            else:
                since += 1
            keys, mg, rule, curc = nk, nmg, nrule, c
            if c < best[0]:
                best = (c, st, mo)
        else:
            since += 1
        if since > 60 + 2 * n:
            pm = pool[rng.randrange(min(len(pool), 4))]
            keys = norm([x + rng.uniform(-2, 2) for x in norm(pm[1])])
            mg = [-1] * n
            rule = pm[3]
            curc, st, mo = schedule(keys, mg, rule)
            if curc < best[0]:
                best = (curc, st, mo)
            since = 0
        if it % 50 == 0:
            keys = norm(keys)
    c, st, mo = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][mo[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = c
    return state

import time, random, heapq

def solve(state, params):
    t0 = time.process_time()
    budget = 0.80
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = (resources[r] or {}).get("calendar") or [[0, 0]]
        cal = sorted([[int(a), int(b)] for a, b in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, x in enumerate(ids):
        jidx[x] = i
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        seen = set()
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "job %s references unknown predecessor %s" % (ids[i], p)}
                return state
            pi = jidx[p]
            if pi in seen:
                continue
            seen.add(pi)
            preds[i].append(pi)
            succs[pi].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        x = q.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            d = int(m.get("duration", 1))
            req = m.get("requires") or {}
            ok = True
            rq = []
            for rn, u in req.items():
                u = int(u)
                if rn not in ridx:
                    ok = False; break
                if u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    rq.append((ridx[rn], u))
            if ok and d >= 0:
                ml.append((mi, d, rq))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    for i in range(n):
        if due[i] is None:
            wt[i] = 0; due[i] = 0
        else:
            due[i] = int(due[i])
    nm = [len(modes[i]) for i in range(n)]
    H = max(lastbp, max(rel)) + sum(max(m[1] for m in modes[i]) for i in range(n)) + 16
    base = []
    for k in range(len(rnames)):
        arr = [0] * H
        cal = cals[k]
        for b in range(len(cal)):
            a = max(0, cal[b][0]); e = cal[b + 1][0] if b + 1 < len(cal) else H
            e = min(e, H)
            c = cal[b][1]
            for t in range(a, e):
                arr[t] = c
        base.append(arr)

    def decode(order, mvec):
        av = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        cm = list(mvec) if mvec is not None else [0] * n
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            if mvec is not None:
                cand = (modes[j][mvec[j]],)
            else:
                cand = modes[j]
            best = None
            for mk, m in enumerate(cand):
                d = m[1]; rq = [(av[r], u) for r, u in m[2]]
                s = est
                if rq:
                    while True:
                        t = s; e = s + d; okk = True
                        while t < e:
                            for a, u in rq:
                                if a[t] < u:
                                    okk = False; break
                            if not okk:
                                break
                            t += 1
                        if okk:
                            break
                        s = t + 1
                f = s + d
                sc = f + (wt[j] * (f - due[j]) if f > due[j] else 0) * 1.0
                if mvec is None:
                    sc = sc * 1000 + sum(u for _, u in m[2]) * d * 0.01
                if best is None or sc < best[0]:
                    best = (sc, s, mk)
            s = best[1]
            mk = best[2] if mvec is None else mvec[j]
            m = modes[j][mk]
            d = m[1]
            for r, u in m[2]:
                a = av[r]
                for t in range(s, s + d):
                    a[t] -= u
            st[j] = s; fin[j] = s + d; cm[j] = mk
        ms = max(fin)
        c = ms
        for j in range(n):
            if wt[j] and fin[j] > due[j]:
                c += wt[j] * (fin[j] - due[j])
        return c, st, cm

    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            e = max(e, es[p] + mind[p])
        es[j] = e
    cp = max(es[j] + mind[j] for j in range(n))
    lf = [0] * n
    for j in reversed(topo):
        l = cp
        for s in succs[j]:
            l = min(l, lf[s] - mind[s])
        if wt[j] > 0:
            l = min(l, due[j])
        lf[j] = l
    nsucc = [0] * n
    for j in reversed(topo):
        nsucc[j] = len(succs[j]) + sum(nsucc[s] for s in succs[j]) * 0.5

    def list_from_prio(key, noise=0.0, rng=None):
        indeg2 = [len(preds[i]) for i in range(n)]
        h = []
        for i in range(n):
            if indeg2[i] == 0:
                k = key(i) + (rng.random() * noise if noise else 0)
                heapq.heappush(h, (k, i))
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    k = key(s) + (rng.random() * noise if noise else 0)
                    heapq.heappush(h, (k, s))
        return out

    rng = random.Random(12345)
    keys = [
        lambda i: (lf[i], es[i]),
        lambda i: (lf[i] - mind[i], i),
        lambda i: (es[i], lf[i]),
        lambda i: (max(rel[i], es[i]) + lf[i], i),
        lambda i: (-nsucc[i], lf[i]),
        lambda i: (lf[i] - 3 * wt[i], es[i]),
    ]
    best = None

    def consider(order, mvec):
        nonlocal best
        c, st, cm = decode(order, mvec)
        if best is None or c < best[0]:
            best = (c, list(order), cm, st)
        return c, cm

    for k in keys:
        consider(list_from_prio(k), None)
    span = max(1, cp)
    it = 0
    while time.process_time() - t0 < budget * 0.25 and it < 60:
        it += 1
        nz = span * rng.choice([0.05, 0.1, 0.2, 0.4])
        kk = rng.randrange(3)
        if kk == 0:
            o = list_from_prio(lambda i: lf[i], nz, rng)
        elif kk == 1:
            o = list_from_prio(lambda i: lf[i] - mind[i], nz, rng)
        else:
            o = list_from_prio(lambda i: lf[i] + es[i], nz, rng)
        consider(o, None)

    cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
    multi = [i for i in range(n) if nm[i] > 1]
    stall = 0
    while time.process_time() - t0 < budget:
        o = cur_o[:]
        m = cur_m[:]
        nmoves = 1 if stall < 60 else rng.randint(2, 4)
        for _ in range(nmoves):
            r = rng.random()
            if multi and r < 0.3:
                j = rng.choice(multi)
                m[j] = rng.choice([x for x in range(nm[j]) if x != m[j]])
            else:
                i = rng.randrange(n)
                j = o.pop(i)
                pos = {}
                for k2, x in enumerate(o):
                    pos[x] = k2
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo:
                        lo = pos[p] + 1
                hi = n - 1
                for s in succs[j]:
                    if pos[s] < hi:
                        hi = pos[s]
                if r < 0.6 and max(lo, i - 6) <= min(hi, i + 6):
                    k2 = rng.randint(max(lo, i - 6), min(hi, i + 6))
                else:
                    k2 = rng.randint(lo, hi)
                o.insert(k2, j)
        c, st, cm = decode(o, m)
        if c <= cur_c:
            if c < cur_c:
                stall = 0
            else:
                stall += 1
            cur_c, cur_o, cur_m = c, o, m
            if c < best[0]:
                best = (c, o[:], m[:], st)
        else:
            stall += 1
        if stall > 400:
            cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]
            stall = 0
    c, order, cm, st = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][cm[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = c
    return state

