            ok = True
            rq = []
            for rn, u in req.items():
                u = int(u)
                if rn not in ridx:
                    ok = False; break
                if u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    rq.append((ridx[rn], u))
            if ok and d >= 0:
                ml.append((mi, d, rq))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
