        modes.append(ml)
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    for i in range(n):
        if due[i] is None:
            wt[i] = 0; due[i] = 0
        else:
            due[i] = int(due[i])
    nm = [len(modes[i]) for i in range(n)]
    H = max(lastbp, max(rel)) + sum(max(m[1] for m in modes[i]) for i in range(n)) + 16
    base = []
    for k in range(len(rnames)):
        arr = [0] * H
        cal = cals[k]
        for b in range(len(cal)):
            a = max(0, cal[b][0]); e = cal[b + 1][0] if b + 1 < len(cal) else H
            e = min(e, H)
            c = cal[b][1]
            for t in range(a, e):
                arr[t] = c
        base.append(arr)

    def decode(order, mvec):
        av = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        cm = list(mvec) if mvec is not None else [0] * n
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            if mvec is not None:
                cand = (modes[j][mvec[j]],)
            else:
                cand = modes[j]
            best = None
            for mk, m in enumerate(cand):
                d = m[1]; rq = [(av[r], u) for r, u in m[2]]
                s = est
                if rq:
                    while True:
                        t = s; e = s + d; okk = True
                        while t < e:
                            for a, u in rq:
                                if a[t] < u:
                                    okk = False; break
                            if not okk:
                                break
                            t += 1
                        if okk:
                            break
                        s = t + 1
                f = s + d
                sc = f + (wt[j] * (f - due[j]) if f > due[j] else 0) * 1.0
                if mvec is None:
                    sc = sc * 1000 + sum(u for _, u in m[2]) * d * 0.01
                if best is None or sc < best[0]:
                    best = (sc, s, mk)
            s = best[1]
            mk = best[2] if mvec is None else mvec[j]
            m = modes[j][mk]
            d = m[1]
            for r, u in m[2]:
                a = av[r]
                for t in range(s, s + d):
                    a[t] -= u
            st[j] = s; fin[j] = s + d; cm[j] = mk
        ms = max(fin)
        c = ms
        for j in range(n):
            if wt[j] and fin[j] > due[j]:
                c += wt[j] * (fin[j] - due[j])
        return c, st, cm

    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    es = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            e = max(e, es[p] + mind[p])
        es[j] = e
    cp = max(es[j] + mind[j] for j in range(n))
    lf = [0] * n
    for j in reversed(topo):
        l = cp
        for s in succs[j]:
            l = min(l, lf[s] - mind[s])
        if wt[j] > 0:
            l = min(l, due[j])
        lf[j] = l
    nsucc = [0] * n
    for j in reversed(topo):
        nsucc[j] = len(succs[j]) + sum(nsucc[s] for s in succs[j]) * 0.5

    def mkkey(key, i, noise, rng):
        k = key(i)
        if not isinstance(k, tuple):
            k = (k,)
        add = rng.random() * noise if (noise and rng is not None) else 0.0
        return (float(k[0]) + add,) + tuple(k[1:]) + (i,)

    def list_from_prio(key, noise=0.0, rng=None):
        indeg2 = [len(preds[i]) for i in range(n)]
        h = []
        for i in range(n):
            if indeg2[i] == 0:
                heapq.heappush(h, (mkkey(key, i, noise, rng), i))
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    heapq.heappush(h, (mkkey(key, s, noise, rng), s))
        return out

    rng = random.Random(12345)
    keys = [
        lambda i: (lf[i], es[i]),
