                m[j] = rng.choice([x for x in range(nm[j]) if x != m[j]])
            else:
                i = rng.randrange(n)
                j = o.pop(i)
                pos = {}
                for k2, x in enumerate(o):
                    pos[x] = k2
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo:
