                hi = n - 1
                for s in succs[j]:
                    if pos[s] < hi:
                        hi = pos[s]
                if hi < lo:
                    hi = lo
                if r < 0.6 and max(lo, i - 6) <= min(hi, i + 6):
                    k2 = rng.randint(max(lo, i - 6), min(hi, i + 6))
                else:
                    k2 = rng.randint(lo, hi)
                o.insert(k2, j)
        c, st, cm = decode(o, m)
        if c <= cur_c:
