import time, random, heapq


def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.72
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {nm: i for i, nm in enumerate(rnames)}
    R = len(rnames)
    cals = []
    maxcap = []
    for nm in rnames:
        cal = (resources[nm] or {}).get("calendar") or [[0, 0]]
        cal = sorted([[int(a), int(b)] for a, b in cal])
        cals.append(cal)
        maxcap.append(max(c for _, c in cal))
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        seen = set()
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "unknown predecessor %s of job %s" % (p, ids[i])}
                return state
            k = jidx[p]
            if k not in seen:
                seen.add(k)
                preds[i].append(k)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    q = 0
    while q < len(topo):
        u = topo[q]; q += 1
        for s in succs[u]:
            indeg[s] -= 1
            if indeg[s] == 0:
                topo.append(s)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            d = int(m.get("duration", 1))
            req = []
            ok = True
            for rn, u in (m.get("requires") or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False; break
                if u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    req.append((ridx[rn], u))
            if ok and d >= 0:
                ml.append((mi, d, req))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    rel = [max(0, int(j.get("release") or 0)) for j in jobs]
    due = [None if j.get("due") is None else int(j.get("due")) for j in jobs]
    wt = [int(j.get("weight") or 0) for j in jobs]
    lastbp = max([cal[-1][0] for cal in cals] + [0])
    H = max(lastbp, max(rel)) + sum(max(m[1] for m in ml) for ml in modes) + 2
    base = []
    for r in range(R):
        cal = cals[r]
        arr = [0] * H
        for k in range(len(cal)):
            a = cal[k][0]
            b = cal[k + 1][0] if k + 1 < len(cal) else H
            a = max(0, min(a, H)); b = max(0, min(b, H))
            c = cal[k][1]
            for t in range(a, b):
                arr[t] = c
        base.append(arr)
    lastcap = [cals[r][-1][1] for r in range(R)]
    mind = [min(m[1] for m in ml) for ml in modes]
    tail = [0] * n
    for u in reversed(topo):
        b = 0
        for s in succs[u]:
            if tail[s] > b: b = tail[s]
        tail[u] = mind[u] + b
    head = [0] * n
    for u in topo:
        h = rel[u]
        for p in preds[u]:
            v = head[p] + mind[p]
            if v > h: h = v
        head[u] = h
    cpl = max(head[i] + tail[i] for i in range(n))
    BIG = 10 ** 9
    dd = [BIG] * n
    for u in reversed(topo):
        v = due[u] if due[u] is not None else BIG
        for s in succs[u]:
            x = dd[s] - mind[s]
            if x < v: v = x
        dd[u] = v
    mload = []
    for i in range(n):
        ml = []
        for (mi, d, req) in modes[i]:
            l = 0.0
            for (r, u) in req:
                l += u / float(maxcap[r] if maxcap[r] > 0 else 1)
            ml.append(l * d)
        mload.append(ml)

    def cost_of(st, fin):
        c = max(fin)
        for i in range(n):
            if due[i] is not None and fin[i] > due[i]:
                c += wt[i] * (fin[i] - due[i])
        return c

    def find(free, t, d, req):
        while True:
            moved = False
            for (r, u) in req:
                f = free[r]
                if t + d > len(f):
                    for rr in range(R):
                        free[rr].extend([lastcap[rr]] * (t + d - len(free[rr]) + 16))
                    f = free[r]
                k = t + d - 1
                while k >= t:
                    if f[k] < u:
                        break
                    k -= 1
                if k >= t:
                    t = k + 1
                    moved = True
                    break
            if not moved:
                return t

    def place(free, t, d, req):
        for (r, u) in req:
            f = free[r]
            for k in range(t, t + d):
                f[k] -= u

    def decode_fixed(order, mv):
        free = [a[:] for a in base]
        st = [0] * n; fin = [0] * n
        for i in order:
            t = rel[i]
            for p in preds[i]:
                if fin[p] > t: t = fin[p]
            mi, d, req = modes[i][mv[i]]
            t = find(free, t, d, req)
            place(free, t, d, req)
            st[i] = t; fin[i] = t + d
        return st, fin

    def decode_greedy(order, lam):
        free = [a[:] for a in base]
        st = [0] * n; fin = [0] * n; mv = [0] * n
        for i in order:
            t0 = rel[i]
            for p in preds[i]:
                if fin[p] > t0: t0 = fin[p]
            bb = None
            ml = modes[i]
            for k in range(len(ml)):
                mi, d, req = ml[k]
                t = find(free, t0, d, req)
                f = t + d
                sc = f + lam * mload[i][k]
                if due[i] is not None and f > due[i]:
                    sc += wt[i] * (f - due[i])
                if bb is None or sc < bb[0]:
                    bb = (sc, k, t)
            sc, k, t = bb
            mi, d, req = ml[k]
            place(free, t, d, req)
            st[i] = t; fin[i] = t + d; mv[i] = k
        return st, fin, mv

    def make_order(key):
        indg = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if indg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, u = heapq.heappop(h)
            out.append(u)
            for s in succs[u]:
                indg[s] -= 1
                if indg[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    rng = random.Random(12345)
    best = None

    def consider(st, fin, mv):
        nonlocal best
        c = cost_of(st, fin)
        if best is None or c < best[0]:
            best = (c, st[:], fin[:], mv[:])
        return c

    lst = [cpl - tail[i] for i in range(n)]
    lsd = [(dd[i] - mind[i]) if dd[i] < BIG else BIG for i in range(n)]

    def rule_key(rule, noise):
        key = []
        for i in range(n):
            if rule == 0:
                k = lst[i]
            elif rule == 1:
                k = min(lst[i], lsd[i]) if lsd[i] < BIG else lst[i]
            elif rule == 2:
                k = min(lst[i], lsd[i] - 0.5 * wt[i]) if lsd[i] < BIG else lst[i]
            elif rule == 3:
                k = head[i]
            else:
                k = -tail[i] * 1.0 - len(succs[i])
            if noise > 0:
                k = k + rng.uniform(-noise, noise) * (1 + cpl * 0.1)
            key.append((k, -tail[i], i))
        return key

    lams = [0.0, 0.5, 1.0, 2.0]
    it = 0
    cons_budget = BUDGET * 0.35
    while True:
        stop = False
        for rule in range(5):
            for lam in lams:
                noise = 0.0 if it == 0 else rng.choice([0.5, 1.0, 2.0, 4.0])
                order = make_order(rule_key(rule, noise))
                st, fin, mv = decode_greedy(order, lam)
                consider(st, fin, mv)
                if time.process_time() - T0 > cons_budget and it > 0:
                    stop = True
                    break
            if stop:
                break
        it += 1
        if time.process_time() - T0 > cons_budget:
            break

    def order_from(st):
        return sorted(range(n), key=lambda i: (st[i], -tail[i]))

    cur_c, cur_st, cur_fin, cur_mv = best
    cur_mv = cur_mv[:]
    cur_order = order_from(cur_st)
    temp = max(1.0, 0.02 * cur_c)
    iters = 0
    last_imp = 0
    multi = [i for i in range(n) if len(modes[i]) > 1]
    while time.process_time() - T0 < BUDGET:
        iters += 1
        order = cur_order[:]
        mv = cur_mv[:]
        mtype = rng.random()
        if mtype < 0.25:
            if multi:
                i = rng.choice(multi)
                k = rng.randrange(len(modes[i]) - 1)
                if k >= mv[i]: k += 1
                mv[i] = k
            else:
                mtype = 0.5
        if mtype >= 0.25:
            pos = {u: p for p, u in enumerate(order)}
            i = rng.randrange(n)
            p = pos[i]
            lo = max([pos[x] for x in preds[i]] + [-1]) + 1
            hi = min([pos[x] for x in succs[i]] + [n]) - 1
            if hi > lo:
                if rng.random() < 0.5:
                    span = 6
                    np_ = rng.randint(max(lo, p - span), min(hi, p + span))
                else:
                    np_ = rng.randint(lo, hi)
                order.pop(p)
                order.insert(np_, i)
                if mtype > 0.85 and len(modes[i]) > 1:
                    mv[i] = rng.randrange(len(modes[i]))
        st, fin = decode_fixed(order, mv)
        c = cost_of(st, fin)
        if c <= cur_c or rng.random() < pow(2.718281828, -(c - cur_c) / temp):
            cur_c = c; cur_mv = mv; cur_order = order_from(st)
            if c < best[0]:
                best = (c, st[:], fin[:], mv[:])
                last_imp = iters
        temp = max(0.3, temp * 0.995)
        if iters - last_imp > 300:
            cur_c, cur_st, cur_fin, cur_mv = best[0], best[1], best[2], best[3][:]
            cur_order = order_from(cur_st)
            temp = max(1.0, 0.02 * cur_c)
            last_imp = iters
    c, st, fin, mv = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][mv[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = c
    return state

import time, random, heapq

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = resources[r].get("calendar", [[0, 0]]) or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {s: i for i, s in enumerate(ids)}
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "unknown predecessor %s of job %s" % (p, ids[i])}
                return state
            preds[i].append(jidx[p])
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        ps = sorted(set(preds[i]))
        preds[i] = ps
        for p in ps:
            succs[p].append(i)
            indeg[i] += 1
    deg = indeg[:]
    topo = [i for i in range(n) if deg[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]; k += 1
        for v in succs[u]:
            deg[v] -= 1
            if deg[v] == 0:
                topo.append(v)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []
    release = []
    due = []
    weight = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            d = int(m["duration"])
            req = m.get("requires", {}) or {}
            ok = True
            rq = []
            load = 0.0
            for r, u in req.items():
                u = int(u)
                if u <= 0:
                    continue
                if r not in ridx or u > maxcap[ridx[r]]:
                    ok = False; break
                rq.append((ridx[r], u))
                load += d * u / max(1, maxcap[ridx[r]])
            if ok:
                ml.append((mi, d, rq, load))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
        release.append(max(0, int(j.get("release", 0) or 0)))
        dd = j.get("due")
        due.append(None if dd is None else int(dd))
        weight.append(int(j.get("weight", 0) or 0))
    H = max(lastbp, max(release) if release else 0) + sum(max(m[1] for m in ml) for ml in modes) + 20
    base = []
    for cal in cals:
        arr = [0] * H
        for k2, (a, c) in enumerate(cal):
            b = cal[k2 + 1][0] if k2 + 1 < len(cal) else H
            a = max(0, min(a, H)); b = max(0, min(b, H))
            for t in range(a, b):
                arr[t] = c
        base.append(arr)
    duet = [(i, due[i], weight[i]) for i in range(n) if due[i] is not None and weight[i] > 0]

    def decode(keys, mvec):
        avail = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        md = [0] * n
        dg = indeg[:]
        heap = [(keys[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(heap)
        while heap:
            _, j = heapq.heappop(heap)
            est = release[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            mj = mvec[j]
            best = None
            for mk in (range(len(modes[j])) if mj < 0 else (mj,)):
                _, d, rq, load = modes[j][mk]
                t = est
                while True:
                    ok = True
                    for (r, u) in rq:
                        a = avail[r]
                        for s in range(t, t + d):
                            if a[s] < u:
                                ok = False; t = s + 1; break
                        if not ok:
                            break
                    if ok:
                        break
                f = t + d
                if best is None or f < best[0] or (f == best[0] and load < best[3]):
                    best = (f, t, mk, load)
            f, t, mk, _ = best
            for (r, u) in modes[j][mk][2]:
                a = avail[r]
                for s in range(t, f):
                    a[s] -= u
            st[j] = t; fin[j] = f; md[j] = mk
            for v in succs[j]:
                dg[v] -= 1
                if dg[v] == 0:
                    heapq.heappush(heap, (keys[v], v))
        c = max(fin) if n else 0
        for (i, dd, w) in duet:
            if fin[i] > dd:
                c += w * (fin[i] - dd)
        return c, st, md

    mind = [min(m[1] for m in ml) for ml in modes]
    es = [0] * n
    for u in topo:
        e = release[u]
        for p in preds[u]:
            e = max(e, es[p] + mind[p])
        es[u] = e
    T = max(es[i] + mind[i] for i in range(n)) if n else 0
    lf = [T] * n
    for u in reversed(topo):
        v = T
        if due[u] is not None:
            v = min(v, due[u])
        for s in succs[u]:
            v = min(v, lf[s] - mind[s])
        lf[u] = v
    ls = [lf[i] - mind[i] for i in range(n)]
    nsucc = [0] * n
    for u in reversed(topo):
        nsucc[u] = len(succs[u]) + sum(nsucc[s] for s in succs[u]) // 2
    rules = [
        [lf[i] + 0.001 * i for i in range(n)],
        [ls[i] + 0.001 * i for i in range(n)],
        [es[i] + 0.001 * ls[i] for i in range(n)],
        [ls[i] - 0.5 * weight[i] - 0.01 * nsucc[i] for i in range(n)],
        [-nsucc[i] + 0.001 * ls[i] for i in range(n)],
        [(due[i] if due[i] is not None else T + es[i]) - weight[i] for i in range(n)],
    ]
    rng = random.Random(12345)
    budget = 0.78
    best = None
    greedy = [-1] * n

    def tm():
        return time.process_time() - t0

    mvecs = [greedy,
             [min(range(len(modes[i])), key=lambda k: (modes[i][k][1], modes[i][k][3])) for i in range(n)],
             [min(range(len(modes[i])), key=lambda k: (modes[i][k][3], modes[i][k][1])) for i in range(n)]]
    for mv in mvecs:
        for kk in rules:
            if best is not None and tm() > budget * 0.4:
                break
            c, st, md = decode(kk, mv)
            if best is None or c < best[0]:
                best = (c, kk[:], mv[:], st, md)
    cur = best
    it = 0
    temp = max(1.0, best[0] * 0.02)
    while tm() < budget:
        it += 1
        c0, k0, m0, st0, md0 = cur
        keys = [st0[i] + rng.random() * 0.5 for i in range(n)]
        mv = m0[:]
        nm = rng.randint(1, 3)
        for _ in range(nm):
            r = rng.random()
            j = rng.randrange(n)
            if r < 0.55:
                keys[j] -= rng.randint(1, 12)
            elif r < 0.7:
                keys[j] += rng.randint(1, 12)
            elif r < 0.85:
                j2 = rng.randrange(n)
                keys[j], keys[j2] = keys[j2], keys[j]
            else:
                L = len(modes[j])
                mv[j] = rng.choice([-1] + list(range(L)))
        c, st, md = decode(keys, mv)
        if c < best[0]:
            best = (c, keys, mv, st, md)
        if c <= c0 or rng.random() < pow(2.718, -(c - c0) / temp):
            cur = (c, keys, mv, st, md)
        temp = max(0.5, temp * 0.995)
        if it % 200 == 0:
            cur = best
    c, _, _, st, md = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][md[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time
import random
import heapq


def solve(state, params):
    t0 = time.process_time()
    budget = 0.72
    inp = state["input"]
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    ids = [str(j["id"]) for j in jobs]
    idx = {}
    for i, s in enumerate(ids):
        idx[s] = i
    rnames = list(resources.keys())
    rix = {r: k for k, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = (resources[r] or {}).get("calendar", [[0, 0]]) or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in idx:
                state["output"] = {"status": "infeasible",
                                   "reason": "unknown predecessor %s of job %s" % (p, ids[i])}
                return state
            q = idx[p]
            if q not in preds[i]:
                preds[i].append(q)
                succs[q].append(i)
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            d = int(m["duration"])
            ok = True
            req = []
            for rn, u in (m.get("requires", {}) or {}).items():
                u = int(u)
                if rn not in rix:
                    ok = False
                    break
                if u > maxcap[rix[rn]]:
                    ok = False
                    break
                if u > 0:
                    req.append((rix[rn], u))
            if ok:
                ml.append((mi, max(d, 0), req))
        if not ml:
            state["output"] = {"status": "infeasible",
                               "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
    indeg = [len(preds[i]) for i in range(n)]
    stack = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while stack:
        x = stack.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state

    release = [int(j.get("release", 0) or 0) for j in jobs]
    due = [j.get("due") for j in jobs]
    due = [None if d is None else int(d) for d in due]
    weight = [int(j.get("weight", 0) or 0) for j in jobs]
    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    maxd = [max(m[1] for m in modes[i]) for i in range(n)]
    H = max(lastbp, max(release)) + sum(maxd) + 16
    caparr = []
    for k in range(len(rnames)):
        cal = cals[k]
        arr = [0] * H
        for bi in range(len(cal)):
            a = cal[bi][0]
            b = cal[bi + 1][0] if bi + 1 < len(cal) else H
            a = max(a, 0)
            b = min(b, H)
            c = cal[bi][1]
            for t in range(a, b):
                arr[t] = c
        caparr.append(arr)
    nm = [len(modes[i]) for i in range(n)]
    area = []
    for i in range(n):
        al = []
        for (mi, d, req) in modes[i]:
            s = 0.0
            for (k, u) in req:
                s += u / max(1, maxcap[k])
            al.append(s * d)
        area.append(al)

    es = [0] * n
    for x in topo:
        e = release[x]
        for p in preds[x]:
            v = es[p] + mind[p]
            if v > e:
                e = v
        es[x] = e
    cpl = max(es[i] + mind[i] for i in range(n))
    lf = [0] * n
    for x in reversed(topo):
        v = cpl
        for s in succs[x]:
            w = lf[s] - mind[s]
            if w < v:
                v = w
        lf[x] = v
    BIG = 10 ** 7
    dl = [BIG] * n
    for x in reversed(topo):
        v = due[x] if due[x] is not None else BIG
        for s in succs[x]:
            w = dl[s] - mind[s]
            if w < v:
                v = w
        dl[x] = v
    tail = [0] * n
    for x in reversed(topo):
        v = 0
        for s in succs[x]:
            if tail[s] + mind[s] > v:
                v = tail[s] + mind[s]
        tail[x] = v
    wsum = [0] * n
    for x in reversed(topo):
        v = weight[x] if due[x] is not None else 0
        for s in succs[x]:
            v += wsum[s]
        wsum[x] = min(v, 10 ** 6)

    def find_start(arrs_rem, e, d, req):
        t = e
        if not req or d == 0:
            return t
        while True:
            ok = True
            end = t + d
            for (k, u) in req:
                a = arrs_rem[k]
                if end > len(a):
                    a.extend([maxcap[k]] * (end - len(a) + 64))
                tt = t
                while tt < end:
                    if a[tt] < u:
                        ok = False
                        break
                    tt += 1
                if not ok:
                    t = tt + 1
                    break
            if ok:
                return t

    def decode(order, mvec, alpha):
        rem = [a[:] for a in caparr]
        fin = [0] * n
        st = [0] * n
        md = [0] * n
        cost = 0
        mk = 0
        for x in order:
            e = release[x]
            for p in preds[x]:
                if fin[p] > e:
                    e = fin[p]
            if mvec is not None and mvec[x] >= 0:
                m = mvec[x]
                d = modes[x][m][1]
                req = modes[x][m][2]
                s = find_start(rem, e, d, req)
            else:
                best = None
                for m in range(nm[x]):
                    d = modes[x][m][1]
                    req = modes[x][m][2]
                    s0 = find_start(rem, e, d, req)
                    f = s0 + d
                    sc = f + alpha * area[x][m]
                    if due[x] is not None and f > due[x]:
                        sc += weight[x] * (f - due[x])
                    if best is None or sc < best[0]:
                        best = (sc, m, s0)
                m = best[1]
                s = best[2]
                d = modes[x][m][1]
                req = modes[x][m][2]
            for (k, u) in req:
                a = rem[k]
                if s + d > len(a):
                    a.extend([maxcap[k]] * (s + d - len(a) + 64))
                for t in range(s, s + d):
                    a[t] -= u
            st[x] = s
            md[x] = m
            f = s + d
            fin[x] = f
            if f > mk:
                mk = f
            if due[x] is not None and f > due[x]:
                cost += weight[x] * (f - due[x])
        return cost + mk, st, md

    def order_from_key(key):
        indeg2 = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if indeg2[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    heapq.heappush(h, (key[s], s))
        return out

    rng = random.Random(12345)
    best = None

    def consider(order, res):
        nonlocal best
        c, st, md = res
        if best is None or c < best[0]:
            best = (c, st[:], md[:], order[:])
            return True
        return False

    keys = []
    keys.append([(min(dl[i], lf[i] + BIG // 2), es[i]) for i in range(n)])
    keys.append([(lf[i], dl[i]) for i in range(n)])
    keys.append([(es[i], lf[i]) for i in range(n)])
    keys.append([(-tail[i] - mind[i], lf[i]) for i in range(n)])
    keys.append([(dl[i] if dl[i] < BIG else lf[i] + cpl, -wsum[i]) for i in range(n)])
    keys.append([(lf[i] - 3 * min(wsum[i], 50), es[i]) for i in range(n)])
    keys.append([(release[i], dl[i]) for i in range(n)])
    keys.append([(min(lf[i], dl[i]), -tail[i]) for i in range(n)])
    stop = False
    for k in keys:
        o = order_from_key(k)
        for alpha in (0.0, 0.3, 1.0):
            consider(o, decode(o, None, alpha))
            if time.process_time() - t0 > budget * 0.5:
                stop = True
                break
        if stop:
            break

    pos = [0] * n
    cur_order = best[3][:]
    cur_modes = best[2][:]
    cur_cost = best[0]
    it = 0
    stale = 0
    multi = [i for i in range(n) if nm[i] > 1]
    while True:
        it += 1
        if (it & 3) == 0 and time.process_time() - t0 > budget:
            break
        new_order = cur_order
        new_modes = cur_modes
        r = rng.random()
        if not multi and r < 0.3:
            r = 0.3 + 0.7 * rng.random()
        if r < 0.3:
            new_modes = cur_modes[:]
            for _ in range(1 if rng.random() < 0.7 else 2):
                x = rng.choice(multi)
                m = rng.randrange(nm[x] - 1)
                if m >= new_modes[x]:
                    m += 1
                new_modes[x] = m
        elif r < 0.4:
            new_modes = None
        if r >= 0.3:
            new_order = cur_order[:]
            cnt = 1 if rng.random() < 0.6 else rng.randint(2, 4)
            for _ in range(cnt):
                for i, x in enumerate(new_order):
                    pos[x] = i
                x = new_order[rng.randrange(n)]
                lo = 0
                for p in preds[x]:
                    if pos[p] + 1 > lo:
                        lo = pos[p] + 1
                hi = n - 1
                for s in succs[x]:
                    if pos[s] - 1 < hi:
                        hi = pos[s] - 1
                px = pos[x]
                if hi <= lo:
                    continue
                np_ = rng.randint(lo, hi)
                if np_ == px:
                    continue
                del new_order[px]
                new_order.insert(np_, x)
        if new_modes is None:
            res = decode(new_order, None, rng.choice((0.0, 0.3, 1.0)))
            res_modes = res[2]
        else:
            res = decode(new_order, new_modes, 0.0)
            res_modes = new_modes
        c = res[0]
        if c <= cur_cost or (stale > 300 and rng.random() < 0.05):
            if c < cur_cost:
                stale = 0
            else:
                stale += 1
            st = res[1]
            # durations >= 1, so sorting by start keeps precedence feasibility
            if all(modes[z][res_modes[z]][1] > 0 for z in range(n)):
                cur_order = sorted(new_order, key=lambda z: st[z])
            else:
                cur_order = new_order
            cur_modes = res_modes[:]
            cur_cost = c
            consider(cur_order, res)
        else:
            stale += 1
        if stale > 600:
            cur_order = best[3][:]
            cur_modes = best[2][:]
            cur_cost = best[0]
            stale = 0

    c, st, md, _ = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][md[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["debug_cost"] = c
    state["debug_iters"] = it
    return state

