        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    deg = indeg[:]
    h = 0
    while h < len(topo):
        u = topo[h]
        h += 1
        for v in succs[u]:
            deg[v] -= 1
            if deg[v] == 0:
                topo.append(v)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence relation has a cycle"}
        return state

    modes = []  # per job: list of (orig_idx, dur, [(r,u)], area)
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            d = int(m.get("duration", 1))
            req = m.get("requires") or {}
            ok = True
            rl = []
            for rn, u in req.items():
                u = int(u)
                if rn not in ridx or u > maxcap[ridx[rn]]:
                    ok = False
                    break
                if u > 0:
                    rl.append((ridx[rn], u))
            if ok:
                area = sum(float(u) / max(1, maxcap[r]) for r, u in rl) * d
                ml.append((mi, d, rl, area))
        if not ml:
            state["output"] = {"status": "infeasible",
                               "reason": "job %s has no executable mode" % ids[i]}
            return state
        modes.append(ml)

    rel = [max(0, int(j.get("release") or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight") or 0) for j in jobs]
    hasdue = [due[i] is not None and wt[i] > 0 for i in range(n)]

    # ---------- capacity arrays ----------
    H = lastbp + max(rel) + sum(max(m[1] for m in modes[i]) for i in range(n)) + 20
    base = []
    for r in range(len(rnames)):
        arr = [0] * H
        cal = cals[r]
        for k in range(len(cal)):
            a = cal[k][0]
            b = cal[k + 1][0] if k + 1 < len(cal) else H
            a = max(0, min(a, H))
            b = max(0, min(b, H))
            c = cal[k][1]
            for t in range(a, b):
                arr[t] = c
        base.append(arr)

    # ---------- priority information ----------
    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    es = [0] * n
    for u in topo:
        e = rel[u]
        for p in preds[u]:
            if es[p] + mind[p] > e:
                e = es[p] + mind[p]
        es[u] = e
    hor = max(es[i] + mind[i] for i in range(n))
    BIG = 10 ** 9
    lf = [hor] * n
    lfd = [BIG] * n
    for u in reversed(topo):
        for s in succs[u]:
            if lf[s] - mind[s] < lf[u]:
                lf[u] = lf[s] - mind[s]
            if lfd[s] < BIG // 2 and lfd[s] - mind[s] < lfd[u]:
                lfd[u] = lfd[s] - mind[s]
        if hasdue[u] and due[u] < lfd[u]:
            lfd[u] = int(due[u])
    nsucc = [0.0] * n
    for u in reversed(topo):
        v = len(succs[u]) + 0.5 * sum(nsucc[s] for s in succs[u])
        nsucc[u] = min(v, float(hor))

    def sgs(keys, mg):
        avail = [a[:] for a in base]
        fin = [0] * n
        st = [0] * n
        mo = [0] * n
        dg = indeg[:]
        hp = [(keys[i], i) for i in range(n) if dg[i] == 0]
        heapq.heapify(hp)
        cost = 0
        mk = 0
        while hp:
            _, u = heapq.heappop(hp)
            e = rel[u]
            for p in preds[u]:
                if fin[p] > e:
                    e = fin[p]
            ml = modes[u]
            g = mg[u]
            if g < 0:
                cand = list(range(len(ml)))
            else:
                cand = [g]
            bf = None
            for k in cand:
                md = ml[k]
                d = md[1]
                rl = md[2]
                t = e
                while True:
                    ok = True
                    for r, q in rl:
                        arr = avail[r]
                        for tt in range(t, t + d):
                            if arr[tt] < q:
                                t = tt + 1
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        break
                f = t + d
                if bf is None or f < bf[0] or (f == bf[0] and md[3] < bf[1]):
                    bf = (f, md[3], t, k)
            f, _, t, k = bf
            for r, q in ml[k][2]:
                arr = avail[r]
                for tt in range(t, f):
                    arr[tt] -= q
            fin[u] = f
            st[u] = t
            mo[u] = k
            if f > mk:
                mk = f
            if hasdue[u] and f > due[u]:
                cost += wt[u] * (f - due[u])
            for s in succs[u]:
                dg[s] -= 1
                if dg[s] == 0:
                    heapq.heappush(hp, (keys[s], s))
        return cost + mk, st, mo

    rng = random.Random(12345)
    best = {"c": None, "st": None, "mo": None, "k": None, "m": None}

    def consider(keys, mg):
        c, st, mo = sgs(keys, mg)
        if best["c"] is None or c < best["c"]:
            best["c"] = c
            best["st"] = st
            best["mo"] = mo
            best["k"] = keys[:]
            best["m"] = mg[:]
        return c

    def left():
        return BUDGET - (time.process_time() - T0)

    greedy = [-1] * n
    variants = []
    variants.append([float(lf[i]) for i in range(n)])
    variants.append([float(min(lf[i], lfd[i])) for i in range(n)])
    variants.append([float(min(lf[i], lfd[i]) - mind[i]) for i in range(n)])
    variants.append([float(lfd[i]) if lfd[i] < BIG // 2 else float(lf[i] + hor) for i in range(n)])
    variants.append([float(es[i]) + i * 1e-6 for i in range(n)])
    variants.append([float(lf[i]) - 0.5 * nsucc[i] for i in range(n)])
    variants.append([float(min(lf[i], lfd[i])) - (wt[i] if hasdue[i] else 0) for i in range(n)])

    for v in variants:
        if best["c"] is not None and left() < 0.05:
            break
        consider(v, greedy)

    # ---------- randomized sampling ----------
    nrand = 0
    while left() > BUDGET * 0.6 and nrand < 60:
        nrand += 1
        b = variants[rng.randrange(len(variants))]
        sc = hor * rng.uniform(0.02, 0.3)
        keys = [b[i] + rng.uniform(0, sc) for i in range(n)]
        mg = greedy[:]
        if rng.random() < 0.3:
            for i in range(n):
                if len(modes[i]) > 1 and rng.random() < 0.1:
                    mg[i] = rng.randrange(len(modes[i]))
        consider(keys, mg)

    # ---------- local search on random keys / mode genes ----------
    cur_c = best["c"]
    cur_k = best["k"][:]
    cur_m = best["m"][:]
    stall = 0
    while left() > 0.0:
        keys = cur_k[:]
        mg = cur_m[:]
        r = rng.random()
        nm = 1 + int(rng.random() * 3)
        for _ in range(nm):
            i = rng.randrange(n)
            if r < 0.15 and len(modes[i]) > 1:
                mg[i] = rng.randrange(-1, len(modes[i]))
            elif r < 0.5:
                j2 = rng.randrange(n)
                keys[i], keys[j2] = keys[j2], keys[i]
            else:
                keys[i] += rng.gauss(0, hor * 0.1 + 1)
        c, st2, mo2 = sgs(keys, mg)
        if c <= cur_c:
            if c < cur_c:
                stall = 0
            cur_c, cur_k, cur_m = c, keys, mg
            if c < best["c"]:
                best["c"] = c
                best["st"] = st2
                best["mo"] = mo2
                best["k"] = keys[:]
                best["m"] = mg[:]
        else:
            stall += 1
            if stall > 300:
                stall = 0
                cur_c = best["c"]
                cur_k = best["k"][:]
                cur_m = best["m"][:]

    st = best["st"]
    mo = best["mo"]
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][mo[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = best["c"]
    return state

import time, random, heapq, math

def solve(state, params):
    t0 = time.process_time()
    w0 = time.perf_counter()
    BUDGET = 0.72
    def elapsed():
        return max(time.process_time() - t0, (time.perf_counter() - w0) * 0.6)
    inp = state["input"]
    res = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = (res[r] or {}).get("calendar", [[0, 0]]) or [[0, 0]]
        cal = sorted([[int(a), int(b)] for a, b in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                state["output"] = {"status": "infeasible", "reason": "unknown predecessor %s of job %s" % (p, ids[i])}
                return state
            pi = jidx[p]
            if pi not in preds[i]:
                preds[i].append(pi)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]; k += 1
        for v in succs[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                topo.append(v)
    if len(topo) < n:
        state["output"] = {"status": "infeasible", "reason": "precedence cycle"}
        return state
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            req = m.get("requires") or {}
            ok = True
            rl = []
            for rn, u in req.items():
                u = int(u)
                if rn not in ridx:
                    ok = False; break
                if u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    rl.append((ridx[rn], u))
            d = int(m.get("duration", 1))
            if ok:
                ml.append((d, rl, mi))
        if not ml:
            state["output"] = {"status": "infeasible", "reason": "job %s has no feasible mode" % ids[i]}
            return state
        modes.append(ml)
    rel = [int(j.get("release", 0) or 0) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    hasdue = [due[i] is not None and wt[i] > 0 for i in range(n)]
    duev = [int(due[i]) if due[i] is not None else 0 for i in range(n)]
    H = lastbp + max(rel + [0]) + sum(max(m[0] for m in modes[i]) for i in range(n)) + 20
    base = []
    for c in cals:
        arr = [0] * H
        for q in range(len(c)):
            a = c[q][0]
            b = c[q + 1][0] if q + 1 < len(c) else H
            cap = c[q][1]
            for t in range(max(a, 0), min(b, H)):
                arr[t] = cap
        base.append(arr)
    nm = [len(modes[i]) for i in range(n)]
    mind = [min(m[0] for m in modes[i]) for i in range(n)]

    def decode(order, mv):
        avail = [b[:] for b in base]
        fin = [0] * n
        st = [0] * n
        chosen = [0] * n
        for j in order:
            es = rel[j]
            for p in preds[j]:
                if fin[p] > es:
                    es = fin[p]
            mm = mv[j]
            ml = modes[j]
            if mm < 0 and len(ml) > 1:
                cands = range(len(ml))
            else:
                cands = (mm if mm >= 0 else 0,)
            best = None
            for ci in cands:
                d, rl, _ = ml[ci]
                t = es
                if rl:
                    while True:
                        ok = True
                        for (r, u) in rl:
                            a = avail[r]
                            for kk in range(t, t + d):
                                if a[kk] < u:
                                    t = kk + 1; ok = False; break
                            if not ok:
                                break
                        if ok:
                            break
                f = t + d
                sc = f
                if hasdue[j] and f > duev[j]:
                    sc += wt[j] * (f - duev[j])
                key = (sc, f, sum(u for _, u in rl) * d)
                if best is None or key < best[0]:
                    best = (key, ci, t)
            _, ci, t = best
            d, rl, _ = ml[ci]
            for (r, u) in rl:
                a = avail[r]
                for kk in range(t, t + d):
                    a[kk] -= u
            st[j] = t; fin[j] = t + d; chosen[j] = ci
        mk = max(fin) if n else 0
        cost = mk
        for j in range(n):
            if hasdue[j] and fin[j] > duev[j]:
                cost += wt[j] * (fin[j] - duev[j])
        return cost, st, chosen

    tail = [0] * n
    for j in reversed(topo):
        b = 0
        for s in succs[j]:
            if tail[s] > b:
                b = tail[s]
        tail[j] = b + mind[j]
    head = [0] * n
    for j in topo:
        e = rel[j]
        for p in preds[j]:
            if head[p] + mind[p] > e:
                e = head[p] + mind[p]
        head[j] = e
    CP = max(head[j] + tail[j] for j in range(n)) if n else 0
    lft = [CP - tail[j] + mind[j] for j in range(n)]
    dl = [lft[j] for j in range(n)]
    for j in reversed(topo):
        v = duev[j] if hasdue[j] else 10 ** 9
        for s in succs[j]:
            if dl[s] - mind[s] < v:
                v = dl[s] - mind[s]
        dl[j] = min(v, lft[j]) if v < 10 ** 9 else lft[j]

    def order_from_prio(prio):
        deg = [len(preds[i]) for i in range(n)]
        h = [(prio[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, u = heapq.heappop(h)
            out.append(u)
            for v in succs[u]:
                deg[v] -= 1
                if deg[v] == 0:
                    heapq.heappush(h, (prio[v], v))
        return out

    rng = random.Random(12345)
    prios = [
        [(dl[i], lft[i]) for i in range(n)],
        [(lft[i], rel[i]) for i in range(n)],
        [(min(dl[i], lft[i]) - 0.5 * tail[i], i) for i in range(n)],
        [(rel[i] + head[i], lft[i]) for i in range(n)],
        [(-tail[i], dl[i]) for i in range(n)],
        [(max(rel[i], head[i]), dl[i]) for i in range(n)],
    ]
    fastm = []
    for i in range(n):
        bi = 0
        for c in range(nm[i]):
            if modes[i][c][0] < modes[i][bi][0]:
                bi = c
        fastm.append(bi)
    best = None
    pool = []
    for pr in prios:
        if best is not None and elapsed() > BUDGET * 0.4:
            break
        o = order_from_prio(pr)
        for mvset in ([-1] * n, fastm[:]):
            if best is not None and elapsed() > BUDGET * 0.4:
                break
            c, st, ch = decode(o, mvset)
            pool.append((c, o, mvset[:]))
            if best is None or c < best[0]:
                best = (c, st, ch)
    for _ in range(6):
        if elapsed() > BUDGET * 0.3:
            break
        pr = [(dl[i] + rng.random() * (CP * 0.3 + 1), i) for i in range(n)]
        o = order_from_prio(pr)
        c, st, ch = decode(o, [-1] * n)
        pool.append((c, o, [-1] * n))
        if c < best[0]:
            best = (c, st, ch)
    pool.sort(key=lambda x: x[0])

    cur_c, cur_o, cur_m = pool[0][0], pool[0][1][:], pool[0][2][:]
    T0 = max(1.0, 0.02 * cur_c)
    T = T0
    it = 0
    last_imp = 0
    tstart = elapsed()
    span = max(1e-3, BUDGET - tstart)
    multi = [i for i in range(n) if nm[i] > 1]
    while n > 1 or multi:
        el = elapsed()
        if el > BUDGET:
            break
        frac = (el - tstart) / span
        T = T0 * (1 - frac) * (1 - frac) + 0.01
        it += 1
        o = cur_o[:]
        m = cur_m
        nmoves = 1 + (rng.random() < 0.3)
        for _ in range(nmoves):
            r = rng.random()
            if multi and (r < 0.25 or n <= 1):
                if m is cur_m:
                    m = cur_m[:]
                j = rng.choice(multi)
                m[j] = rng.randrange(-1, nm[j])
            elif n > 1:
                i = rng.randrange(n)
                j = o.pop(i)
                pos = {v: q for q, v in enumerate(o)}
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo:
                        lo = pos[p] + 1
                hi = len(o)
                for s in succs[j]:
                    if pos[s] < hi:
                        hi = pos[s]
                a1 = max(lo, i - 6)
                b1 = min(hi, i + 6)
                if rng.random() < 0.5 and a1 <= b1:
                    np_ = rng.randint(a1, b1)
                else:
                    np_ = rng.randint(lo, hi)
                o.insert(np_, j)
        c, st, ch = decode(o, m)
        if c < best[0]:
            best = (c, st, ch)
            last_imp = it
        d = c - cur_c
        if d <= 0 or rng.random() < math.exp(-d / T):
            cur_c, cur_o, cur_m = c, o, m
        if it - last_imp > 300 and rng.random() < 0.01:
            e = pool[rng.randrange(min(4, len(pool)))]
            cur_c, cur_o, cur_m = e[0], e[1][:], e[2][:]
            last_imp = it
    _, st, ch = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(modes[j][ch[j]][2])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["best_cost"] = best[0]
    state["iters"] = it
    return state

import time, random, heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.78
    inp = state.get("input") or {}
    res = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(res.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    R = len(rnames)
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = (res[r] or {}).get("calendar") or [[0, 0]]
        cal = sorted([(int(a[0]), int(a[1])) for a in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
        if cal[-1][0] > lastbp:
            lastbp = cal[-1][0]
    n = len(jobs)
    ids = [str(j.get("id")) for j in jobs]
    jidx = {x: i for i, x in enumerate(ids)}
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        seen = set()
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                return _infeasible(state, "job %s references unknown predecessor %s" % (ids[i], p))
            q = jidx[p]
            if q not in seen:
                seen.add(q)
                preds[i].append(q)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    stack = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while stack:
        x = stack.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                stack.append(s)
    if len(topo) < n:
        return _infeasible(state, "precedence relation has a cycle")
    modes = []
    rel = []
    due = []
    wt = []
    for i, j in enumerate(jobs):
        ml = []
        for k, m in enumerate(j.get("modes") or []):
            d = int(m.get("duration", 1))
            req = []
            ok = True
            for rn, q in (m.get("requires") or {}).items():
                q = int(q)
                if rn not in ridx or q > maxcap[ridx[rn]]:
                    ok = False
                    break
                if q > 0:
                    req.append((ridx[rn], q))
            if ok:
                work = 0.0
                for (r, q) in req:
                    work += d * q / float(max(1, maxcap[r]))
                ml.append((d, req, k, work))
        if not ml:
            return _infeasible(state, "job %s has no feasible mode" % ids[i])
        modes.append(ml)
        rel.append(max(0, int(j.get("release") or 0)))
        dd = j.get("due")
        due.append(None if dd is None else int(dd))
        wt.append(int(j.get("weight") or 0))
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    maxrel = max(rel)
    H = lastbp + maxrel + sum(max(m[0] for m in ml) for ml in modes) + 16
    base = []
    for r in range(R):
        cal = cals[r]
        arr = [0] * H
        for k in range(len(cal)):
            a = cal[k][0]
            b = cal[k + 1][0] if k + 1 < len(cal) else H
            if a >= H:
                break
            c = cal[k][1]
            for t in range(max(0, a), min(b, H)):
                arr[t] = c
        base.append(arr)
    mind = [min(m[0] for m in ml) for ml in modes]

    def find(avail, t, d, req):
        while True:
            ok = True
            for (r, q) in req:
                arr = avail[r]
                k = t + d - 1
                while k >= t:
                    if arr[k] < q:
                        t = k + 1
                        ok = False
                        break
                    k -= 1
                if not ok:
                    break
            if ok:
                return t

    def findl(avail, t, d, req):
        while t >= 0:
            ok = True
            for (r, q) in req:
                arr = avail[r]
                for k in range(t, t + d):
                    if arr[k] < q:
                        t = k - d
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return t
        return None

    def costof(fin):
        c = max(fin)
        for j in range(n):
            if due[j] is not None and fin[j] > due[j]:
                c += wt[j] * (fin[j] - due[j])
        return c

    def sgs(order, mpref, alpha):
        avail = [a[:] for a in base]
        start = [0] * n
        mode = [0] * n
        fin = [0] * n
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est:
                    est = fin[p]
            ml = modes[j]
            mp = mpref[j]
            if mp >= 0 or len(ml) == 1:
                k = mp if mp >= 0 else 0
                d, req = ml[k][0], ml[k][1]
                s = find(avail, est, d, req)
                bk = k
            else:
                bsc = None
                bk = 0
                s = est
                for k in range(len(ml)):
                    d, req = ml[k][0], ml[k][1]
                    s0 = find(avail, est, d, req)
                    f = s0 + d
                    sc = f
                    if due[j] is not None and f > due[j]:
                        sc += wt[j] * (f - due[j])
                    sc += alpha * ml[k][3]
                    if bsc is None or sc < bsc:
                        bsc = sc
                        bk = k
                        s = s0
                d, req = ml[bk][0], ml[bk][1]
            for (r, q) in req:
                arr = avail[r]
                for t in range(s, s + d):
                    arr[t] -= q
            start[j] = s
            mode[j] = bk
            fin[j] = s + d
        return start, mode, fin, costof(fin)

    def backward(start, mode, fin):
        M = max(fin)
        avail = [a[:] for a in base]
        order = sorted(range(n), key=lambda j: (-fin[j], -start[j]))
        bst = [0] * n
        for j in order:
            lf = M
            for s in succs[j]:
                if bst[s] < lf:
                    lf = bst[s]
            d, req = modes[j][mode[j]][0], modes[j][mode[j]][1]
            s = findl(avail, lf - d, d, req)
            if s is None:
                bst[j] = lf - d
                continue
            for (r, q) in req:
                arr = avail[r]
                for t in range(s, s + d):
                    arr[t] -= q
            bst[j] = s
        return sorted(range(n), key=lambda j: (bst[j], start[j]))

    def order_from_keys(keys):
        indeg2 = [len(preds[i]) for i in range(n)]
        h = [(keys[i], i) for i in range(n) if indeg2[i] == 0]
        heapq.heapify(h)
        out = []
        while h:
            _, x = heapq.heappop(h)
            out.append(x)
            for s in succs[x]:
                indeg2[s] -= 1
                if indeg2[s] == 0:
                    heapq.heappush(h, (keys[s], s))
        return out

    tail = [0] * n
    for x in reversed(topo):
        m = 0
        for s in succs[x]:
            if tail[s] > m:
                m = tail[s]
        tail[x] = m + mind[x]
    head = [0] * n
    for x in topo:
        e = rel[x]
        for p in preds[x]:
            if head[p] + mind[p] > e:
                e = head[p] + mind[p]
        head[x] = e
    LB = max(head[i] + tail[i] for i in range(n))
    lst = [LB - tail[i] for i in range(n)]
    INF = 10 ** 9
    lsd = [INF] * n
    for x in reversed(topo):
        v = INF
        if due[x] is not None and wt[x] > 0:
            v = due[x] - mind[x]
        for s in succs[x]:
            if lsd[s] < INF and lsd[s] - mind[x] < v:
                v = lsd[s] - mind[x]
        lsd[x] = v
    wsum = [0] * n
    for x in reversed(topo):
        w = wt[x] if due[x] is not None else 0
        for s in succs[x]:
            w += wsum[s]
        wsum[x] = min(w, 10 ** 6)
    rules = []
    rules.append([float(v) for v in lst])
    rules.append([float(min(lst[i], lsd[i])) for i in range(n)])
    rules.append([float(lsd[i] if lsd[i] < INF else lst[i] + LB) for i in range(n)])
    rules.append([min(lst[i], lsd[i]) - 0.5 * min(wsum[i], 20) for i in range(n)])
    rules.append([float(head[i]) for i in range(n)])
    rules.append([float(min(lst[i], lsd[i] + LB * 0.25)) for i in range(n)])

    rng = random.Random(12345)
    best = None

    def consider(start, mode, cost):
        nonlocal best
        if best is None or cost < best[0]:
            best = (cost, start[:], mode[:])

    def fbi(start, mode, fin, cost, rounds):
        for _ in range(rounds):
            o = backward(start, mode, fin)
            s2, m2, f2, c2 = sgs(o, mode, 0.0)
            if c2 < cost:
                start, mode, fin, cost = s2, m2, f2, c2
            else:
                break
        return start, mode, fin, cost

    def elapsed():
        return time.process_time() - T0

    greedy = [-1] * n
    it = 0
    phase1 = BUDGET * 0.35
    pool = []
    while True:
        if it > 0 and elapsed() > phase1:
            break
        ri = it % len(rules)
        keysb = rules[ri]
        noise = 0.0 if it < len(rules) else rng.choice([0.5, 2.0, 5.0, 0.2 * LB + 1])
        alpha = 0.0 if (it // len(rules)) % 3 != 2 else rng.choice([0.5, 1.0, 2.0])
        keys = [keysb[i] + noise * rng.random() for i in range(n)]
        o = order_from_keys(keys)
        st, md, fn, c = sgs(o, greedy, alpha)
        st, md, fn, c = fbi(st, md, fn, c, 3)
        consider(st, md, c)
        pool.append((c, st, md))
        it += 1
        if it > 2000:
            break

    def order_of(start):
        return sorted(range(n), key=lambda j: (start[j], j))

    c0, st0, md0 = best
    cur_cost = c0
    cur_order = order_of(st0)
    cur_mp = md0[:]
    stall = 0
    multi = [j for j in range(n) if len(modes[j]) > 1]
    pool.sort(key=lambda x: x[0])
    pool = pool[:10]
    while elapsed() < BUDGET:
        order = cur_order[:]
        mp = cur_mp[:]
        nm = 1 if rng.random() < 0.7 else rng.randint(2, 4)
        for _ in range(nm):
            rr = rng.random()
            if multi and rr < 0.3:
                j = rng.choice(multi)
                if rng.random() < 0.2:
                    mp[j] = -1
                else:
                    mp[j] = rng.randrange(len(modes[j]))
            else:
                pos = {x: i for i, x in enumerate(order)}
                i = rng.randrange(n)
                j = order[i]
                lo = 0
                for p in preds[j]:
                    if pos[p] + 1 > lo:
                        lo = pos[p] + 1
                hi = n - 1
                for s in succs[j]:
                    if pos[s] - 1 < hi:
                        hi = pos[s] - 1
                if hi <= lo:
                    continue
                k = rng.randint(lo, hi)
                if k == i:
                    continue
                del order[i]
                order.insert(k, j)
        st, md, fn, c = sgs(order, mp, 0.0)
        if rng.random() < 0.25 or c < cur_cost:
            st, md, fn, c = fbi(st, md, fn, c, 2)
        consider(st, md, c)
        if c <= cur_cost:
            if c < cur_cost:
                stall = 0
            else:
                stall += 1
            cur_cost = c
            cur_order = order_of(st)
            cur_mp = md[:]
        else:
            stall += 1
        if stall > 150:
            stall = 0
            if rng.random() < 0.5 or not pool:
                cc, sb, mb = best
            else:
                cc, sb, mb = pool[rng.randrange(min(5, len(pool)))]
            cur_cost = cc
            cur_order = order_of(sb)
            cur_mp = mb[:]

    cost, start, mode = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(start[j]), "mode": int(modes[j][mode[j]][2])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time, random, heapq

def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state

def solve(state, params):
    t0 = time.process_time()
    budget = 0.78
    inp = state["input"]
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    for r in rnames:
        rv = resources[r] or {}
        cal = sorted([(int(a), int(b)) for a, b in (rv.get("calendar") or [[0, 0]])])
        if not cal:
            cal = [(0, 0)]
        cals.append(cal)
    maxcap = [c[-1][1] for c in cals]
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = [[] for _ in range(n)]
    succs = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in (j.get("after") or []):
            p = str(p)
            if p not in jidx:
                return _infeasible(state, "unknown predecessor %s of job %s" % (p, ids[i]))
            pi = jidx[p]
            if pi not in preds[i]:
                preds[i].append(pi)
                succs[pi].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]
    topo = []
    while q:
        x = q.pop()
        topo.append(x)
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                q.append(s)
    if len(topo) < n:
        return _infeasible(state, "precedence cycle")
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            ok = True
            req = []
            for r, u in (m.get("requires") or {}).items():
                u = int(u)
                if r not in ridx or u > maxcap[ridx[r]]:
                    ok = False
                    break
                if u > 0:
                    req.append((ridx[r], u))
            d = int(m.get("duration", 1))
            if ok:
                ml.append((mi, d, req))
        if not ml:
            return _infeasible(state, "job %s has no feasible mode" % ids[i])
        modes.append(ml)
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    hasdue = [due[i] is not None for i in range(n)]
    duev = [int(due[i]) if hasdue[i] else 0 for i in range(n)]
    lastbp = max([c[-1][0] for c in cals] + [0])
    sumd = sum(max(max(m[1] for m in ml), 0) for ml in modes)
    H = 2 * (lastbp + max(rel + [0]) + sumd) + 50
    base = []
    for c in cals:
        arr = [0] * H
        for k, (a, cap) in enumerate(c):
            b = c[k + 1][0] if k + 1 < len(c) else H
            a = max(0, a)
            b = min(H, b)
            if b > a:
                arr[a:b] = [cap] * (b - a)
        base.append(arr)

    def earliest(avail, req, est, d):
        t = est
        if d <= 0:
            return t
        while True:
            ok = True
            for r, u in req:
                arr = avail[r]
                if min(arr[t:t + d]) < u:
                    k = t + d - 1
                    while arr[k] >= u:
                        k -= 1
                    t = k + 1
                    ok = False
                    break
            if ok:
                return t

    def decode(keys, mgene):
        avail = [a[:] for a in base]
        indg = [len(preds[i]) for i in range(n)]
        est = rel[:]
        heap = [(keys[i], i) for i in range(n) if indg[i] == 0]
        heapq.heapify(heap)
        start = [0] * n
        mpos = [0] * n
        cost = 0
        mk = 0
        while heap:
            _, j = heapq.heappop(heap)
            e = est[j]
            ml = modes[j]
            if mgene is not None:
                p = mgene[j]
                _, d, req = ml[p]
                s = earliest(avail, req, e, d)
            else:
                best = None
                for p0, (_, d0, req0) in enumerate(ml):
                    s0 = earliest(avail, req0, e, d0)
                    f0 = s0 + d0
                    sc = f0
                    if hasdue[j] and f0 > duev[j]:
                        sc += wt[j] * (f0 - duev[j])
                    sc = sc * 1000000 + sum(u * max(d0, 0) * 100 // max(1, maxcap[r]) for r, u in req0)
                    if best is None or sc < best[0]:
                        best = (sc, p0, s0)
                _, p, s = best
                _, d, req = ml[p]
            if d > 0:
                for r, u in req:
                    arr = avail[r]
                    for t in range(s, s + d):
                        arr[t] -= u
            f = s + d
            start[j] = s
            mpos[j] = p
            if f > mk:
                mk = f
            if hasdue[j] and f > duev[j]:
                cost += wt[j] * (f - duev[j])
            for sj in succs[j]:
                if f > est[sj]:
                    est[sj] = f
                indg[sj] -= 1
                if indg[sj] == 0:
                    heapq.heappush(heap, (keys[sj], sj))
        return cost + mk, start, mpos

    mind = [min(m[1] for m in ml) for ml in modes]
    tail = [0] * n
    for x in reversed(topo):
        t = 0
        for s in succs[x]:
            if tail[s] > t:
                t = tail[s]
        tail[x] = t + mind[x]
    head = [0] * n
    for x in topo:
        h = rel[x]
        for p in preds[x]:
            if head[p] + mind[p] > h:
                h = head[p] + mind[p]
        head[x] = h
    LB = max([head[i] + tail[i] for i in range(n)] + [1])
    rules = []
    rules.append([float(-tail[i]) for i in range(n)])
    rules.append([float(head[i] - tail[i]) for i in range(n)])
    rules.append([(duev[i] - tail[i] + mind[i] if hasdue[i] else LB - tail[i] + mind[i]) * 1.0
                  - (wt[i] if hasdue[i] else 0) * 0.5 for i in range(n)])
    rules.append([float(rel[i]) for i in range(n)])
    rules.append([float(i) for i in range(n)])
    rng = random.Random(12345)
    best = None

    def norm_keys(start):
        order = sorted(range(n), key=lambda i: (start[i], i))
        k = [0.0] * n
        for r_, i in enumerate(order):
            k[i] = float(r_)
        return k

    def consider(c, st, mp):
        nonlocal best
        if best is None or c < best[0]:
            best = (c, norm_keys(st), mp[:], st[:])
            return True
        return False

    def tleft():
        return budget - (time.process_time() - t0)

    for rk in rules:
        c, st, mp = decode(rk, None)
        consider(c, st, mp)
        if tleft() < budget * 0.5:
            break
    ph1 = budget * 0.35
    it = 0
    while time.process_time() - t0 < ph1:
        rk = rules[it % len(rules)]
        spread = max(1.0, LB * 0.15)
        keys = [rk[i] + rng.random() * spread * (0.2 + rng.random()) for i in range(n)]
        it += 1
        mg = None if rng.random() < 0.7 else [rng.randrange(len(modes[i])) for i in range(n)]
        c, st, mp = decode(keys, mg)
        consider(c, st, mp)
    cur_c, cur_k, cur_m, _ = best
    multi = [i for i in range(n) if len(modes[i]) > 1]
    noimp = 0
    while tleft() > 0.01:
        keys = cur_k[:]
        mg = cur_m[:]
        nm = 1 if noimp < 200 else rng.randint(2, 5)
        for _ in range(nm):
            mv = rng.random()
            if multi and mv < 0.3:
                j = rng.choice(multi)
                np_ = rng.randrange(len(modes[j]) - 1)
                if np_ >= mg[j]:
                    np_ += 1
                mg[j] = np_
            elif mv < 0.75:
                j = rng.randrange(n)
                o = rng.randrange(n)
                keys[j] = keys[o] + (0.5 if rng.random() < 0.5 else -0.5)
            elif mv < 0.85:
                a = rng.randrange(n)
                b = rng.randrange(n)
                keys[a], keys[b] = keys[b], keys[a]
            else:
                j = rng.randrange(n)
                keys[j] -= rng.randint(1, max(1, n // 5))
        usegreedy = rng.random() < 0.1
        c, st, mp = decode(keys, None if usegreedy else mg)
        if c <= cur_c:
            if c < cur_c:
                noimp = 0
            else:
                noimp += 1
            cur_c = c
            cur_k = norm_keys(st)
            cur_m = mp
            consider(c, st, mp)
        else:
            noimp += 1
        if noimp > 600:
            cur_c, cur_k, cur_m, _ = best
            noimp = 0
    c, keys, mp, st = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][mp[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = int(c)
    return state

import time
import random
import heapq


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    t0p = time.process_time()
    t0w = time.perf_counter()
    BUDGET = 0.72
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    for r in rnames:
        c = (resources[r] or {}).get("calendar") or [[0, 0]]
        c = sorted([[int(a), int(b)] for a, b in c])
        cals.append(c)
        maxcap.append(c[-1][1])
    n = len(jobs)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    ids = [str(j.get("id")) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = []
    for i, j in enumerate(jobs):
        ps = []
        for p in (j.get("after") or []):
            if str(p) not in jidx:
                return _infeasible(state, "job %s references unknown predecessor %s" % (ids[i], p))
            ps.append(jidx[str(p)])
        preds.append(sorted(set(ps)))
    jmodes = []
    for i, j in enumerate(jobs):
        ms = []
        for mi, m in enumerate(j.get("modes") or []):
            ok = True
            reqs = []
            for r, u in (m.get("requires") or {}).items():
                u = int(u)
                if r not in ridx:
                    ok = False
                    break
                if u > maxcap[ridx[r]]:
                    ok = False
                    break
                if u > 0:
                    reqs.append((ridx[r], u))
            if ok:
                ms.append((mi, max(1, int(m.get("duration", 1))), reqs))
        if not ms:
            return _infeasible(state, "job %s has no executable mode" % ids[i])
        jmodes.append(ms)
    succ = [[] for _ in range(n)]
    npred = [0] * n
    for i in range(n):
        for p in preds[i]:
            succ[p].append(i)
            npred[i] += 1
    indeg = npred[:]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]
        k += 1
        for v in succ[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                topo.append(v)
    if len(topo) < n:
        return _infeasible(state, "precedence relation contains a cycle")

    rel = [max(0, int(j.get("release") or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight") or 0) for j in jobs]
    dueL = [(int(due[i]) if due[i] is not None else None) for i in range(n)]
    T0 = max(rel)
    for c in cals:
        T0 = max(T0, c[-1][0])
    H = T0 + sum(max(m[1] for m in ms) for ms in jmodes) + 2
    base = []
    for c in cals:
        arr = [0] * H
        for s in range(len(c)):
            a = c[s][0]
            b = c[s + 1][0] if s + 1 < len(c) else H
            a = max(0, min(a, H))
            b = max(0, min(b, H))
            cap = c[s][1]
            for t in range(a, b):
                arr[t] = cap
        base.append(arr)

    def place(t, d, reqs, avail):
        while True:
            end = t + d
            ok = True
            for ri, u in reqs:
                a = avail[ri]
                for kk in range(t, end):
                    if a[kk] < u:
                        t = kk + 1
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return t

    nm = [len(ms) for ms in jmodes]

    def decode(keys, modes):
        avail = [b[:] for b in base]
        deg = npred[:]
        est = rel[:]
        heap = [(keys[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(heap)
        start = [0] * n
        fin = [0] * n
        cm = [0] * n
        while heap:
            _, j = heapq.heappop(heap)
            e = est[j]
            m = modes[j]
            ms = jmodes[j]
            if m < 0 or m >= nm[j]:
                best = None
                for mi in range(nm[j]):
                    d = ms[mi][1]
                    st = place(e, d, ms[mi][2], avail)
                    f = st + d
                    if best is None or f < best[0]:
                        best = (f, st, mi)
                f, st, m = best
            else:
                st = place(e, ms[m][1], ms[m][2], avail)
                f = st + ms[m][1]
            for ri, u in ms[m][2]:
                a = avail[ri]
                for kk in range(st, f):
                    a[kk] -= u
            start[j] = st
            fin[j] = f
            cm[j] = m
            for s in succ[j]:
                if f > est[s]:
                    est[s] = f
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(heap, (keys[s], s))
        cost = max(fin)
        for j in range(n):
            if dueL[j] is not None and wt[j] > 0 and fin[j] > dueL[j]:
                cost += wt[j] * (fin[j] - dueL[j])
        return cost, start, cm

    def elapsed():
        return max(time.process_time() - t0p, (time.perf_counter() - t0w) * 0.5)

    mind = [min(m[1] for m in ms) for ms in jmodes]
    tail = [0] * n
    for u in reversed(topo):
        t = 0
        for v in succ[u]:
            if tail[v] > t:
                t = tail[v]
        tail[u] = t + mind[u]
    esf = [0] * n
    for u in topo:
        e = rel[u]
        for p in preds[u]:
            if esf[p] > e:
                e = esf[p]
        esf[u] = e + mind[u]
    cp = max(esf)
    lft = [cp - tail[u] + mind[u] for u in range(n)]
    dl = [None] * n
    for u in reversed(topo):
        v0 = dueL[u] if (dueL[u] is not None and wt[u] > 0) else None
        for v in succ[u]:
            if dl[v] is not None:
                c = dl[v] - mind[v]
                if v0 is None or c < v0:
                    v0 = c
        dl[u] = v0
    big = cp + 10 ** 6
    rules = []
    rules.append([lft[u] - mind[u] for u in range(n)])
    rules.append([(dl[u] if dl[u] is not None else big) - mind[u] for u in range(n)])
    rules.append([min(lft[u], dl[u] if dl[u] is not None else lft[u]) - mind[u] for u in range(n)])
    rules.append([-tail[u] for u in range(n)])
    rules.append([esf[u] for u in range(n)])
    rules.append([min(lft[u] - mind[u], (dl[u] - mind[u]) if dl[u] is not None else big) - 0.01 * wt[u] for u in range(n)])

    rng = random.Random(12345)
    best = None

    def rekey(start, keys):
        order = sorted(range(n), key=lambda i: (start[i], keys[i]))
        nk = [0.0] * n
        for r, i in enumerate(order):
            nk[i] = float(r)
        return nk

    cands = []
    for rk in rules:
        for mv in ([-1] * n, [0] * n):
            c, st, cm = decode(rk, mv)
            cands.append((c, rekey(st, rk), cm, st))
            if best is None or c < best[0]:
                best = (c, st[:], cm[:])
        if elapsed() > BUDGET * 0.3:
            break
    mmin = [min(range(nm[j]), key=lambda mi: jmodes[j][mi][1]) for j in range(n)]
    c, st, cm = decode(rules[2], mmin)
    cands.append((c, rekey(st, rules[2]), cm, st))
    if c < best[0]:
        best = (c, st[:], cm[:])
    cands.sort(key=lambda x: x[0])

    multi = [j for j in range(n) if nm[j] > 1]
    cur_c, cur_k, cur_m, cur_s = cands[0]
    cur_k = cur_k[:]
    cur_m = cur_m[:]
    T = max(1.0, 0.03 * cur_c)
    Tinit = T
    it = 0
    last_imp = 0
    while True:
        it += 1
        el = elapsed()
        if el > BUDGET:
            break
        frac = el / BUDGET
        T = Tinit * (0.02 ** frac)
        nk = cur_k[:]
        nmv = cur_m[:]
        r = rng.random()
        j = rng.randrange(n)
        if r < 0.15:
            tard = [x for x in range(n) if dueL[x] is not None and wt[x] > 0
                    and cur_s[x] + jmodes[x][cur_m[x]][1] > dueL[x]]
            if tard:
                j = rng.choice(tard)
                nk[j] = cur_k[j] - rng.randint(1, max(1, n // 4)) - 0.5
            else:
                i = rng.randrange(n)
                nk[j] = cur_k[i] + (0.5 if rng.random() < 0.5 else -0.5)
        elif r < 0.55:
            i = rng.randrange(n)
            nk[j] = cur_k[i] + (0.5 if rng.random() < 0.5 else -0.5)
        elif r < 0.7:
            i = rng.randrange(n)
            nk[i], nk[j] = nk[j], nk[i]
        elif multi:
            j = rng.choice(multi)
            if rng.random() < 0.3:
                nmv[j] = -1
            else:
                mm = rng.randrange(nm[j] - 1)
                if mm >= cur_m[j]:
                    mm += 1
                nmv[j] = mm
            if rng.random() < 0.3:
                i = rng.randrange(n)
                nk[j] = cur_k[i] + (0.5 if rng.random() < 0.5 else -0.5)
        else:
            i = rng.randrange(n)
            nk[j] = cur_k[i] + (0.5 if rng.random() < 0.5 else -0.5)
        c, st, cm = decode(nk, nmv)
        d = c - cur_c
        if d <= 0 or rng.random() < pow(2.718281828, -d / T):
            cur_c = c
            cur_k = rekey(st, nk)
            cur_m = cm
            cur_s = st
            if c < best[0]:
                best = (c, st[:], cm[:])
                last_imp = it
        if it - last_imp > 400 + 4 * n:
            last_imp = it
            pick = cands[rng.randrange(min(3, len(cands)))] if rng.random() < 0.3 else None
            if pick is None:
                cur_c, cur_s, cur_m = best[0], best[1][:], best[2][:]
                cur_k = rekey(cur_s, [0.0] * n)
            else:
                cur_c, cur_k, cur_m, cur_s = pick[0], pick[1][:], pick[2][:], pick[3]
    _, st, cm = best
    sched = {}
    for j in range(n):
        sched[ids[j]] = {"start": int(st[j]), "mode": int(jmodes[j][cm[j]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time, heapq, random, math

def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state

def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.72
    inp = state["input"]
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    idx = {}
    for i, k in enumerate(ids):
        idx[k] = i
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        for p in (j.get("after") or []):
            p = str(p)
            if p not in idx:
                return _infeasible(state, "job %s references unknown predecessor %s" % (ids[i], p))
            pi = idx[p]
            if pi not in preds[i]:
                preds[i].append(pi)
    succs = [[] for _ in range(n)]
    indeg = [0] * n
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
            indeg[i] += 1
    deg = indeg[:]
    topo = [i for i in range(n) if deg[i] == 0]
    k = 0
    while k < len(topo):
        u = topo[k]; k += 1
        for v in succs[u]:
            deg[v] -= 1
            if deg[v] == 0:
                topo.append(v)
    if len(topo) < n:
        return _infeasible(state, "precedence relation contains a cycle")
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = resources[r].get("calendar") or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
        lastbp = max(lastbp, cal[-1][0])
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes") or []):
            d = int(m["duration"])
            req = m.get("requires") or {}
            ok = True
            rl = []
            for rn, u in req.items():
                u = int(u)
                if rn not in ridx or u > maxcap[ridx[rn]]:
                    ok = False; break
                if u > 0:
                    rl.append((ridx[rn], u))
            if ok:
                ml.append((mi, d, rl))
        if not ml:
            return _infeasible(state, "job %s has no feasible mode" % ids[i])
        modes.append(ml)
    rel = [int(j.get("release") or 0) for j in jobs]
    due = [j.get("due") for j in jobs]
    wt = [int(j.get("weight") or 0) for j in jobs]
    hasdue = [due[i] is not None for i in range(n)]
    duev = [int(due[i]) if hasdue[i] else 0 for i in range(n)]
    maxd = [max(m[1] for m in modes[i]) for i in range(n)]
    mind = [min(m[1] for m in modes[i]) for i in range(n)]
    H = max(lastbp, max(rel) if n else 0) + sum(maxd) + 5
    base = []
    for ri, cal in enumerate(cals):
        arr = [0] * H
        for s in range(len(cal)):
            a = cal[s][0]
            b = cal[s + 1][0] if s + 1 < len(cal) else H
            if a >= H:
                break
            b = min(b, H)
            c = cal[s][1]
            for t in range(a, b):
                arr[t] = c
        base.append(arr)
    R = len(rnames)
    rw = [1.0 / max(1, maxcap[r]) for r in range(R)]
    mload = [[sum(u * rw[r] for r, u in m[2]) * m[1] for m in modes[i]] for i in range(n)]

    head = [0] * n
    for u in topo:
        h = rel[u]
        for p in preds[u]:
            h = max(h, head[p] + mind[p])
        head[u] = h
    tail = [0] * n
    for u in reversed(topo):
        t = 0
        for v in succs[u]:
            t = max(t, tail[v])
        tail[u] = t + mind[u]
    BIG = 10 ** 6
    edue = [0] * n
    for u in reversed(topo):
        e = duev[u] if hasdue[u] and wt[u] > 0 else BIG
        for v in succs[u]:
            e = min(e, edue[v] - mind[v])
        edue[u] = e
    wdown = [0] * n
    for u in reversed(topo):
        w = wt[u] if hasdue[u] else 0
        for v in succs[u]:
            w = max(w, wdown[v])
        wdown[u] = w

    def decode(keys, fixed, mode_rule):
        caps = [a[:] for a in base]
        d0 = indeg[:]
        heap = [(keys[i], i) for i in range(n) if d0[i] == 0]
        heapq.heapify(heap)
        est = rel[:]
        st = [0] * n
        md = [0] * n
        cost = 0
        ms = 0
        while heap:
            _, j = heapq.heappop(heap)
            lo = est[j]
            fm = fixed[j]
            cand = modes[j] if fm < 0 else (modes[j][fm],)
            best = None
            for k2, m in enumerate(cand):
                d = m[1]; rl = m[2]
                s = lo
                if rl:
                    while True:
                        t = s + d - 1
                        bad = -1
                        while t >= s:
                            for (r, u) in rl:
                                if caps[r][t] < u:
                                    bad = t; break
                            if bad >= 0:
                                break
                            t -= 1
                        if bad < 0:
                            break
                        s = bad + 1
                f = s + d
                tard = (f - duev[j]) * wt[j] if hasdue[j] and f > duev[j] else 0
                mi2 = k2 if fm < 0 else fm
                if mode_rule == 0:
                    sc = (f + tard + max(0, f - ms) * 0.5, mload[j][mi2])
                else:
                    sc = (f + tard + max(0, f - ms) * 0.5 + 0.5 * mload[j][mi2], 0)
                if best is None or sc < best[0]:
                    best = (sc, s, mi2, f, tard)
            _, s, mk, f, tard = best
            st[j] = s; md[j] = mk
            for (r, u) in modes[j][mk][2]:
                a = caps[r]
                for t in range(s, f):
                    a[t] -= u
            cost += tard
            if f > ms:
                ms = f
            for v in succs[j]:
                if f > est[v]:
                    est[v] = f
                d0[v] -= 1
                if d0[v] == 0:
                    heapq.heappush(heap, (keys[v], v))
        return cost + ms, st, md

    rng = random.Random(12345)
    nofix = [-1] * n
    rules = []
    rules.append([-tail[i] for i in range(n)])
    rules.append([edue[i] - tail[i] * 0.001 for i in range(n)])
    rules.append([min(edue[i] - tail[i], 0) * 1.0 - tail[i] for i in range(n)])
    rules.append([head[i] - tail[i] * 0.01 for i in range(n)])
    rules.append([(edue[i] - head[i] - mind[i]) / (1.0 + wdown[i]) if edue[i] < BIG else BIG - tail[i] for i in range(n)])
    rules.append([-(tail[i] + wdown[i] * 3) for i in range(n)])
    best = None
    cands = []
    for kv in rules:
        for mr in (0, 1):
            c, st, md = decode(kv, nofix, mr)
            cands.append((c, kv, mr))
            if best is None or c < best[0]:
                best = (c, st, md)
        if time.process_time() - T0 > BUDGET * 0.3:
            break
    cands.sort(key=lambda x: x[0])

    def ranks(kv):
        order = sorted(range(n), key=lambda i: kv[i])
        r = [0.0] * n
        for p, i in enumerate(order):
            r[i] = float(p)
        return r

    cur_keys = ranks(cands[0][1])
    cur_mr = cands[0][2]
    cur_fix = nofix[:]
    cur_cost = cands[0][0]
    T_start = max(1.0, cur_cost * 0.01)
    t_ls0 = time.process_time()
    it = 0
    since = 0
    while True:
        el = time.process_time() - T0
        if el > BUDGET or n == 0:
            break
        frac = (time.process_time() - t_ls0) / max(1e-6, BUDGET - (t_ls0 - T0))
        temp = T_start * max(0.0, 1.0 - frac) + 1e-9
        keys = cur_keys[:]
        fix = cur_fix
        mv = rng.random()
        if mv < 0.15:
            fix = cur_fix[:]
            j = rng.randrange(n)
            fix[j] = rng.randrange(-1, len(modes[j]))
        elif mv < 0.25:
            for _ in range(rng.randint(2, 4)):
                j = rng.randrange(n)
                keys[j] += rng.uniform(-n * 0.1, n * 0.1)
        else:
            j = rng.randrange(n)
            o = rng.randrange(n)
            keys[j] = keys[o] + (0.5 if rng.random() < 0.5 else -0.5) * rng.random()
        c, st, md = decode(keys, fix, cur_mr)
        it += 1
        if c < best[0]:
            best = (c, st, md)
            since = 0
        else:
            since += 1
        if c <= cur_cost or rng.random() < math.exp(-(c - cur_cost) / temp):
            cur_keys = ranks(keys) if it % 20 == 0 else keys
            cur_fix = fix
            cur_cost = c
        if since > 300:
            cc = cands[rng.randrange(min(4, len(cands)))]
            cur_keys = [x + rng.uniform(0, n * 0.05) for x in ranks(cc[1])]
            cur_mr = cc[2]; cur_fix = nofix[:]
            cur_cost = decode(cur_keys, cur_fix, cur_mr)[0]
            since = 0
    c, st, md = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][md[i]][0])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time, random, heapq

def _fallback(inp):
    res = inp["resources"]; jobs = inp["jobs"]
    T0 = 0
    for r in res.values():
        T0 = max(T0, r["calendar"][-1][0])
    for j in jobs:
        T0 = max(T0, j["release"])
    ids = [j["id"] for j in jobs]; idx = {k: i for i, k in enumerate(ids)}
    indeg = [0]*len(jobs); succ = [[] for _ in jobs]
    for i, j in enumerate(jobs):
        for p in set(j["after"]):
            indeg[i] += 1; succ[idx[p]].append(i)
    q = [i for i in range(len(jobs)) if indeg[i] == 0]; order = []
    while q:
        i = q.pop(); order.append(i)
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    t = T0; sch = {}
    for i in order:
        j = jobs[i]
        for mi, m in enumerate(j["modes"]):
            if all(r in res and u <= res[r]["calendar"][-1][1] for r, u in m["requires"].items()):
                sch[j["id"]] = {"start": t, "mode": mi}; t += m["duration"]; break
    return {"status": "ok", "schedule": sch}

def _check(inp):
    res = inp["resources"]; jobs = inp["jobs"]
    ids = set(j["id"] for j in jobs)
    for j in jobs:
        for p in j["after"]:
            if p not in ids:
                return "job %s references unknown predecessor %s" % (j["id"], p)
    for j in jobs:
        ok = False
        for m in j["modes"]:
            if all(r in res and u <= res[r]["calendar"][-1][1] for r, u in m["requires"].items()):
                ok = True; break
        if not ok:
            return "job %s has no feasible mode" % j["id"]
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    indeg = [0]*len(jobs); succ = [[] for _ in jobs]
    for i, j in enumerate(jobs):
        for p in set(j["after"]):
            indeg[i] += 1; succ[idx[p]].append(i)
    q = [i for i in range(len(jobs)) if indeg[i] == 0]; cnt = 0
    while q:
        i = q.pop(); cnt += 1
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    if cnt != len(jobs):
        return "precedence relation has a cycle"
    return None

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    reason = _check(inp)
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    try:
        state["output"] = _opt(inp, t0)
    except Exception:
        state["output"] = _fallback(inp)
    return state

def _opt(inp, t0):
    deadline = t0 + 0.78
    rng = random.Random(12345)
    resd = inp["resources"]; jobs = inp["jobs"]
    rnames = list(resd.keys()); ridx = {r: i for i, r in enumerate(rnames)}
    maxcap = [resd[r]["calendar"][-1][1] for r in rnames]
    n = len(jobs)
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    rel = [j["release"] for j in jobs]
    due = [j["due"] for j in jobs]
    wt = [j["weight"] or 0 for j in jobs]
    preds = [sorted(set(idx[p] for p in j["after"])) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]: succs[p].append(i)
    modes = []; morig = []
    for j in jobs:
        ml = []; mo = []
        for mi, m in enumerate(j["modes"]):
            rq = m["requires"]
            if all(r in ridx and u <= maxcap[ridx[r]] for r, u in rq.items()):
                reqs = tuple((ridx[r], u) for r, u in rq.items() if u > 0)
                load = sum(u / max(1, maxcap[r]) for r, u in reqs) * m["duration"]
                ml.append((m["duration"], reqs, load)); mo.append(mi)
        modes.append(ml); morig.append(mo)
    T0 = max([resd[r]["calendar"][-1][0] for r in rnames] + rel + [0])
    H = T0 + sum(max(m[0] for m in ml) for ml in modes) + 16
    cap = []
    for r in rnames:
        cal = resd[r]["calendar"]; arr = [0]*H
        for k, (s, c) in enumerate(cal):
            e = cal[k+1][0] if k + 1 < len(cal) else H
            s = min(s, H); e = min(e, H)
            if e > s: arr[s:e] = [c]*(e - s)
        cap.append(arr)
    hasdue = [due[i] is not None for i in range(n)]

    def decode(order, msel):
        av = [c[:] for c in cap]
        st = [0]*n; md = [0]*n; fin = [0]*n
        cost = 0; mk = 0
        for j in order:
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est: est = fin[p]
            ml = modes[j]; ms = msel[j]
            cand = range(len(ml)) if ms < 0 else (ms,)
            best = None
            for m in cand:
                d, reqs, load = ml[m]
                t = est
                while True:
                    moved = False
                    for r, u in reqs:
                        a = av[r]
                        if min(a[t:t+d]) < u:
                            x = t + d - 1
                            while a[x] >= u: x -= 1
                            t = x + 1; moved = True; break
                    if not moved: break
                f = t + d
                sc = f
                if hasdue[j] and f > due[j]: sc += wt[j]*(f - due[j])
                key = (sc, load, f)
                if best is None or key < best[0]:
                    best = (key, m, t, f)
            _, m, t, f = best
            d, reqs, load = ml[m]
            for r, u in reqs:
                a = av[r]
                for x in range(t, f): a[x] -= u
            st[j] = t; md[j] = m; fin[j] = f
            if f > mk: mk = f
            if hasdue[j] and f > due[j]: cost += wt[j]*(f - due[j])
        return cost + mk, st, md

    mind = [min(m[0] for m in ml) for ml in modes]
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]; topo = []
    while q:
        i = q.pop(); topo.append(i)
        for s in succs[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    tail = [0]*n
    for i in reversed(topo):
        tail[i] = mind[i] + max([tail[s] for s in succs[i]] + [0])
    head = [0]*n
    for i in topo:
        head[i] = max([rel[i]] + [head[p] + mind[p] for p in preds[i]])
    nsucc = [0]*n
    for i in reversed(topo):
        nsucc[i] = len(succs[i]) + sum(nsucc[s] for s in succs[i])
    LB_cp = max(head[i] + mind[i] for i in range(n)) if n else 0
    big = LB_cp + sum(mind) + 1
    slack = [0]*n
    for i in range(n):
        lst = big - tail[i]
        if hasdue[i] and wt[i] > 0:
            lst = min(lst, due[i] - mind[i])
        slack[i] = lst

    def topo_by(key):
        deg = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h); out = []
        while h:
            _, i = heapq.heappop(h); out.append(i)
            for s in succs[i]:
                deg[s] -= 1
                if deg[s] == 0: heapq.heappush(h, (key[s], s))
        return out

    keys = []
    keys.append([-tail[i] for i in range(n)])
    keys.append([slack[i] for i in range(n)])
    keys.append([(slack[i], -tail[i]) for i in range(n)])
    keys.append([(head[i], -tail[i]) for i in range(n)])
    keys.append([-nsucc[i] for i in range(n)])
    keys.append([(rel[i], slack[i]) for i in range(n)])
    base = [-1]*n
    best = None
