        else:
            pos = {}
            for p_, j_ in enumerate(o): pos[j_] = p_
            i = rng.randrange(n)
            j = o[i]
            lo = max([pos[p] for p in preds[j]] + [-1]) + 1
            hi = min([pos[s] for s in succs[j]] + [n]) - 1
            if hi <= lo:
                continue
            npos = rng.randint(lo, hi)
            if npos == i: continue
            o = o[:i] + o[i+1:]
            o.insert(npos, j)
            if r > 0.85 and multi:
                ms = cur_m[:]
                jj = rng.choice(multi)
                ms[jj] = rng.randrange(-1, len(modes[jj]))
        c, st, md = decode(o, ms)
        dlt = c - cur_c
        if dlt <= 0 or rng.random() < pow(2.718281828, -dlt / T):
            cur_o = sorted(o, key=lambda x: st[x]) if dlt < 0 else o
            cur_m = ms; cur_c = c
            if c < best[0]:
                best = (c, o[:], ms[:], st, md); since = 0
        since += 1
        if since > 400:
            cur_c, cur_o, cur_m = best[0], best[1][:], best[2][:]; since = 0
    c, o, ms, st, md = best
    sch = {}
    for i in range(n):
        sch[jobs[i]["id"]] = {"start": int(st[i]), "mode": morig[i][md[i]]}
    return {"status": "ok", "schedule": sch}

