    preds = [sorted(set(idx[p] for p in j["after"])) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]: succs[p].append(i)
    predset = [set(p) for p in preds]
    modes = []; morig = []
    for j in jobs:
        ml = []; mo = []
        for mi, m in enumerate(j["modes"]):
            rq = m["requires"]
            if all(r in ridx and u <= maxcap[ridx[r]] for r, u in rq.items()):
                reqs = tuple((ridx[r], u) for r, u in rq.items() if u > 0)
                load = sum(u / max(1, maxcap[r]) for r, u in reqs) * m["duration"]
                rm = 0
                for r, u in reqs: rm |= (1 << r)
                ml.append((m["duration"], reqs, load, rm)); mo.append(mi)
        modes.append(ml); morig.append(mo)
    T0 = max([resd[r]["calendar"][-1][0] for r in rnames] + rel + [0])
    H = T0 + sum(max(m[0] for m in ml) for ml in modes) + 16
    cap = []
    for r in rnames:
        cal = resd[r]["calendar"]; arr = [0]*H
        for k, (s, c) in enumerate(cal):
            e = cal[k+1][0] if k + 1 < len(cal) else H
            s = min(s, H); e = min(e, H)
            if e > s: arr[s:e] = [c]*(e - s)
        cap.append(arr)
    hasdue = [due[i] is not None for i in range(n)]
    INF = 10**9

    mind = [min(m[0] for m in ml) for ml in modes]
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]; topo = []
    while q:
        i = q.pop(); topo.append(i)
        for s in succs[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    tail = [0]*n
    for i in reversed(topo):
        tail[i] = mind[i] + max([tail[s] for s in succs[i]] + [0])
    head = [0]*n
    for i in topo:
        head[i] = max([rel[i]] + [head[p] + mind[p] for p in preds[i]])
    nsucc = [0]*n
    for i in reversed(topo):
        nsucc[i] = len(succs[i]) + sum(nsucc[s] for s in succs[i])
    LB_cp = max(head[i] + mind[i] for i in range(n))
    rl = [0.0]*len(rnames)
    for i in range(n):
        bestl = None
        for d, reqs, load, rm in modes[i]:
            if bestl is None or load < bestl[0]: bestl = (load, d, reqs)
        for r, u in bestl[2]:
            rl[r] += u * bestl[1] / max(1, maxcap[r])
    Cb = max([LB_cp] + [int(x) for x in rl])

    deff = [INF]*n
    for i in range(n):
        if hasdue[i] and wt[i] > 0: deff[i] = due[i]
    for i in reversed(topo):
        for s in succs[i]:
            if deff[s] < INF:
                v = deff[s] - mind[s]
                if v < deff[i]: deff[i] = v
    desc = [0]*n
    for i in reversed(topo):
        b = 0
        for s in succs[i]: b |= (1 << s) | desc[s]
        desc[i] = b
    wdue = [wt[i] if (hasdue[i] and wt[i] > 0) else 0 for i in range(n)]
    Weff = [0]*n
    for i in range(n):
        tot = wdue[i]; b = desc[i]; k = 0
        while b:
            if b & 1: tot += wdue[k]
            b >>= 1; k += 1
        Weff[i] = tot
    pbar = max(1.0, sum(mind) / n)
    big = LB_cp + sum(mind) + 1
    slack = [0]*n
    for i in range(n):
        lst = big - tail[i]
        if hasdue[i] and wt[i] > 0:
            lst = min(lst, due[i] - mind[i])
        slack[i] = lst

    CPI = max(5, n // 10)

    # checkpointed serial decoder
    # sol = (cost, order, msel, st, md, fin, cps)
    def decode(order, msel, base, sp):
        if base is None or sp < CPI:
            k = 0
            av = [c[:] for c in cap]
            st = [0]*n; md = [0]*n; fin = [0]*n; cost = 0; mk = 0
            cps = [(cap, 0, 0)]
        else:
            k = sp // CPI
            bst, bmd, bfin, bcps = base[3], base[5 - 1], base[5], base[6]
            a0, cost, mk = bcps[k]
            av = [a[:] for a in a0]
            st = bst[:]; md = bmd[:]; fin = bfin[:]
            cps = bcps[:k+1]
        p0 = k * CPI
        for pi in range(p0, n):
            if pi != p0 and pi % CPI == 0:
                cps.append(([a[:] for a in av], cost, mk))
            j = order[pi]
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est: est = fin[p]
            ml = modes[j]; ms = msel[j]
            if ms >= 0:
                d, reqs, load, rm = ml[ms]
                t = _find(av, est, d, reqs); m = ms; f = t + d
            else:
                best = None
                dj = deff[j]; wj = Weff[j]
                for mm in range(len(ml)):
                    d, reqs, load, rm = ml[mm]
                    t = _find(av, est, d, reqs)
                    f = t + d
                    sc = f
                    if f > dj: sc += wj * (f - dj)
                    key = (sc, load, f)
                    if best is None or key < best[0]:
                        best = (key, mm, t, f)
                _, m, t, f = best
            for r, u in ml[m][1]:
                a = av[r]
                for x in range(t, f): a[x] -= u
            st[j] = t; md[j] = m; fin[j] = f
            if f > mk: mk = f
            if hasdue[j] and f > due[j]: cost += wt[j]*(f - due[j])
        return (cost + mk, order, msel, st, md, fin, cps)

    exp = math.exp

    def construct(k, kd, beta, eps, noise):
        av = [c[:] for c in cap]
        rem = [len(preds[i]) for i in range(n)]
        st = [0]*n; md = [0]*n; fin = [0]*n; est = [0]*n
        elig = [i for i in range(n) if rem[i] == 0]
        for i in elig: est[i] = rel[i]
        cache = [None]*n
        nz = [exp(rng.gauss(0, noise)) for _ in range(n)] if noise > 0 else [1.0]*n
        kp = k * pbar; kdp = kd * pbar if kd else 0
        order = []
        while elig:
            info = []; tmin = INF
            for j in elig:
                c = cache[j]
                if c is None:
                    c = [None]*len(modes[j]); cache[j] = c
                bm = None; dj = deff[j]; wj = Weff[j]
                for m, (d, reqs, load, rm) in enumerate(modes[j]):
                    o = c[m]
                    if o is None:
                        t = _find(av, est[j], d, reqs); o = (t, t + d); c[m] = o
                    t, f = o
                    mc = f + beta * load
                    if f > dj: mc += wj * (f - dj)
                    if bm is None or mc < bm[0]: bm = (mc, m, t, f)
                info.append((j, bm))
                if bm[2] < tmin: tmin = bm[2]
            bestk = None; bj = None
            for j, bm in info:
                _, m, t, f = bm
                d = f - t
                s = 0.0
                if deff[j] < INF:
                    sd = deff[j] - f
                    s += Weff[j] * (exp(-sd / kp) if sd > 0 else 1.0)
                sm = Cb - tail[j] + mind[j] - f
                s += eps * (exp(-sm / kp) if sm > 0 else 1.0)
                s = s / d * nz[j]
                if kdp: s *= exp(-(t - tmin) / kdp)
                key = (s, -t)
                if bestk is None or key > bestk:
                    bestk = key; bj = (j, m, t, f)
            j, m, t, f = bj
            d, reqs, load, rm = modes[j][m]
            for r, u in reqs:
                a = av[r]
                for x in range(t, f): a[x] -= u
            st[j] = t; md[j] = m; fin[j] = f
            order.append(j)
            elig.remove(j); cache[j] = None
            for e in elig:
                c = cache[e]
                if c is None: continue
                me = modes[e]
                for mi in range(len(c)):
                    o = c[mi]
                    if o is not None and o[0] < f and t < o[1] and (me[mi][3] & rm):
                        c[mi] = None
            for s_ in succs[j]:
                rem[s_] -= 1
                if rem[s_] == 0:
                    e0 = rel[s_]
                    for p in preds[s_]:
                        if fin[p] > e0: e0 = fin[p]
                    est[s_] = e0
                    elig.append(s_)
        mk = 0; c = 0
        for j in range(n):
            if fin[j] > mk: mk = fin[j]
            if hasdue[j] and fin[j] > due[j]: c += wt[j] * (fin[j] - due[j])
        return c + mk, order, md

    def topo_by(key):
        deg = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h); out = []
        while h:
            _, i = heapq.heappop(h); out.append(i)
            for s in succs[i]:
                deg[s] -= 1
                if deg[s] == 0: heapq.heappush(h, (key[s], s))
        return out

    base = [-1]*n
    best = None
    keys = [[-tail[i] for i in range(n)],
            [((deff[i] if deff[i] < INF else INF), -tail[i]) for i in range(n)],
            [-(Weff[i] + 0.5) / mind[i] for i in range(n)],
            [(head[i], -tail[i]) for i in range(n)],
            [-nsucc[i] for i in range(n)],
            [slack[i] for i in range(n)],
            [(slack[i], -tail[i]) for i in range(n)],
            [(rel[i], slack[i]) for i in range(n)]]
    for k in keys:
        o = topo_by(k)
        s = decode(o, base[:], None, 0)
        if best is None or s[0] < best[0]:
            best = s

    combos = []
    for k in (1.0, 2.0, 0.5, 4.0):
        for kd in (None, 2.0):
            combos.append((k, kd, 0.0, 1.0, 0.0))
    cphase = t0 + 0.30
    ci = 0
    sc = max(1.0, float(max(tail)))
    while True:
        if ci > 0 and time.process_time() >= cphase: break
        if ci < len(combos):
            prm = combos[ci]
        else:
            prm = (rng.choice([0.3, 0.5, 1.0, 2.0, 3.0, 5.0]), rng.choice([None, 1.0, 2.0, 4.0]),
                   rng.choice([0.0, 0.3, 1.0, 2.0]), rng.choice([0.2, 1.0, 3.0]),
                   rng.choice([0.1, 0.2, 0.4]))
        ci += 1
        c, o, md = construct(*prm)
        if c < best[0]:
            s = decode(o, md[:], None, 0)
            if s[0] < best[0]: best = s
        if ci % 4 == 0:
            noise = rng.random() * 0.5
            kk = [slack[i] + rng.gauss(0, noise * sc) for i in range(n)]
            s = decode(topo_by(kk), base[:], None, 0)
            if s[0] < best[0]: best = s
        if ci > 200: break

    multi = [i for i in range(n) if len(modes[i]) > 1]
    duejobs = [i for i in range(n) if hasdue[i] and wt[i] > 0]

    def mkpos(o):
        p = [0]*n
        for i_, j_ in enumerate(o): p[j_] = i_
        return p

    def mktard(s):
        fin = s[5]
        return [(x, wt[x] * (fin[x] - due[x])) for x in duejobs if fin[x] > due[x]]

    cur = best; cur_pos = mkpos(cur[1]); cur_tard = mktard(cur)
    it = 0; since = 0
    T = max(0.5, 0.02 * cur[0])
    start_sa = time.process_time(); span = max(1e-3, deadline - start_sa)
    while True:
        if (it & 3) == 0:
            now = time.process_time()
            if now >= deadline: break
            frac = (now - start_sa) / span
            T = max(0.05, 0.02 * best[0] * (1 - frac) ** 2)
        it += 1
        co = cur[1]; cm = cur[2]; cst = cur[3]; cfin = cur[5]
        o = co; ms = cm; sp = 0
        r = rng.random()
        if multi and r < 0.22:
            ms = cm[:]
            j = rng.choice(multi)
            k = len(modes[j])
            nv = rng.randrange(-1, k)
            if nv == ms[j]: nv = -1 if nv >= 0 else rng.randrange(k)
            ms[j] = nv
            sp = cur_pos[j]
        elif r < 0.34:
            i = rng.randrange(n - 1) if n > 1 else 0
            if n < 2: continue
            a_, b_ = co[i], co[i+1]
            if a_ in predset[b_]: continue
            o = co[:]
            o[i] = b_; o[i+1] = a_
            sp = i
        else:
            j = -1
            if r < 0.68 and cur_tard:
                tot = 0
                for _, v in cur_tard: tot += v
                x = rng.random() * tot
                for jj, v in cur_tard:
                    x -= v
                    if x <= 0:
                        j = jj; break
                if j < 0: j = cur_tard[-1][0]
                while rng.random() < 0.5:
                    bp = [p for p in preds[j] if cfin[p] >= cst[j]]
                    if not bp: break
                    j = rng.choice(bp)
            if j >= 0:
                i = cur_pos[j]
                lo = max([cur_pos[p] for p in preds[j]] + [-1]) + 1
                if lo >= i: continue
                npos = -1
                if rng.random() < 0.5 and hasdue[j]:
                    target = deff[j] - modes[j][cur[4][j]][0] if deff[j] < INF else due[j]
                    for pp in range(lo, i):
                        if cst[co[pp]] >= target:
                            npos = pp; break
                if npos < 0:
                    npos = rng.randint(lo, i - 1)
            else:
                i = rng.randrange(n)
                j = co[i]
                lo = max([cur_pos[p] for p in preds[j]] + [-1]) + 1
                hi = min([cur_pos[s] for s in succs[j]] + [n]) - 1
                if hi <= lo: continue
                npos = rng.randint(lo, hi)
                if npos == i: continue
            o = co[:i] + co[i+1:]
            o.insert(npos, j)
            sp = min(i, npos)
            if r > 0.93 and multi:
                ms = cm[:]
                jj = rng.choice(multi)
                ms[jj] = rng.randrange(-1, len(modes[jj]))
                sp = min(sp, cur_pos[jj] if cur_pos[jj] < sp else sp)
                # position of jj in new order may differ; be safe
                pj = o.index(jj)
                if pj < sp: sp = pj
        s = decode(o, ms, cur, sp)
        dlt = s[0] - cur[0]
        if dlt <= 0 or rng.random() < exp(-dlt / T):
            cur = s; cur_pos = mkpos(s[1]); cur_tard = mktard(s)
            if s[0] < best[0]:
                best = s; since = 0
        since += 1
        if since > 500:
            cur = best; cur_pos = mkpos(cur[1]); cur_tard = mktard(cur); since = 0
    st = best[3]; md = best[4]
    sch = {}
    for i in range(n):
        sch[jobs[i]["id"]] = {"start": int(st[i]), "mode": morig[i][md[i]]}
    return {"status": "ok", "schedule": sch}

import time, random, heapq

def _fallback(inp):
    res = inp["resources"]; jobs = inp["jobs"]
    T0 = 0
    for r in res.values():
        T0 = max(T0, r["calendar"][-1][0])
    for j in jobs:
        T0 = max(T0, j["release"])
    ids = [j["id"] for j in jobs]; idx = {k: i for i, k in enumerate(ids)}
    indeg = [0]*len(jobs); succ = [[] for _ in jobs]
    for i, j in enumerate(jobs):
        for p in set(j["after"]):
            indeg[i] += 1; succ[idx[p]].append(i)
    q = [i for i in range(len(jobs)) if indeg[i] == 0]; order = []
    while q:
        i = q.pop(); order.append(i)
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    t = T0; sch = {}
    for i in order:
        j = jobs[i]
        for mi, m in enumerate(j["modes"]):
            if all(r in res and u <= res[r]["calendar"][-1][1] for r, u in m["requires"].items()):
                sch[j["id"]] = {"start": t, "mode": mi}; t += m["duration"]; break
    return {"status": "ok", "schedule": sch}

def _check(inp):
    res = inp["resources"]; jobs = inp["jobs"]
    ids = set(j["id"] for j in jobs)
    for j in jobs:
        for p in j["after"]:
            if p not in ids:
                return "job %s references unknown predecessor %s" % (j["id"], p)
    for j in jobs:
        ok = False
        for m in j["modes"]:
            if all(r in res and u <= res[r]["calendar"][-1][1] for r, u in m["requires"].items()):
                ok = True; break
        if not ok:
            return "job %s has no feasible mode" % j["id"]
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    indeg = [0]*len(jobs); succ = [[] for _ in jobs]
    for i, j in enumerate(jobs):
        for p in set(j["after"]):
            indeg[i] += 1; succ[idx[p]].append(i)
    q = [i for i in range(len(jobs)) if indeg[i] == 0]; cnt = 0
    while q:
        i = q.pop(); cnt += 1
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    if cnt != len(jobs):
        return "precedence relation has a cycle"
    return None

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    reason = _check(inp)
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    try:
        state["output"] = _opt(inp, t0)
    except Exception:
        state["output"] = _fallback(inp)
    return state

def _opt(inp, t0):
    deadline = t0 + 0.8
    rng = random.Random(12345)
    resd = inp["resources"]; jobs = inp["jobs"]
    rnames = list(resd.keys()); ridx = {r: i for i, r in enumerate(rnames)}
    maxcap = [resd[r]["calendar"][-1][1] for r in rnames]
    n = len(jobs)
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    rel = [j["release"] for j in jobs]
    due = [j["due"] for j in jobs]
    wt = [j["weight"] or 0 for j in jobs]
    preds = [sorted(set(idx[p] for p in j["after"])) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]: succs[p].append(i)
    modes = []; morig = []
    for j in jobs:
        ml = []; mo = []
        for mi, m in enumerate(j["modes"]):
            rq = m["requires"]
            if all(r in ridx and u <= maxcap[ridx[r]] for r, u in rq.items()):
                reqs = tuple((ridx[r], u) for r, u in rq.items() if u > 0)
                load = sum(u / max(1, maxcap[r]) for r, u in reqs) * m["duration"]
                ml.append((m["duration"], reqs, load)); mo.append(mi)
        modes.append(ml); morig.append(mo)
    T0 = max([resd[r]["calendar"][-1][0] for r in rnames] + rel + [0])
    H = T0 + sum(max(m[0] for m in ml) for ml in modes) + 16
    cap = []
    for r in rnames:
        cal = resd[r]["calendar"]; arr = [0]*H
        for k, (s, c) in enumerate(cal):
            e = cal[k+1][0] if k + 1 < len(cal) else H
            s = min(s, H); e = min(e, H)
            if e > s: arr[s:e] = [c]*(e - s)
        cap.append(arr)
    hasdue = [due[i] is not None and wt[i] > 0 for i in range(n)]
    B = max(4, n // 12)
    R = len(cap)

    def decode(order, msel, k0, ck):
        avs, st0, md0, fin0, cost, mk = ck[k0]
        av = [a[:] for a in avs]
        st = st0[:]; md = md0[:]; fin = fin0[:]
        newck = ck[:k0+1]
        p0 = k0 * B
        for p in range(p0, n):
            if p > p0 and p % B == 0:
                newck.append(([a[:] for a in av], st[:], md[:], fin[:], cost, mk))
            j = order[p]
            est = rel[j]
            for q in preds[j]:
                if fin[q] > est: est = fin[q]
            ml = modes[j]; ms = msel[j]
            cand = range(len(ml)) if ms < 0 else (ms,)
            best = None
            for m in cand:
                d, reqs, load = ml[m]
                t = est
                while True:
                    moved = False
                    for r, u in reqs:
                        a = av[r]
                        if min(a[t:t+d]) < u:
                            x = t + d - 1
                            while a[x] >= u: x -= 1
                            t = x + 1; moved = True; break
                    if not moved: break
                f = t + d
                sc = f
                if hasdue[j] and f > due[j]: sc += wt[j]*(f - due[j])
                key = (sc, load, f)
                if best is None or key < best[0]:
                    best = (key, m, t, f)
            _, m, t, f = best
            d, reqs, load = ml[m]
            for r, u in reqs:
                a = av[r]
                for x in range(t, f): a[x] -= u
            st[j] = t; md[j] = m; fin[j] = f
            if f > mk: mk = f
            if hasdue[j] and f > due[j]: cost += wt[j]*(f - due[j])
        return cost + mk, st, md, fin, newck

    ck0 = [([c for c in cap], [0]*n, [0]*n, [0]*n, 0, 0)]

    mind = [min(m[0] for m in ml) for ml in modes]
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]; topo = []
    while q:
        i = q.pop(); topo.append(i)
        for s in succs[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    tail = [0]*n
    for i in reversed(topo):
        tail[i] = mind[i] + max([tail[s] for s in succs[i]] + [0])
    head = [0]*n
    for i in topo:
        head[i] = max([rel[i]] + [head[p] + mind[p] for p in preds[i]])
    nsucc = [0]*n
    for i in reversed(topo):
        nsucc[i] = len(succs[i]) + sum(nsucc[s] for s in succs[i])
    LB_cp = max(head[i] + mind[i] for i in range(n)) if n else 0
    big = LB_cp + sum(mind) + 1
    INF = big * 10 + 10**6
    edd = [INF]*n
    for i in reversed(topo):
        v = due[i] if hasdue[i] else INF
        for s in succs[i]:
            if edd[s] - mind[s] < v: v = edd[s] - mind[s]
        edd[i] = v
    lst = [min(edd[i] - mind[i], big - tail[i]) for i in range(n)]
    wsum = [0]*n
    for i in reversed(topo):
        wsum[i] = wt[i] + sum(wsum[s] for s in succs[i])

    def topo_by(key):
        deg = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h); out = []
        while h:
            _, i = heapq.heappop(h); out.append(i)
            for s in succs[i]:
                deg[s] -= 1
                if deg[s] == 0: heapq.heappush(h, (key[s], s))
        return out

    keys = []
    keys.append([(lst[i], -tail[i]) for i in range(n)])
    keys.append([(edd[i], -tail[i]) for i in range(n)])
    keys.append([(lst[i] - 2 * wsum[i], -tail[i]) for i in range(n)])
    keys.append([-tail[i] for i in range(n)])
    keys.append([(head[i], lst[i]) for i in range(n)])
    keys.append([-nsucc[i] for i in range(n)])
    keys.append([(rel[i], lst[i]) for i in range(n)])
    base = [-1]*n
    best = None
    for k in keys:
        o = topo_by(k)
        c, st, md, fin, ck = decode(o, base, 0, ck0)
        if best is None or c < best[0]:
            best = (c, o[:], base[:], st, md, fin, ck)
    sc = max(1.0, float(max(tail) if n else 1))
    tries = 0
    while time.process_time() < t0 + 0.15 and tries < 30:
        tries += 1
        noise = rng.random() * 0.5
        if tries % 3 == 0:
            k = [-tail[i] + rng.gauss(0, noise * sc) for i in range(n)]
        else:
            k = [lst[i] + rng.gauss(0, noise * sc) for i in range(n)]
        o = topo_by(k)
        c, st, md, fin, ck = decode(o, base, 0, ck0)
        if c < best[0]:
            best = (c, o[:], base[:], st, md, fin, ck)

    cur_c, cur_o, cur_m, cur_fin, cur_ck = best[0], best[1][:], best[2][:], best[5], best[6]

    def mkinfo(o, fin):
        pos = [0]*n
        for p_, j_ in enumerate(o): pos[j_] = p_
        tj = []; tw = []
        for j in range(n):
            if hasdue[j] and fin[j] > due[j]:
                tj.append(j); tw.append(wt[j]*(fin[j]-due[j]))
        mkv = max(fin) if n else 0
        last = [j for j in range(n) if fin[j] == mkv]
        return pos, tj, tw, last

    cur_pos, cur_tj, cur_tw, cur_last = mkinfo(cur_o, cur_fin)
    multi = [i for i in range(n) if len(modes[i]) > 1]
    T = max(0.5, 0.02 * cur_c)
    it = 0; since = 0
    stall = max(300, 4 * n)
    start_sa = time.process_time(); span = max(1e-3, deadline - start_sa)
    while True:
        if (it & 3) == 0:
            now = time.process_time()
            if now >= deadline: break
            frac = (now - start_sa) / span
            T = max(0.05, 0.03 * best[0] * (1 - frac) ** 2)
        it += 1
        o = cur_o; ms = cur_m
        pos = cur_pos
        r = rng.random()
        chg = n
        if multi and r < 0.2:
            ms = cur_m[:]
            j = rng.choice(multi)
            k = len(modes[j])
            nv = rng.randrange(-1, k)
            if nv == ms[j]: nv = -1 if nv >= 0 else rng.randrange(k)
            ms[j] = nv
            chg = pos[j]
        elif r < 0.55:
            # pull a tardy / critical job earlier with its ancestors
            if cur_tj and rng.random() < 0.75:
                j = rng.choices(cur_tj, weights=cur_tw)[0]
            elif cur_last:
                j = rng.choice(cur_last)
            else:
                j = rng.randrange(n)
            i = pos[j]
            if i == 0: continue
            spn = rng.randint(1, max(1, min(i, max(3, n // 4))))
            npos = i - spn if rng.random() < 0.8 else rng.randint(0, i - 1)
            mark = {j}
            seg = o[npos:i+1]
            for qq in range(len(seg) - 2, -1, -1):
                x = seg[qq]
                for s in succs[x]:
                    if s in mark:
                        mark.add(x); break
            if seg[0] in mark and len(mark) == len(seg): continue
            mv = [x for x in seg if x in mark]
            rest = [x for x in seg if x not in mark]
            o = o[:npos] + mv + rest + o[i+1:]
            chg = npos
        elif r < 0.7:
            # push a job later with its descendants
            j = rng.randrange(n)
            i = pos[j]
            if i >= n - 1: continue
            spn = rng.randint(1, max(1, min(n - 1 - i, max(3, n // 4))))
            npos = i + spn
            mark = {j}
            seg = o[i:npos+1]
            for qq in range(1, len(seg)):
                x = seg[qq]
                for p in preds[x]:
                    if p in mark:
                        mark.add(x); break
            if len(mark) == len(seg): continue
            mv = [x for x in seg if x in mark]
            rest = [x for x in seg if x not in mark]
            o = o[:i] + rest + mv + o[npos+1:]
            chg = i
        else:
            i = rng.randrange(n)
            j = o[i]
            lo = max([pos[p] for p in preds[j]] + [-1]) + 1
            hi = min([pos[s] for s in succs[j]] + [n]) - 1
            if hi <= lo:
                continue
            npos = rng.randint(lo, hi)
            if npos == i: continue
            o = o[:i] + o[i+1:]
            o.insert(npos, j)
            chg = min(i, npos)
        if r > 0.9 and multi:
            if ms is cur_m: ms = cur_m[:]
            jj = rng.choice(multi)
            ms[jj] = rng.randrange(-1, len(modes[jj]))
            chg = min(chg, pos[jj])
        if chg >= n: continue
        k0 = chg // B
        if k0 >= len(cur_ck): k0 = len(cur_ck) - 1
        c, st, md, fin, ck = decode(o, ms, k0, cur_ck)
        dlt = c - cur_c
        if dlt <= 0 or rng.random() < pow(2.718281828, -dlt / T):
            cur_o = o; cur_m = ms; cur_c = c; cur_fin = fin; cur_ck = ck
            cur_pos, cur_tj, cur_tw, cur_last = mkinfo(cur_o, cur_fin)
            if c < best[0]:
                best = (c, o[:], ms[:], st, md, fin, ck); since = 0
        since += 1
        if since > stall:
            cur_c, cur_o, cur_m, cur_fin, cur_ck = best[0], best[1][:], best[2][:], best[5], best[6]
            cur_pos, cur_tj, cur_tw, cur_last = mkinfo(cur_o, cur_fin)
            since = 0
    c, o, ms, st, md, fin, ck = best
    sch = {}
    for i in range(n):
        sch[jobs[i]["id"]] = {"start": int(st[i]), "mode": morig[i][md[i]]}
    return {"status": "ok", "schedule": sch}

import time, random, heapq, math

def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.72
    rng = random.Random(20261123)
    inp = state.get("input") or {}
    res_in = inp.get("resources") or {}
    jobs_in = inp.get("jobs") or []
    n = len(jobs_in)

    def infeas(msg):
        state["output"] = {"status": "infeasible", "reason": msg}
        return state

    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    ids = [j.get("id") for j in jobs_in]
    idx = {}
    for i in range(n):
        idx[ids[i]] = i
    preds = [[] for _ in range(n)]
    for i in range(n):
        seen = set()
        for p in (jobs_in[i].get("after") or []):
            if p not in idx:
                return infeas("job %s references unknown predecessor %s" % (ids[i], p))
            q = idx[p]
            if q not in seen:
                seen.add(q)
                preds[i].append(q)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    queue = [i for i in range(n) if indeg[i] == 0]
    qi = 0
    while qi < len(queue):
        x = queue[qi]; qi += 1
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if len(queue) < n:
        return infeas("precedence relation contains a cycle")
    topo = queue

    rnames = list(res_in.keys())
    rid = {}
    for k, nm in enumerate(rnames):
        rid[nm] = k
    cals = []
    maxcap = []
    for nm in rnames:
        rc = res_in[nm]
        cal = rc.get("calendar") if isinstance(rc, dict) else None
        if not cal:
            cal = [[0, 0]]
        cal = sorted([(int(a[0]), int(a[1])) for a in cal])
        cals.append(cal)
        maxcap.append(cal[-1][1])
    R = len(rnames)

    MODES = []
    for i in range(n):
        vm = []
        for mi, m in enumerate(jobs_in[i].get("modes") or []):
            d = int(m.get("duration", 1))
            req = m.get("requires") or {}
            ok = True
            rq = []
            ld = 0.0
            for rn, u in req.items():
                u = int(u)
                if rn not in rid:
                    ok = False; break
                r = rid[rn]
                if u > maxcap[r]:
                    ok = False; break
                if u > 0:
                    rq.append((r, u))
                    ld += d * u / max(1, maxcap[r])
            if ok and d >= 0:
                vm.append((d, rq, mi, ld))
        if not vm:
            return infeas("job %s has no mode fitting known resources' maximum capacity" % (ids[i],))
        MODES.append(vm)

    rel = [max(0, int(jobs_in[i].get("release") or 0)) for i in range(n)]
    due = []
    for i in range(n):
        dv = jobs_in[i].get("due")
        due.append(None if dv is None else int(dv))
    w = [int(jobs_in[i].get("weight") or 0) for i in range(n)]
    dueJobs = [i for i in range(n) if due[i] is not None and w[i] > 0]

    lastbp = 0
    for cal in cals:
        lastbp = max(lastbp, cal[-1][0])
    sumd = sum(max(m[0] for m in MODES[i]) for i in range(n))
    H = lastbp + max(rel) + sumd + 5

    cap = []
    for r in range(R):
        arr = [0] * H
        cal = cals[r]
        for k in range(len(cal)):
            a = max(0, min(cal[k][0], H))
            b = cal[k + 1][0] if k + 1 < len(cal) else H
            b = max(0, min(b, H))
            if b > a:
                arr[a:b] = [cal[k][1]] * (b - a)
        cap.append(arr)
    free = [c[:] for c in cap]

    start = [0] * n
    mode = [0] * n
    fin = [0] * n

    def earliest(req, d, est, lim):
        if lim > H - d:
            lim = H - d
        t = est
        while t <= lim:
            bad = -1
            for r, u in req:
                fr = free[r]
                e = t + d - 1
                while e >= t:
                    if fr[e] < u:
                        bad = e; break
                    e -= 1
                if bad >= 0:
                    break
            if bad < 0:
                return t
            t = bad + 1
        return -1

    def latest(req, d, lo, hi):
        if hi > H - d:
            hi = H - d
        t = hi
        while t >= lo:
            bad = -1
            for r, u in req:
                fr = free[r]
                e = t
                end = t + d
                while e < end:
                    if fr[e] < u:
                        bad = e; break
                    e += 1
                if bad >= 0:
                    break
            if bad < 0:
                return t
            t = bad - d
        return -1

    def place(i):
        d = MODES[i][mode[i]][0]
        s = start[i]
        for r, u in MODES[i][mode[i]][1]:
            fr = free[r]
            for t in range(s, s + d):
                fr[t] -= u

    def unplace(i):
        d = MODES[i][mode[i]][0]
        s = start[i]
        for r, u in MODES[i][mode[i]][1]:
            fr = free[r]
            for t in range(s, s + d):
                fr[t] += u

    def choose(i, est, limf, alpha):
        bm = -1; bt = -1; bs = None
        di = due[i]; wi = w[i]
        for mi, md in enumerate(MODES[i]):
            d = md[0]
            ls = (limf - d) if limf is not None else H - d
            if ls > H - d:
                ls = H - d
            if ls < est:
                continue
            t = earliest(md[1], d, est, ls)
            if t < 0:
                continue
            f = t + d
            sc = f + alpha * md[3]
            if di is not None and f > di:
                sc += wi * (f - di)
            if bs is None or sc < bs:
                bs = sc; bm = mi; bt = t
        return bm, bt

    def cost():
        c = max(fin)
        for i in dueJobs:
            if fin[i] > due[i]:
                c += w[i] * (fin[i] - due[i])
        return c

    def snapshot():
        return (start[:], mode[:])

    def load_sol(sol):
        for r in range(R):
            free[r][:] = cap[r]
        st, md = sol
        for i in range(n):
            start[i] = st[i]; mode[i] = md[i]
            fin[i] = st[i] + MODES[i][md[i]][0]
            place(i)

    # static priorities
    mind = [min(m[0] for m in MODES[i]) for i in range(n)]
    tail = [0] * n
    lf = [0] * n
    for i in reversed(topo):
        tl = 0
        l = H if due[i] is None else due[i]
        for s in succs[i]:
            if tail[s] > tl:
                tl = tail[s]
            if lf[s] - mind[s] < l:
                l = lf[s] - mind[s]
        tail[i] = mind[i] + tl
        lf[i] = l
    es = [0] * n
    for i in topo:
        e = rel[i]
        for p in preds[i]:
            if es[p] + mind[p] > e:
                e = es[p] + mind[p]
        es[i] = e
    lstkey = [lf[i] - mind[i] for i in range(n)]

    def sgs(keys, alpha):
        for r in range(R):
            free[r][:] = cap[r]
        deg = [len(preds[i]) for i in range(n)]
        hp = [(keys[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(hp)
        while hp:
            _, i = heapq.heappop(hp)
            est = rel[i]
            for p in preds[i]:
                if fin[p] > est:
                    est = fin[p]
            mi, t = choose(i, est, None, alpha)
            if mi < 0:
                return False
            mode[i] = mi; start[i] = t; fin[i] = t + MODES[i][mi][0]
            place(i)
            for s in succs[i]:
                deg[s] -= 1
                if deg[s] == 0:
                    heapq.heappush(hp, (keys[s], s))
        return True

    def compact():
        order = sorted(range(n), key=lambda i: (start[i], fin[i]))
        for i in order:
            unplace(i)
            est = rel[i]
            for p in preds[i]:
                if fin[p] > est:
                    est = fin[p]
            mi, t = choose(i, est, fin[i], 0.0)
            if mi >= 0:
                mode[i] = mi; start[i] = t; fin[i] = t + MODES[i][mi][0]
            place(i)

    def right_shift():
        ms = max(fin)
        order = sorted(range(n), key=lambda i: (-fin[i], -start[i]))
        for i in order:
            unplace(i)
            lfv = ms
            for s in succs[i]:
                if start[s] < lfv:
                    lfv = start[s]
            d = MODES[i][mode[i]][0]
            t = latest(MODES[i][mode[i]][1], d, start[i], lfv - d)
            if t >= start[i]:
                start[i] = t; fin[i] = t + d
            place(i)

    # ---------- initial constructions ----------
    bestsol = None
    best = None
    rules = [
        [(lstkey[i], -tail[i]) for i in range(n)],
        [(-tail[i], lstkey[i]) for i in range(n)],
        [(es[i], lstkey[i]) for i in range(n)],
        [(min(lstkey[i], es[i] + 3 * mind[i]), -tail[i]) for i in range(n)],
    ]
    for keys in rules:
        for alpha in (0.0, 0.3):
            if sgs(keys, alpha):
                c = cost()
                if best is None or c < best:
                    best = c; bestsol = snapshot()
    k2 = 0
    while time.process_time() - T0 < 0.12 * BUDGET and k2 < 12:
        k2 += 1
        keys = [(lstkey[i] + rng.random() * (5 + k2), rng.random()) for i in range(n)]
        if sgs(keys, rng.choice((0.0, 0.0, 0.3))):
            c = cost()
            if best is None or c < best:
                best = c; bestsol = snapshot()

    if bestsol is None:
        # fallback: strictly sequential
        for r in range(R):
            free[r][:] = cap[r]
        tcur = 0
        for i in topo:
            est = max(rel[i], tcur)
            for p in preds[i]:
                est = max(est, fin[p])
            mi, t = choose(i, est, None, 0.0)
            mode[i] = mi; start[i] = t; fin[i] = t + MODES[i][mi][0]
            place(i); tcur = fin[i]
        best = cost(); bestsol = snapshot()

    load_sol(bestsol)
    compact()
    c = cost()
    if c <= best:
        best = c; bestsol = snapshot()
    snap = snapshot()
    right_shift(); compact()
    c = cost()
    if c < best:
        best = c; bestsol = snapshot()
    else:
        load_sol(bestsol)
    cur = best

    # ---------- LNS ----------
    pending = [False] * n

    def destroy_repair(Rl, keymode, alpha):
        old = [(i, start[i], mode[i]) for i in Rl]
        for i in Rl:
            unplace(i); pending[i] = True
        deg = {}
        for i in Rl:
            cnt = 0
            for p in preds[i]:
                if pending[p]:
                    cnt += 1
            deg[i] = cnt
        key = {}
        for i in Rl:
            if keymode == 0:
                key[i] = start[i] + rng.random() * 3.0
            elif keymode == 1:
                key[i] = lstkey[i] + rng.random() * 3.0
            elif keymode == 2:
                key[i] = rng.random()
            else:
                key[i] = (due[i] if due[i] is not None else lf[i]) - mind[i] * w[i] * 0.1 + rng.random()
        hp = [(key[i], i) for i in Rl if deg[i] == 0]
        heapq.heapify(hp)
        done = []
        okf = True
        while hp:
            _, i = heapq.heappop(hp)
            est = rel[i]
            for p in preds[i]:
                if fin[p] > est:
                    est = fin[p]
            limf = None
            for s in succs[i]:
                if not pending[s]:
                    if limf is None or start[s] < limf:
                        limf = start[s]
            mi, t = choose(i, est, limf, alpha)
            if mi < 0:
                okf = False; break
            mode[i] = mi; start[i] = t; fin[i] = t + MODES[i][mi][0]
            place(i); pending[i] = False; done.append(i)
            for s in succs[i]:
                if s in deg:
                    deg[s] -= 1
                    if deg[s] == 0:
                        heapq.heappush(hp, (key[s], s))
        if not okf or len(done) < len(Rl):
            for i in done:
                unplace(i)
            for (i, s, m) in old:
                pending[i] = False
                start[i] = s; mode[i] = m; fin[i] = s + MODES[i][m][0]
                place(i)
            return None
        return old

    def revert(old):
        for (i, _, _) in old:
            unplace(i)
        for (i, s, m) in old:
            start[i] = s; mode[i] = m; fin[i] = s + MODES[i][m][0]
            place(i)

    def pick_seed():
        tardy = [i for i in dueJobs if fin[i] > due[i]]
        if tardy and rng.random() < 0.6:
            return rng.choices(tardy, weights=[w[i] * (fin[i] - due[i]) for i in tardy])[0]
        ms = max(fin)
        cands = [i for i in range(n) if fin[i] == ms]
        if rng.random() < 0.8:
            return rng.choice(cands)
        return rng.randrange(n)

    def pick_window(k):
        order = sorted(range(n), key=lambda i: start[i])
        if rng.random() < 0.5:
            sd = pick_seed()
            pos = order.index(sd)
            lo = max(0, pos - k + 1 + rng.randint(0, max(0, k // 3)))
        else:
            lo = rng.randrange(max(1, n - k + 1))
        return order[lo:lo + k]

    def pick_critical(k):
        sd = pick_seed()
        S = [sd]; inS = {sd}
        tries = 0
        while len(S) < k and tries < 4 * k:
            tries += 1
            x = rng.choice(S)
            if preds[x] and rng.random() < 0.45:
                y = rng.choice(preds[x])
            else:
                sx = start[x]; fx = fin[x]
                c = [i for i in range(n) if i not in inS and start[i] < fx and fin[i] >= sx]
                if not c:
                    continue
                y = rng.choice(c)
            if y not in inS:
                inS.add(y); S.append(y)
        return S

    kmax = max(2, min(n, 6 + n // 8))
    temp0 = max(2.0, 0.02 * cur)
    it = 0
    last_imp = 0
    frac = 0.0
    while True:
        if (it & 3) == 0:
            el = time.process_time() - T0
            if el > BUDGET:
                break
            frac = el / BUDGET
        it += 1
        k = rng.randint(2, kmax) if kmax > 2 else kmax
        u = rng.random()
        if u < 0.4:
            Rl = pick_window(k)
        elif u < 0.85:
            Rl = pick_critical(k)
        else:
            Rl = rng.sample(range(n), min(k, n))
        if not Rl:
            continue
        keymode = rng.choices((0, 1, 2, 3), weights=(0.45, 0.25, 0.1, 0.2))[0]
        alpha = rng.choice((0.0, 0.0, 0.0, 0.2, 0.5))
        old = destroy_repair(Rl, keymode, alpha)
        if old is None:
            continue
        c = cost()
        if c < best:
            compact()
            c = cost()
        delta = c - cur
        temp = temp0 * (1.0 - frac) + 0.05
        if delta <= 0 or rng.random() < math.exp(-delta / temp):
            cur = c
            if c < best:
                best = c; bestsol = snapshot(); last_imp = it
        else:
            revert(old)
        if it % 80 == 0:
            compact()
            cur = cost()
            if cur < best:
                best = cur; bestsol = snapshot(); last_imp = it
        if it - last_imp > 350:
            last_imp = it
            load_sol(bestsol)
            right_shift(); compact()
            c = cost()
            if c < best:
                best = c; bestsol = snapshot()
            else:
                load_sol(bestsol)
            cur = best

    # ---------- verify & output ----------
    st, md = bestsol

    def verify(st, md):
        use = [[0] * H for _ in range(R)]
        for i in range(n):
            if st[i] < rel[i] or st[i] < 0:
                return False
            d = MODES[i][md[i]][0]
            if st[i] + d > H:
                return False
            for p in preds[i]:
                if st[i] < st[p] + MODES[p][md[p]][0]:
                    return False
            for r, u in MODES[i][md[i]][1]:
                ur = use[r]
                for t in range(st[i], st[i] + d):
                    ur[t] += u
        for r in range(R):
            ur = use[r]; cr = cap[r]
            for t in range(H):
                if ur[t] > cr[t]:
                    return False
        return True

    if not verify(st, md):
        for r in range(R):
            free[r][:] = cap[r]
        tcur = 0
        for i in topo:
            est = max(rel[i], tcur)
            for p in preds[i]:
                est = max(est, fin[p])
            mi, t = choose(i, est, None, 0.0)
            if mi < 0:
                mi = 0; t = est
            mode[i] = mi; start[i] = t; fin[i] = t + MODES[i][mi][0]
            place(i); tcur = fin[i]
        st, md = start[:], mode[:]

    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(MODES[i][md[i]][2])}
    state["output"] = {"status": "ok", "schedule": sched}
    return state

import time, random, heapq, math

def _fallback(inp):
    res = inp["resources"]; jobs = inp["jobs"]
    T0 = 0
    for r in res.values():
        T0 = max(T0, r["calendar"][-1][0])
    for j in jobs:
        T0 = max(T0, j["release"])
    ids = [j["id"] for j in jobs]; idx = {k: i for i, k in enumerate(ids)}
    indeg = [0]*len(jobs); succ = [[] for _ in jobs]
    for i, j in enumerate(jobs):
        for p in set(j["after"]):
            indeg[i] += 1; succ[idx[p]].append(i)
    q = [i for i in range(len(jobs)) if indeg[i] == 0]; order = []
    while q:
        i = q.pop(); order.append(i)
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    t = T0; sch = {}
    for i in order:
        j = jobs[i]
        for mi, m in enumerate(j["modes"]):
            if all(r in res and u <= res[r]["calendar"][-1][1] for r, u in m["requires"].items()):
                sch[j["id"]] = {"start": t, "mode": mi}; t += m["duration"]; break
    return {"status": "ok", "schedule": sch}

def _check(inp):
    res = inp["resources"]; jobs = inp["jobs"]
    ids = set(j["id"] for j in jobs)
    for j in jobs:
        for p in j["after"]:
            if p not in ids:
                return "job %s references unknown predecessor %s" % (j["id"], p)
    for j in jobs:
        ok = False
        for m in j["modes"]:
            if all(r in res and u <= res[r]["calendar"][-1][1] for r, u in m["requires"].items()):
                ok = True; break
        if not ok:
            return "job %s has no feasible mode" % j["id"]
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    indeg = [0]*len(jobs); succ = [[] for _ in jobs]
    for i, j in enumerate(jobs):
        for p in set(j["after"]):
            indeg[i] += 1; succ[idx[p]].append(i)
    q = [i for i in range(len(jobs)) if indeg[i] == 0]; cnt = 0
    while q:
        i = q.pop(); cnt += 1
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    if cnt != len(jobs):
        return "precedence relation has a cycle"
    return None

def _verify(inp, out):
    try:
        res = inp["resources"]; jobs = inp["jobs"]; sch = out["schedule"]
        fin = {}
        for j in jobs:
            e = sch.get(j["id"])
            if e is None: return False
            s = e["start"]; m = e["mode"]
            if not isinstance(s, int) or not isinstance(m, int): return False
            if s < j["release"] or m < 0 or m >= len(j["modes"]): return False
            fin[j["id"]] = s + j["modes"][m]["duration"]
        for j in jobs:
            for p in j["after"]:
                if sch[j["id"]]["start"] < fin[p]: return False
        H = max(list(fin.values()) + [1]) + 1
        for rn, rd in res.items():
            cal = rd["calendar"]; arr = [0]*H
            for k, (s, c) in enumerate(cal):
                e = cal[k+1][0] if k + 1 < len(cal) else H
                s = min(s, H); e = min(e, H)
                if e > s: arr[s:e] = [c]*(e - s)
            use = [0]*H
            for j in jobs:
                e = sch[j["id"]]; md = j["modes"][e["mode"]]
                u = md["requires"].get(rn, 0)
                if u:
                    for x in range(e["start"], e["start"] + md["duration"]): use[x] += u
            for x in range(H):
                if use[x] > arr[x]: return False
        for j in jobs:
            md = j["modes"][sch[j["id"]]["mode"]]
            for r in md["requires"]:
                if r not in res: return False
        return True
    except Exception:
        return False

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    reason = _check(inp)
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    try:
        out = _opt(inp, t0)
        if not _verify(inp, out):
            out = _fallback(inp)
    except Exception:
        out = _fallback(inp)
    state["output"] = out
    return state

def _find(av, t, d, reqs):
    while True:
        moved = False
        for r, u in reqs:
            a = av[r]
            if min(a[t:t+d]) < u:
                x = t + d - 1
                while a[x] >= u: x -= 1
                t = x + 1; moved = True; break
        if not moved:
            return t

def _opt(inp, t0):
    deadline = t0 + 0.8
    rng = random.Random(4242)
    resd = inp["resources"]; jobs = inp["jobs"]
    rnames = list(resd.keys()); ridx = {r: i for i, r in enumerate(rnames)}
    maxcap = [resd[r]["calendar"][-1][1] for r in rnames]
    n = len(jobs)
    if n == 0:
        return {"status": "ok", "schedule": {}}
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    rel = [j["release"] for j in jobs]
    due = [j["due"] for j in jobs]
    wt = [j["weight"] or 0 for j in jobs]
    preds = [sorted(set(idx[p] for p in j["after"])) for j in jobs]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]: succs[p].append(i)
    modes = []; morig = []
    for j in jobs:
        ml = []; mo = []
        for mi, m in enumerate(j["modes"]):
            rq = m["requires"]
            if all(r in ridx and u <= maxcap[ridx[r]] for r, u in rq.items()):
                reqs = tuple((ridx[r], u) for r, u in rq.items() if u > 0)
                load = sum(u / max(1, maxcap[r]) for r, u in reqs) * m["duration"]
                rm = 0
                for r, u in reqs: rm |= (1 << r)
                ml.append((m["duration"], reqs, load, rm)); mo.append(mi)
        modes.append(ml); morig.append(mo)
    T0 = max([resd[r]["calendar"][-1][0] for r in rnames] + rel + [0])
    H = T0 + sum(max(m[0] for m in ml) for ml in modes) + 16
    cap = []
    for r in rnames:
        cal = resd[r]["calendar"]; arr = [0]*H
        for k, (s, c) in enumerate(cal):
            e = cal[k+1][0] if k + 1 < len(cal) else H
            s = min(s, H); e = min(e, H)
            if e > s: arr[s:e] = [c]*(e - s)
        cap.append(arr)
    hasdue = [due[i] is not None for i in range(n)]
    INF = 10**9
    duev = [due[i] if hasdue[i] else INF for i in range(n)]

    mind = [min(m[0] for m in ml) for ml in modes]
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]; topo = []
    while q:
        i = q.pop(); topo.append(i)
        for s in succs[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    tail = [0]*n
    for i in reversed(topo):
        tail[i] = mind[i] + max([tail[s] for s in succs[i]] + [0])
    head = [0]*n
    for i in topo:
        head[i] = max([rel[i]] + [head[p] + mind[p] for p in preds[i]])
    nsucc = [0]*n
    for i in reversed(topo):
        nsucc[i] = len(succs[i]) + sum(nsucc[s] for s in succs[i])
    LB_cp = max(head[i] + mind[i] for i in range(n))
    rl = [0.0]*len(rnames)
    for i in range(n):
        bestl = None
        for d, reqs, load, rm in modes[i]:
            if bestl is None or load < bestl[0]: bestl = (load, d, reqs)
        for r, u in bestl[2]:
            rl[r] += u * bestl[1] / max(1, maxcap[r])
    Cb = max([LB_cp] + [int(x) for x in rl])
    big = LB_cp + sum(mind) + 1

    deff = [INF]*n
    for i in range(n):
        if hasdue[i] and wt[i] > 0: deff[i] = due[i]
    for i in reversed(topo):
        for s in succs[i]:
            if deff[s] < INF:
                v = deff[s] - mind[s]
                if v < deff[i]: deff[i] = v
    desc = [0]*n
    for i in reversed(topo):
        b = 0
        for s in succs[i]: b |= (1 << s) | desc[s]
        desc[i] = b
    wdue = [wt[i] if (hasdue[i] and wt[i] > 0) else 0 for i in range(n)]
    Weff = [0]*n
    for i in range(n):
        tot = wdue[i]; b = desc[i]; k = 0
        while b:
            if b & 1: tot += wdue[k]
            b >>= 1; k += 1
        Weff[i] = tot
    pbar = max(1.0, sum(mind) / n)
    slack = [0]*n
    for i in range(n):
        lst = big - tail[i]
        if deff[i] < INF:
            lst = min(lst, deff[i] - mind[i])
        slack[i] = lst

    K = max(4, n // 10)

    def decode(order, msel, p0=0, snaps=None, st0=None, md0=None, fin0=None):
        ck = p0 // K
        if snaps is None or ck == 0 or ck >= len(snaps):
            ck = 0
            av = [c[:] for c in cap]; cost = 0; mk = 0
            st = [0]*n; md = [0]*n; fin = [0]*n; ns = []
        else:
            a0, cost, mk = snaps[ck]
            av = [a[:] for a in a0]
            st = st0[:]; md = md0[:]; fin = fin0[:]; ns = snaps[:ck]
        for pos in range(ck * K, n):
            if pos % K == 0:
                ns.append(([a[:] for a in av], cost, mk))
            j = order[pos]
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est: est = fin[p]
            ml = modes[j]; ms = msel[j]
            if ms >= 0 or len(ml) == 1:
                m = ms if ms >= 0 else 0
                d = ml[m][0]
                t = _find(av, est, d, ml[m][1]); f = t + d
            else:
                if ms == -1:
                    dj = duev[j]; wj = wt[j]
                else:
                    dj = deff[j]; wj = Weff[j]
                bk = None
                for mm in range(len(ml)):
                    d, reqs, load, rm = ml[mm]
                    tt = _find(av, est, d, reqs)
                    ff = tt + d
                    sc = ff
                    if ff > dj: sc += wj * (ff - dj)
                    key = (sc, load, ff)
                    if bk is None or key < bk:
                        bk = key; m = mm; t = tt; f = ff
            for r, u in ml[m][1]:
                a = av[r]
                a[t:f] = [v - u for v in a[t:f]]
            st[j] = t; md[j] = m; fin[j] = f
            if f > mk: mk = f
            if f > duev[j]: cost += wt[j] * (f - duev[j])
        return cost + mk, st, md, fin, ns

    def cost_of(st, md):
        mk = 0; c = 0
        for j in range(n):
            f = st[j] + modes[j][md[j]][0]
            if f > mk: mk = f
            if f > duev[j]: c += wt[j] * (f - duev[j])
        return c + mk

    exp = math.exp

    def construct(k, kd, beta, eps, noise):
        av = [c[:] for c in cap]
        rem = [len(preds[i]) for i in range(n)]
        st = [0]*n; md = [0]*n; fin = [0]*n; est = [0]*n
        elig = [i for i in range(n) if rem[i] == 0]
        for i in elig: est[i] = rel[i]
        cache = [None]*n
        nz = [exp(rng.gauss(0, noise)) for _ in range(n)] if noise > 0 else [1.0]*n
        kp = k * pbar; kdp = kd * pbar if kd else 0
        order = []
        while elig:
            info = []; tmin = INF
            for j in elig:
                c = cache[j]
                if c is None:
                    c = [None]*len(modes[j]); cache[j] = c
                bm = None; dj = deff[j]; wj = Weff[j]
                for m, (d, reqs, load, rm) in enumerate(modes[j]):
                    o = c[m]
                    if o is None:
                        t = _find(av, est[j], d, reqs); o = (t, t + d); c[m] = o
                    t, f = o
                    mc = f + beta * load
                    if f > dj: mc += wj * (f - dj)
                    if bm is None or mc < bm[0]: bm = (mc, m, t, f)
                info.append((j, bm))
                if bm[2] < tmin: tmin = bm[2]
            bestk = None; bj = None
            for j, bm in info:
                _, m, t, f = bm
                d = f - t
                s = 0.0
                if deff[j] < INF:
                    sd = deff[j] - f
                    s += Weff[j] * (exp(-sd / kp) if sd > 0 else 1.0)
                sm = Cb - tail[j] + mind[j] - f
                s += eps * (exp(-sm / kp) if sm > 0 else 1.0)
                s = s / d * nz[j]
                if kdp: s *= exp(-(t - tmin) / kdp)
                key = (s, -t)
                if bestk is None or key > bestk:
                    bestk = key; bj = (j, m, t, f)
            j, m, t, f = bj
            d, reqs, load, rm = modes[j][m]
            for r, u in reqs:
                a = av[r]
                a[t:f] = [v - u for v in a[t:f]]
            st[j] = t; md[j] = m; fin[j] = f
            order.append(j)
            elig.remove(j); cache[j] = None
            for e in elig:
                c = cache[e]
                if c is None: continue
                me = modes[e]
                for mi in range(len(c)):
                    o = c[mi]
                    if o is not None and o[0] < f and t < o[1] and (me[mi][3] & rm):
                        c[mi] = None
            for s_ in succs[j]:
                rem[s_] -= 1
                if rem[s_] == 0:
                    e0 = rel[s_]
                    for p in preds[s_]:
                        if fin[p] > e0: e0 = fin[p]
                    est[s_] = e0
                    elig.append(s_)
        return cost_of(st, md), order, md, st

    def topo_by(key):
        deg = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h); out = []
        while h:
            _, i = heapq.heappop(h); out.append(i)
            for s in succs[i]:
                deg[s] -= 1
                if deg[s] == 0: heapq.heappush(h, (key[s], s))
        return out

    best = [None]

    def consider(c, o, ms, st, md):
        if best[0] is None or c < best[0][0]:
            best[0] = (c, o[:], ms[:], st[:], md[:])

    bm1 = [-1]*n; bm2 = [-2]*n
    keys = [[-tail[i] for i in range(n)],
            [slack[i] for i in range(n)],
            [(slack[i], -tail[i]) for i in range(n)],
            [((deff[i] if deff[i] < INF else INF), -tail[i]) for i in range(n)],
            [-(Weff[i] + 0.5) / mind[i] for i in range(n)],
            [(head[i], -tail[i]) for i in range(n)],
            [-nsucc[i] for i in range(n)],
            [(rel[i], slack[i]) for i in range(n)]]
    for k in keys:
        o = topo_by(k)
        for bm in (bm1, bm2):
            c, st, md, fin, ns = decode(o, bm)
            consider(c, o, bm, st, md)

    combos = []
    for k in (1.0, 2.0, 0.5, 4.0):
        for kd in (None, 2.0):
            combos.append((k, kd, 0.0, 1.0, 0.0))
    cphase = t0 + 0.32
    sc = max(1.0, float(max(tail)))
    ci = 0
    while ci < 160:
        if ci > 0 and time.process_time() >= cphase: break
        if ci < len(combos):
            prm = combos[ci]
        elif ci % 3 == 2:
            noise = rng.random() * 0.5
            if ci % 2:
                kk = [slack[i] + rng.gauss(0, noise * sc) for i in range(n)]
            else:
                kk = [-tail[i] + rng.gauss(0, noise * sc) for i in range(n)]
            o = topo_by(kk)
            bm = bm1 if rng.random() < 0.5 else bm2
            c, st, md, fin, ns = decode(o, bm)
            consider(c, o, bm, st, md)
            ci += 1
            continue
        else:
            prm = (rng.choice([0.3, 0.5, 1.0, 2.0, 3.0, 5.0]), rng.choice([None, 1.0, 2.0, 4.0]),
                   rng.choice([0.0, 0.3, 1.0, 2.0]), rng.choice([0.2, 1.0, 3.0]),
                   rng.choice([0.1, 0.2, 0.4]))
        ci += 1
        c, o, md, st = construct(*prm)
        consider(c, o, md, st, md)
        if ci <= len(combos) or rng.random() < 0.3:
            c2, st2, md2, fin2, ns2 = decode(o, bm2)
            consider(c2, o, bm2, st2, md2)

    def load_best():
        b = best[0]
        o = b[1][:]; ms = b[2][:]
        c, st, md, fin, ns = decode(o, ms)
        pos = [0]*n
        for p_, j_ in enumerate(o): pos[j_] = p_
        return c, o, ms, st, md, fin, ns, pos

    cur_c, cur_o, cur_m, cur_st, cur_md, cur_fin, cur_ns, cur_pos = load_best()
    multi = [i for i in range(n) if len(modes[i]) > 1]
    duejobs = [i for i in range(n) if hasdue[i] and wt[i] > 0]
    freejobs = [i for i in range(n) if deff[i] >= INF]
    T = max(0.5, 0.02 * cur_c)
    it = 0; since = 0
    start_sa = time.process_time(); span = max(1e-3, deadline - start_sa)
    while True:
        if (it & 3) == 0:
            now = time.process_time()
            if now >= deadline: break
            frac = (now - start_sa) / span
            T = max(0.05, 0.02 * best[0][0] * (1 - frac) ** 2)
        it += 1
        o = cur_o; ms = cur_m; pos = cur_pos
        p0 = n; ochg = False
        r = rng.random()
        if multi and r < 0.18:
            ms = cur_m[:]
            j = rng.choice(multi)
            nv = rng.randrange(-2, len(modes[j]))
            while nv == ms[j]:
                nv = rng.randrange(-2, len(modes[j]))
            ms[j] = nv; p0 = pos[j]
        else:
            j = -1; i = -1; npos = -1
            if r < 0.5 and duejobs:
                tard = [x for x in duejobs if cur_fin[x] > due[x]]
                if tard:
                    j = rng.choice(tard)
                    while rng.random() < 0.6:
                        bp = [p for p in preds[j] if cur_fin[p] >= cur_st[j]]
                        if not bp: break
                        j = rng.choice(bp)
                    i = pos[j]
                    lo = max([pos[p] for p in preds[j]] + [-1]) + 1
                    if lo >= i: continue
                    npos = rng.randint(max(lo, i - 2 * K - 5) if rng.random() < 0.5 else lo, i - 1)
            elif r < 0.6 and freejobs:
                j = rng.choice(freejobs)
                i = pos[j]
                hi = min([pos[s] for s in succs[j]] + [n]) - 1
                if hi <= i: continue
                npos = rng.randint(i + 1, hi)
            if j < 0:
                i = rng.randrange(n)
                j = o[i]
                lo = max([pos[p] for p in preds[j]] + [-1]) + 1
                hi = min([pos[s] for s in succs[j]] + [n]) - 1
                if hi <= lo: continue
                npos = rng.randint(lo, hi)
                if npos == i: continue
            o = o[:i] + o[i+1:]
            o.insert(npos, j)
            ochg = True
            p0 = min(i, npos)
            if r > 0.93 and multi:
                ms = cur_m[:]
                jj = rng.choice(multi)
                ms[jj] = rng.randrange(-2, len(modes[jj]))
                p0 = min(p0, pos[jj])
        c, st, md, fin, ns = decode(o, ms, p0, cur_ns, cur_st, cur_md, cur_fin)
        dlt = c - cur_c
        if dlt <= 0 or rng.random() < math.exp(-dlt / T):
            cur_o = o; cur_m = ms; cur_c = c; cur_st = st; cur_md = md
            cur_fin = fin; cur_ns = ns
            if ochg:
                np_ = [0]*n
                for p_, j_ in enumerate(o): np_[j_] = p_
                cur_pos = np_
            if c < best[0][0]:
                best[0] = (c, o[:], ms[:], st, md); since = 0
        since += 1
        if since > 500:
            cur_c, cur_o, cur_m, cur_st, cur_md, cur_fin, cur_ns, cur_pos = load_best()
            since = 0
    c, o, ms, st, md = best[0]
    sch = {}
    for i in range(n):
        sch[jobs[i]["id"]] = {"start": int(st[i]), "mode": morig[i][md[i]]}
    return {"status": "ok", "schedule": sch}

import time
import heapq
import random


def solve(state, params):
    T0 = time.process_time()
    LIMIT = 0.78
    inp = state.get("input") or {}
    resources = inp.get("resources") or {}
    jobs = inp.get("jobs") or []

    def infeasible(reason):
        state["output"] = {"status": "infeasible", "reason": reason}
        return state

    rnames = list(resources.keys())
    rid = {r: i for i, r in enumerate(rnames)}
    R = len(rnames)
    cals = []
    maxcap = []
    lastbp = 0
    for r in rnames:
        cal = (resources[r] or {}).get("calendar") or [[0, 0]]
