    keys = []
    keys.append([(lst[i], -tail[i]) for i in range(n)])
    keys.append([(edd[i], -tail[i]) for i in range(n)])
    keys.append([(lst[i] - 2 * wsum[i], -tail[i]) for i in range(n)])
    keys.append([-tail[i] for i in range(n)])
    keys.append([(head[i], lst[i]) for i in range(n)])
    keys.append([-nsucc[i] for i in range(n)])
    keys.append([(rel[i], lst[i]) for i in range(n)])
    base = [-1]*n
    best = None
    for k in keys:
        o = topo_by(k)
        c, st, md, fin, ck = decode(o, base, 0, ck0)
        if best is None or c < best[0]:
            best = (c, o[:], base[:], st, md, fin, ck)

    # time-aware dispatching constructions
    presets = [(1.0, 1.0, 0.2, 0.0), (0.5, 0.5, 0.1, 0.0), (2.0, 2.0, 0.3, 0.0),
               (1.0, 1000.0, 0.2, 0.0), (0.3, 0.3, 0.05, 0.0), (1.0, 1.0, 1.0, 0.0)]
    runs = 0
    dend = t0 + 0.30
    while True:
        if runs >= 6 and time.process_time() > dend: break
        if runs >= 200: break
        if runs < len(presets):
            kpar, alpha, mkw, noise = presets[runs]
        else:
            kpar = exp(rng.uniform(math.log(0.2), math.log(4.0)))
            alpha = 1000.0 if rng.random() < 0.15 else exp(rng.uniform(math.log(0.1), math.log(5.0)))
            mkw = rng.choice([0.0, 0.05, 0.1, 0.2, 0.4, 0.8])
            noise = rng.choice([0.0, 0.2, 0.5, 1.0])
        runs += 1
        c, o = dispatch(kpar, alpha, mkw, noise)
        if c < best[0]:
            c2, st, md, fin, ck = decode(o, base, 0, ck0)
            if c2 < best[0]:
                best = (c2, o[:], base[:], st, md, fin, ck)

    cur_c, cur_o, cur_m, cur_fin, cur_ck = best[0], best[1][:], best[2][:], best[5], best[6]

    def mkinfo(o, fin):
        pos = [0]*n
        for p_, j_ in enumerate(o): pos[j_] = p_
        tj = []; tw = []
        for j in range(n):
            if hasdue[j] and fin[j] > due[j]:
                tj.append(j); tw.append(wt[j]*(fin[j]-due[j]))
        mkv = max(fin) if n else 0
        last = [j for j in range(n) if fin[j] == mkv]
        return pos, tj, tw, last

    cur_pos, cur_tj, cur_tw, cur_last = mkinfo(cur_o, cur_fin)
    multi = [i for i in range(n) if len(modes[i]) > 1]
    T = max(0.5, 0.02 * cur_c)
    it = 0; since = 0
    stall = max(300, 4 * n)
    start_sa = time.process_time(); span = max(1e-3, deadline - start_sa)
    while True:
        if (it & 3) == 0:
            now = time.process_time()
            if now >= deadline: break
            frac = (now - start_sa) / span
            T = max(0.05, 0.03 * best[0] * (1 - frac) ** 2)
        it += 1
        o = cur_o; ms = cur_m
        pos = cur_pos
        r = rng.random()
        chg = n
        if multi and r < 0.2:
            ms = cur_m[:]
            j = rng.choice(multi)
            k = len(modes[j])
            nv = rng.randrange(-1, k)
            if nv == ms[j]: nv = -1 if nv >= 0 else rng.randrange(k)
            ms[j] = nv
            chg = pos[j]
        elif r < 0.55:
            if cur_tj and rng.random() < 0.75:
                j = rng.choices(cur_tj, weights=cur_tw)[0]
            elif cur_last:
                j = rng.choice(cur_last)
            else:
                j = rng.randrange(n)
            i = pos[j]
            if i == 0: continue
            spn = rng.randint(1, max(1, min(i, max(3, n // 4))))
            npos = i - spn if rng.random() < 0.8 else rng.randint(0, i - 1)
            mark = {j}
            seg = o[npos:i+1]
            for qq in range(len(seg) - 2, -1, -1):
                x = seg[qq]
                for s in succs[x]:
                    if s in mark:
                        mark.add(x); break
            if seg[0] in mark and len(mark) == len(seg): continue
            mv = [x for x in seg if x in mark]
            rest = [x for x in seg if x not in mark]
            o = o[:npos] + mv + rest + o[i+1:]
            chg = npos
        elif r < 0.7:
            j = rng.randrange(n)
            i = pos[j]
            if i >= n - 1: continue
            spn = rng.randint(1, max(1, min(n - 1 - i, max(3, n // 4))))
            npos = i + spn
            mark = {j}
            seg = o[i:npos+1]
            for qq in range(1, len(seg)):
                x = seg[qq]
                for p in preds[x]:
                    if p in mark:
                        mark.add(x); break
            if len(mark) == len(seg): continue
            mv = [x for x in seg if x in mark]
            rest = [x for x in seg if x not in mark]
            o = o[:i] + rest + mv + o[npos+1:]
            chg = i
        else:
            i = rng.randrange(n)
            j = o[i]
            lo = max([pos[p] for p in preds[j]] + [-1]) + 1
            hi = min([pos[s] for s in succs[j]] + [n]) - 1
            if hi <= lo:
                continue
            npos = rng.randint(lo, hi)
            if npos == i: continue
            o = o[:i] + o[i+1:]
            o.insert(npos, j)
            chg = min(i, npos)
        if r > 0.9 and multi:
            if ms is cur_m: ms = cur_m[:]
            jj = rng.choice(multi)
            ms[jj] = rng.randrange(-1, len(modes[jj]))
            chg = min(chg, pos[jj])
        if chg >= n: continue
        k0 = chg // B
        if k0 >= len(cur_ck): k0 = len(cur_ck) - 1
        c, st, md, fin, ck = decode(o, ms, k0, cur_ck)
        dlt = c - cur_c
        if dlt <= 0 or rng.random() < pow(2.718281828, -dlt / T):
            cur_o = o; cur_m = ms; cur_c = c; cur_fin = fin; cur_ck = ck
            cur_pos, cur_tj, cur_tw, cur_last = mkinfo(cur_o, cur_fin)
            if c < best[0]:
                best = (c, o[:], ms[:], st, md, fin, ck); since = 0
        since += 1
        if since > stall:
            cur_c, cur_o, cur_m, cur_fin, cur_ck = best[0], best[1][:], best[2][:], best[5], best[6]
            cur_pos, cur_tj, cur_tw, cur_last = mkinfo(cur_o, cur_fin)
            since = 0
    c, o, ms, st, md, fin, ck = best
    sch = {}
    for i in range(n):
        sch[jobs[i]["id"]] = {"start": int(st[i]), "mode": morig[i][md[i]]}
    return {"status": "ok", "schedule": sch}

import time
import random


def _infeasible(state, reason):
    state["output"] = {"status": "infeasible", "reason": reason}
    return state


def solve(state, params):
    T0 = time.process_time()
    BUDGET = 0.78
    inp = state["input"]
    resources = inp.get("resources", {}) or {}
    jobs = inp.get("jobs", []) or []
    rnames = list(resources.keys())
    ridx = {r: i for i, r in enumerate(rnames)}
    R = len(rnames)
    cals = []
    maxcap = []
    tlast = 0
    for r in rnames:
        cal = resources[r].get("calendar", []) or [[0, 0]]
        cal = sorted([(int(a), int(b)) for a, b in cal])
        cals.append(cal)
        maxcap.append(max(c for _, c in cal))
        tlast = max(tlast, cal[-1][0])
    n = len(jobs)
    ids = [str(j["id"]) for j in jobs]
    jidx = {}
    for i, s in enumerate(ids):
        jidx[s] = i
    preds = [[] for _ in range(n)]
    for i, j in enumerate(jobs):
        seen = set()
        for p in j.get("after", []) or []:
            p = str(p)
            if p not in jidx:
                return _infeasible(state, "job %s references unknown predecessor %s" % (ids[i], p))
            q = jidx[p]
            if q not in seen:
                seen.add(q)
                preds[i].append(q)
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]:
            succs[p].append(i)
    indeg = [len(preds[i]) for i in range(n)]
    topo = [i for i in range(n) if indeg[i] == 0]
    k = 0
    while k < len(topo):
        x = topo[k]
        k += 1
        for s in succs[x]:
            indeg[s] -= 1
            if indeg[s] == 0:
                topo.append(s)
    if len(topo) < n:
        return _infeasible(state, "precedence relation has a cycle")
    modes = []
    for i, j in enumerate(jobs):
        ml = []
        for mi, m in enumerate(j.get("modes", []) or []):
            ok = True
            req = []
            for rn, u in (m.get("requires", {}) or {}).items():
                u = int(u)
                if rn not in ridx:
                    ok = False
                    break
                if u <= 0:
                    continue
                if u > maxcap[ridx[rn]]:
                    ok = False
                    break
                req.append((ridx[rn], u))
            if ok:
                ml.append((int(m["duration"]), req, mi))
        if not ml:
            return _infeasible(state, "job %s has no mode fitting known resources" % ids[i])
        keep = []
        for a in range(len(ml)):
            da, ra, _ = ml[a]
            va = [0] * R
            for r, u in ra:
                va[r] = u
            dom = False
            for b in range(len(ml)):
                if a == b:
                    continue
                db, rb, _ = ml[b]
                vb = [0] * R
                for r, u in rb:
                    vb[r] = u
                if db <= da and all(vb[r] <= va[r] for r in range(R)):
                    if db < da or any(vb[r] < va[r] for r in range(R)) or b < a:
                        dom = True
                        break
            if not dom:
                keep.append(ml[a])
        modes.append(keep)
    if n == 0:
        state["output"] = {"status": "ok", "schedule": {}}
        return state
    rel = [max(0, int(j.get("release", 0) or 0)) for j in jobs]
    due = [j.get("due") for j in jobs]
    due = [None if d is None else int(d) for d in due]
    wt = [int(j.get("weight", 0) or 0) for j in jobs]
    dmin = [min(m[0] for m in modes[i]) for i in range(n)]
    dmax = [max(m[0] for m in modes[i]) for i in range(n)]
    H = max(tlast, max(rel)) + sum(dmax) + 16
    cap0 = []
    for r in range(R):
        cal = cals[r]
        arr = [0] * H
        for b in range(len(cal)):
            a0 = cal[b][0]
            a1 = cal[b + 1][0] if b + 1 < len(cal) else H
            if a0 >= H:
                break
            a1 = min(a1, H)
            c = cal[b][1]
            for t in range(max(0, a0), a1):
                arr[t] = c
        cap0.append(arr)
    tail = [0] * n
    for x in reversed(topo):
        best = 0
        for s in succs[x]:
            v = dmin[s] + tail[s]
            if v > best:
                best = v
        tail[x] = best
    es0 = [0] * n
    for x in topo:
        e = rel[x]
        for p in preds[x]:
            v = es0[p] + dmin[p]
            if v > e:
                e = v
        es0[x] = e
    cpl = max(es0[i] + dmin[i] + tail[i] for i in range(n))
    menergy = []
    for i in range(n):
        ev = None
        for d, req, _ in modes[i]:
            v = [0] * R
            for r, u in req:
                v[r] = u * d
            if ev is None:
                ev = v
            else:
                ev = [min(ev[r], v[r]) for r in range(R)]
        menergy.append(ev)
    totE = [sum(menergy[i][r] for i in range(n)) for r in range(R)]
    tdue = [d if (d is not None and w > 0) else None for d, w in zip(due, wt)]

    def find(prof, est, dur, req):
        t = est
        while True:
            ok = True
            for r, u in req:
                arr = prof[r]
                s = t + dur - 1
                while s >= t:
                    if arr[s] < u:
                        break
                    s -= 1
                if s >= t:
                    t = s + 1
                    ok = False
                    break
            if ok:
                return t

    def lf_table(cb):
        lf = [0] * n
        for x in reversed(topo):
            v = cb - tail[x]
            if tdue[x] is not None and tdue[x] < v:
                v = tdue[x]
            for s in succs[x]:
                w = lf[s] - dmin[s]
                if w < v:
                    v = w
            lf[x] = v
        return lf

    def run_beam(B, K, beta, noise, cb, rng):
        lf = lf_table(cb)
        lst = [lf[i] - dmin[i] for i in range(n)]
        npl0 = [len(preds[i]) for i in range(n)]
        elig0 = [i for i in range(n) if npl0[i] == 0]
        cache0 = {}
        estd0 = {}
        for e in elig0:
            estd0[e] = rel[e]
            cache0[e] = [find(cap0, rel[e], d, req) for d, req, _ in modes[e]]
        root = (cap0, [-1] * n, [-1] * n, [-1] * n, npl0, elig0, cache0, estd0, 0, 0, list(totE), 0)
        beam = [root]
        for depth in range(n):
            cand = []
            for pi in range(len(beam)):
                node = beam[pi]
                elig = node[5]
                cache = node[6]
                opts = []
                mins = min(min(cache[e]) for e in elig)
                for e in elig:
                    ce = cache[e]
                    ml = modes[e]
                    bestf = None
                    for mi in range(len(ml)):
                        f = ce[mi] + ml[mi][0]
                        if bestf is None or f < bestf:
                            bestf = f
                    for mi in range(len(ml)):
                        s = ce[mi]
                        f = s + ml[mi][0]
                        key = lst[e] + beta * (s - mins) + (f - bestf) * (1.0 + beta)
                        if noise:
                            key += rng.random() * noise
                        opts.append((key, e, mi))
                opts.sort()
                for o in opts[:K]:
                    cand.append((pi, o[1], o[2]))
            evals = []
            seen = set()
            for pi, e, mi in cand:
                node = beam[pi]
                d = modes[e][mi][0]
                s = node[6][e][mi]
                f = s + d
                nsig = (node[11] + hash((e, s, mi)) * 1000003) % 2305843009213693951
                if nsig in seen:
                    continue
                seen.add(nsig)
                evals.append((pi, e, mi, s, f, nsig))
            children = []
            for pi, e, mi, s, f, nsig in evals:
                prof, st, md, fn, npl, elig, cache, estd, gt, cmax, remE, sig = beam[pi]
                d, req, _ = modes[e][mi]
                nprof = list(prof)
                rset = set()
                for r, u in req:
                    a = prof[r][:]
                    for t in range(s, f):
                        a[t] -= u
                    nprof[r] = a
                    rset.add(r)
                nst = st[:]
                nst[e] = s
                nmd = md[:]
                nmd[e] = mi
                nfn = fn[:]
                nfn[e] = f
                ngt = gt
                if tdue[e] is not None and f > tdue[e]:
                    ngt += wt[e] * (f - tdue[e])
                ncm = cmax if cmax > f else f
                nremE = remE[:]
                me = menergy[e]
                for r in range(R):
                    nremE[r] -= me[r]
                nnpl = npl
                nelig = [x for x in elig if x != e]
                ncache = {}
                nestd = {}
                newl = []
                for q in succs[e]:
                    if nnpl is npl:
                        nnpl = npl[:]
                    nnpl[q] -= 1
                    if nnpl[q] == 0:
                        newl.append(q)
                for x in nelig:
                    ce = cache[x]
                    nce = ce
                    nestd[x] = estd[x]
                    ml = modes[x]
                    for k2 in range(len(ml)):
                        sx = ce[k2]
                        dx, rq, _ = ml[k2]
                        if sx < f and sx + dx > s:
                            hit = False
                            for r, u in rq:
                                if r in rset:
                                    hit = True
                                    break
                            if hit:
                                if nce is ce:
                                    nce = ce[:]
                                nce[k2] = find(nprof, sx, dx, rq)
                    ncache[x] = nce
                for q in newl:
                    ex = rel[q]
                    for p in preds[q]:
                        if nfn[p] > ex:
                            ex = nfn[p]
                    nestd[q] = ex
                    ncache[q] = [find(nprof, ex, dx, rq) for dx, rq, _ in modes[q]]
                    nelig.append(q)
                tl = 0
                cml = ncm
                sumef = 0
                EF = {}
                tmin = None
                for x in nelig:
                    ce = ncache[x]
                    ml = modes[x]
                    b = None
                    for k2 in range(len(ml)):
                        v = ce[k2] + ml[k2][0]
                        if b is None or v < b:
                            b = v
                    EF[x] = b
                    sm = min(ce)
                    if tmin is None or sm < tmin:
                        tmin = sm
                for x in topo:
                    if nst[x] >= 0:
                        continue
                    if x in EF:
                        v = EF[x]
                    else:
                        ex = rel[x]
                        for p in preds[x]:
                            pv = nfn[p] if nst[p] >= 0 else EF[p]
                            if pv > ex:
                                ex = pv
                        v = ex + dmin[x]
                        EF[x] = v
                    sumef += v
                    if tdue[x] is not None and v > tdue[x]:
                        tl += wt[x] * (v - tdue[x])
                    vv = v + tail[x]
                    if vv > cml:
                        cml = vv
                if tmin is not None:
                    for r in range(R):
                        if nremE[r] > 0 and maxcap[r] > 0:
                            vv = tmin + (nremE[r] + maxcap[r] - 1) // maxcap[r]
                            if vv > cml:
                                cml = vv
                fval = cml + ngt + tl
                child = (nprof, nst, nmd, nfn, nnpl, nelig, ncache, nestd, ngt, ncm, nremE, nsig)
                children.append((fval, sumef, ncm, len(children), child))
            children.sort(key=lambda c: (c[0], c[1], c[2], c[3]))
            beam = [c[4] for c in children[:B]]
        best = None
        for node in beam:
            cost = node[9] + node[8]
            if best is None or cost < best[0]:
                best = (cost, node[1], node[2])
        return best

    rng = random.Random(12345)
    best = None
    cb = cpl
    unit = None
    sched_runs = [(1, 3, 0.5, 0.0), (1, 4, 0.0, 0.0), (1, 4, 2.0, 0.0)]
    B = 2
    it = 0
    while True:
        el = time.process_time() - T0
        if it < len(sched_runs):
            Bc, Kc, beta, noise = sched_runs[it]
        else:
            Kc = 4
            beta = [0.5, 0.0, 1.0, 2.0][it % 4]
            noise = 0.0 if (it // 4) % 2 == 0 else 1.5
            Bc = B
            while Bc > 1 and el + unit * Bc * Kc * 1.3 > BUDGET:
                Bc = Bc // 2
        if best is not None and unit is not None and el + unit * Bc * Kc * 1.3 > BUDGET:
            break
        t1 = time.process_time()
        res = run_beam(Bc, Kc, beta, noise, cb, rng)
        t2 = time.process_time()
        u = (t2 - t1) / (Bc * Kc)
        unit = u if unit is None else max(unit * 0.7, u)
        if best is None or res[0] < best[0]:
            best = res
            cb = max(cpl, max(best[1][i] + modes[i][best[2][i]][0] for i in range(n)))
        it += 1
        if it > len(sched_runs):
            B = min(128, B * 2)
    cost, st, md = best
    sched = {}
    for i in range(n):
        sched[ids[i]] = {"start": int(st[i]), "mode": int(modes[i][md[i]][2])}
    state["output"] = {"status": "ok", "schedule": sched}
    state["cost"] = cost
    return state

import time, random, heapq, math

def _fallback(inp):
    res = inp["resources"]; jobs = inp["jobs"]
    T0 = 0
    for r in res.values():
        T0 = max(T0, r["calendar"][-1][0])
    for j in jobs:
        T0 = max(T0, j["release"])
    ids = [j["id"] for j in jobs]; idx = {k: i for i, k in enumerate(ids)}
    indeg = [0]*len(jobs); succ = [[] for _ in jobs]
    for i, j in enumerate(jobs):
        for p in set(j["after"]):
            indeg[i] += 1; succ[idx[p]].append(i)
    q = [i for i in range(len(jobs)) if indeg[i] == 0]; order = []
    while q:
        i = q.pop(); order.append(i)
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    t = T0; sch = {}
    for i in order:
        j = jobs[i]
        for mi, m in enumerate(j["modes"]):
            if all(r in res and u <= res[r]["calendar"][-1][1] for r, u in m["requires"].items()):
                sch[j["id"]] = {"start": t, "mode": mi}; t += m["duration"]; break
    return {"status": "ok", "schedule": sch}

def _check(inp):
    res = inp["resources"]; jobs = inp["jobs"]
    ids = set(j["id"] for j in jobs)
    for j in jobs:
        for p in j["after"]:
            if p not in ids:
                return "job %s references unknown predecessor %s" % (j["id"], p)
    for j in jobs:
        ok = False
        for m in j["modes"]:
            if all(r in res and u <= res[r]["calendar"][-1][1] for r, u in m["requires"].items()):
                ok = True; break
        if not ok:
            return "job %s has no feasible mode" % j["id"]
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    indeg = [0]*len(jobs); succ = [[] for _ in jobs]
    for i, j in enumerate(jobs):
        for p in set(j["after"]):
            indeg[i] += 1; succ[idx[p]].append(i)
    q = [i for i in range(len(jobs)) if indeg[i] == 0]; cnt = 0
    while q:
        i = q.pop(); cnt += 1
        for s in succ[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    if cnt != len(jobs):
        return "precedence relation has a cycle"
    return None

def _verify(inp, out):
    try:
        res = inp["resources"]; jobs = inp["jobs"]; sch = out["schedule"]
        fin = {}
        for j in jobs:
            e = sch.get(j["id"])
            if e is None: return False
            s = e["start"]; m = e["mode"]
            if not isinstance(s, int) or not isinstance(m, int): return False
            if s < j["release"] or m < 0 or m >= len(j["modes"]): return False
            fin[j["id"]] = s + j["modes"][m]["duration"]
        for j in jobs:
            for p in j["after"]:
                if sch[j["id"]]["start"] < fin[p]: return False
        for j in jobs:
            md = j["modes"][sch[j["id"]]["mode"]]
            for r, u in md["requires"].items():
                if r not in res or u > res[r]["calendar"][-1][1]: return False
        H = max(list(fin.values()) + [1]) + 1
        for rn, rd in res.items():
            cal = rd["calendar"]; arr = [0]*H
            for k, (s, c) in enumerate(cal):
                e = cal[k+1][0] if k + 1 < len(cal) else H
                s = min(s, H); e = min(e, H)
                if e > s: arr[s:e] = [c]*(e - s)
            use = [0]*H
            for j in jobs:
                e = sch[j["id"]]; md = j["modes"][e["mode"]]
                u = md["requires"].get(rn, 0)
                if u:
                    for x in range(e["start"], e["start"] + md["duration"]): use[x] += u
            for x in range(H):
                if use[x] > arr[x]: return False
        return True
    except Exception:
        return False

def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    reason = _check(inp)
    if reason is not None:
        state["output"] = {"status": "infeasible", "reason": reason}
        return state
    try:
        out = _opt(inp, t0)
        if not _verify(inp, out):
            out = _fallback(inp)
    except Exception:
        out = _fallback(inp)
    state["output"] = out
    return state

def _find(av, t, d, reqs):
    while True:
        moved = False
        for r, u in reqs:
            a = av[r]
            if min(a[t:t+d]) < u:
                x = t + d - 1
                while a[x] >= u: x -= 1
                t = x + 1; moved = True; break
        if not moved:
            return t

def _opt(inp, t0):
    deadline = t0 + 0.88
    rng = random.Random(4242)
    resd = inp["resources"]; jobs = inp["jobs"]
    rnames = list(resd.keys()); ridx = {r: i for i, r in enumerate(rnames)}
    maxcap = [resd[r]["calendar"][-1][1] for r in rnames]
    n = len(jobs)
    if n == 0:
        return {"status": "ok", "schedule": {}}
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    rel = [j["release"] for j in jobs]
    due = [j["due"] for j in jobs]
    wt = [j["weight"] or 0 for j in jobs]
    preds = [sorted(set(idx[p] for p in j["after"])) for j in jobs]
    predset = [set(p) for p in preds]
    succs = [[] for _ in range(n)]
    for i in range(n):
        for p in preds[i]: succs[p].append(i)
    modes = []; morig = []
    for j in jobs:
        ml = []; mo = []
        for mi, m in enumerate(j["modes"]):
            rq = m["requires"]
            if all(r in ridx and u <= maxcap[ridx[r]] for r, u in rq.items()):
                reqs = tuple((ridx[r], u) for r, u in rq.items() if u > 0)
                load = sum(u / max(1, maxcap[r]) for r, u in reqs) * m["duration"]
                rm = 0
                for r, u in reqs: rm |= (1 << r)
                ml.append((m["duration"], reqs, load, rm)); mo.append(mi)
        modes.append(ml); morig.append(mo)
    T0 = max([resd[r]["calendar"][-1][0] for r in rnames] + rel + [0])
    H = T0 + sum(max(m[0] for m in ml) for ml in modes) + 16
    cap = []
    for r in rnames:
        cal = resd[r]["calendar"]; arr = [0]*H
        for k, (s, c) in enumerate(cal):
            e = cal[k+1][0] if k + 1 < len(cal) else H
            s = min(s, H); e = min(e, H)
            if e > s: arr[s:e] = [c]*(e - s)
        cap.append(arr)
    hasdue = [due[i] is not None for i in range(n)]
    INF = 10**9
    duev = [due[i] if hasdue[i] else INF for i in range(n)]

    mind = [min(m[0] for m in ml) for ml in modes]
    indeg = [len(preds[i]) for i in range(n)]
    q = [i for i in range(n) if indeg[i] == 0]; topo = []
    while q:
        i = q.pop(); topo.append(i)
        for s in succs[i]:
            indeg[s] -= 1
            if indeg[s] == 0: q.append(s)
    tail = [0]*n
    for i in reversed(topo):
        tail[i] = mind[i] + max([tail[s] for s in succs[i]] + [0])
    head = [0]*n
    for i in topo:
        head[i] = max([rel[i]] + [head[p] + mind[p] for p in preds[i]])
    nsucc = [0]*n
    for i in reversed(topo):
        nsucc[i] = len(succs[i]) + sum(nsucc[s] for s in succs[i])
    LB_cp = max(head[i] + mind[i] for i in range(n))
    rl = [0.0]*len(rnames)
    for i in range(n):
        bestl = None
        for d, reqs, load, rm in modes[i]:
            if bestl is None or load < bestl[0]: bestl = (load, d, reqs)
        for r, u in bestl[2]:
            rl[r] += u * bestl[1] / max(1, maxcap[r])
    Cb = max([LB_cp] + [int(x) for x in rl])
    big = LB_cp + sum(mind) + 1

    deff = [INF]*n
    for i in range(n):
        if hasdue[i] and wt[i] > 0: deff[i] = due[i]
    for i in reversed(topo):
        for s in succs[i]:
            if deff[s] < INF:
                v = deff[s] - mind[s]
                if v < deff[i]: deff[i] = v
    desc = [0]*n
    for i in reversed(topo):
        b = 0
        for s in succs[i]: b |= (1 << s) | desc[s]
        desc[i] = b
    wdue = [wt[i] if (hasdue[i] and wt[i] > 0) else 0 for i in range(n)]
    Weff = [0]*n
    for i in range(n):
        tot = wdue[i]; b = desc[i]; k = 0
        while b:
            if b & 1: tot += wdue[k]
            b >>= 1; k += 1
        Weff[i] = tot
    pbar = max(1.0, sum(mind) / n)
    slack = [0]*n
    for i in range(n):
        lst = big - tail[i]
        if deff[i] < INF:
            lst = min(lst, deff[i] - mind[i])
        slack[i] = lst

    K = max(4, n // 10)
    NOLIM = float("inf")

    def decode(order, msel, p0=0, snaps=None, st0=None, md0=None, fin0=None, lim=NOLIM):
        ck = p0 // K
        if snaps is None or ck == 0 or ck >= len(snaps):
            ck = 0
            av = [c[:] for c in cap]; cost = 0; mk = 0
            st = [0]*n; md = [0]*n; fin = [0]*n; ns = []
        else:
            a0, cost, mk = snaps[ck]
            av = [a[:] for a in a0]
            st = st0[:]; md = md0[:]; fin = fin0[:]; ns = snaps[:ck]
        for pos in range(ck * K, n):
            if pos % K == 0:
                ns.append(([a[:] for a in av], cost, mk))
            j = order[pos]
            est = rel[j]
            for p in preds[j]:
                if fin[p] > est: est = fin[p]
            ml = modes[j]; ms = msel[j]
            if ms >= 0 or len(ml) == 1:
                m = ms if ms >= 0 else 0
                d = ml[m][0]
                t = _find(av, est, d, ml[m][1]); f = t + d
            else:
                if ms == -1:
                    dj = duev[j]; wj = wt[j]
                else:
                    dj = deff[j]; wj = Weff[j]
                bk = None
                for mm in range(len(ml)):
                    d, reqs, load, rm = ml[mm]
                    tt = _find(av, est, d, reqs)
                    ff = tt + d
                    sc = ff
                    if ff > dj: sc += wj * (ff - dj)
                    key = (sc, load, ff)
                    if bk is None or key < bk:
                        bk = key; m = mm; t = tt; f = ff
            for r, u in ml[m][1]:
                a = av[r]
                a[t:f] = [v - u for v in a[t:f]]
            st[j] = t; md[j] = m; fin[j] = f
            if f > mk: mk = f
            if f > duev[j]: cost += wt[j] * (f - duev[j])
            if cost + mk > lim:
                return None
        return cost + mk, st, md, fin, ns

    def cost_of(st, md):
        mk = 0; c = 0
        for j in range(n):
            f = st[j] + modes[j][md[j]][0]
            if f > mk: mk = f
            if f > duev[j]: c += wt[j] * (f - duev[j])
        return c + mk

    exp = math.exp

    def construct(k, kd, beta, eps, noise):
        av = [c[:] for c in cap]
        rem = [len(preds[i]) for i in range(n)]
        st = [0]*n; md = [0]*n; fin = [0]*n; est = [0]*n
        elig = [i for i in range(n) if rem[i] == 0]
        for i in elig: est[i] = rel[i]
        cache = [None]*n
        nz = [exp(rng.gauss(0, noise)) for _ in range(n)] if noise > 0 else [1.0]*n
        kp = k * pbar; kdp = kd * pbar if kd else 0
        order = []
        while elig:
            info = []; tmin = INF
            for j in elig:
                c = cache[j]
                if c is None:
                    c = [None]*len(modes[j]); cache[j] = c
                bm = None; dj = deff[j]; wj = Weff[j]
                for m, (d, reqs, load, rm) in enumerate(modes[j]):
                    o = c[m]
                    if o is None:
                        t = _find(av, est[j], d, reqs); o = (t, t + d); c[m] = o
                    t, f = o
                    mc = f + beta * load
                    if f > dj: mc += wj * (f - dj)
                    if bm is None or mc < bm[0]: bm = (mc, m, t, f)
                info.append((j, bm))
                if bm[2] < tmin: tmin = bm[2]
            bestk = None; bj = None
            for j, bm in info:
                _, m, t, f = bm
                d = f - t
                s = 0.0
                if deff[j] < INF:
                    sd = deff[j] - f
                    s += Weff[j] * (exp(-sd / kp) if sd > 0 else 1.0)
                sm = Cb - tail[j] + mind[j] - f
                s += eps * (exp(-sm / kp) if sm > 0 else 1.0)
                s = s / d * nz[j]
                if kdp: s *= exp(-(t - tmin) / kdp)
                key = (s, -t)
                if bestk is None or key > bestk:
                    bestk = key; bj = (j, m, t, f)
            j, m, t, f = bj
            d, reqs, load, rm = modes[j][m]
            for r, u in reqs:
                a = av[r]
                a[t:f] = [v - u for v in a[t:f]]
            st[j] = t; md[j] = m; fin[j] = f
            order.append(j)
            elig.remove(j); cache[j] = None
            for e in elig:
                c = cache[e]
                if c is None: continue
                me = modes[e]
                for mi in range(len(c)):
                    o = c[mi]
                    if o is not None and o[0] < f and t < o[1] and (me[mi][3] & rm):
                        c[mi] = None
            for s_ in succs[j]:
                rem[s_] -= 1
                if rem[s_] == 0:
                    e0 = rel[s_]
                    for p in preds[s_]:
                        if fin[p] > e0: e0 = fin[p]
                    est[s_] = e0
                    elig.append(s_)
        return cost_of(st, md), order, md, st

    def topo_by(key):
        deg = [len(preds[i]) for i in range(n)]
        h = [(key[i], i) for i in range(n) if deg[i] == 0]
        heapq.heapify(h); out = []
        while h:
            _, i = heapq.heappop(h); out.append(i)
            for s in succs[i]:
                deg[s] -= 1
                if deg[s] == 0: heapq.heappush(h, (key[s], s))
        return out

    best = [None]

    def consider(c, o, ms, st, md):
        if best[0] is None or c < best[0][0]:
            best[0] = (c, o[:], ms[:], st[:], md[:])

    bm1 = [-1]*n; bm2 = [-2]*n
    keys = [[-tail[i] for i in range(n)],
            [slack[i] for i in range(n)],
            [(slack[i], -tail[i]) for i in range(n)],
            [((deff[i] if deff[i] < INF else INF), -tail[i]) for i in range(n)],
            [-(Weff[i] + 0.5) / mind[i] for i in range(n)],
            [(head[i], -tail[i]) for i in range(n)],
            [-nsucc[i] for i in range(n)],
            [(rel[i], slack[i]) for i in range(n)]]
    for k in keys:
        o = topo_by(k)
        for bm in (bm1, bm2):
            c, st, md, fin, ns = decode(o, bm)
            consider(c, o, bm, st, md)
        if time.process_time() - t0 > 0.25: break

    combos = []
    for k in (1.0, 2.0, 0.5, 4.0):
        for kd in (None, 2.0):
            combos.append((k, kd, 0.0, 1.0, 0.0))
    cphase = t0 + 0.34
    sc = max(1.0, float(max(tail)))
    ci = 0
    while ci < 200:
        if time.process_time() >= cphase: break
        if ci < len(combos):
            prm = combos[ci]
        elif ci % 3 == 2:
            noise = rng.random() * 0.5
            if ci % 2:
                kk = [slack[i] + rng.gauss(0, noise * sc) for i in range(n)]
            else:
                kk = [-tail[i] + rng.gauss(0, noise * sc) for i in range(n)]
            o = topo_by(kk)
            bm = bm1 if rng.random() < 0.5 else bm2
            c, st, md, fin, ns = decode(o, bm)
            consider(c, o, bm, st, md)
            ci += 1
            continue
        else:
            prm = (rng.choice([0.3, 0.5, 1.0, 2.0, 3.0, 5.0]), rng.choice([None, 1.0, 2.0, 4.0]),
                   rng.choice([0.0, 0.3, 1.0, 2.0]), rng.choice([0.2, 1.0, 3.0]),
                   rng.choice([0.1, 0.2, 0.4]))
        ci += 1
        c, o, md, st = construct(*prm)
        consider(c, o, md, st, md)
        if ci <= len(combos) or rng.random() < 0.3:
            c2, st2, md2, fin2, ns2 = decode(o, bm2)
            consider(c2, o, bm2, st2, md2)

    def load_best():
        b = best[0]
        o = b[1][:]; ms = b[2][:]
        c, st, md, fin, ns = decode(o, ms)
        pos = [0]*n
        for p_, j_ in enumerate(o): pos[j_] = p_
        return c, o, ms, st, md, fin, ns, pos

    cur_c, cur_o, cur_m, cur_st, cur_md, cur_fin, cur_ns, cur_pos = load_best()
    if cur_c < best[0][0]:
        best[0] = (cur_c, cur_o[:], cur_m[:], cur_st[:], cur_md[:])
    multi = [i for i in range(n) if len(modes[i]) > 1]
    duejobs = [i for i in range(n) if hasdue[i] and wt[i] > 0]
    freejobs = [i for i in range(n) if deff[i] >= INF]
    stall = max(500, 5 * n)
    T = max(0.5, 0.02 * cur_c)
    it = 0; since = 0
    start_sa = time.process_time(); span = max(1e-3, deadline - start_sa)
    log = math.log
    while True:
        if (it & 3) == 0:
            now = time.process_time()
            if now >= deadline: break
            frac = (now - start_sa) / span
            T = max(0.05, 0.02 * best[0][0] * (1 - frac) ** 2)
        it += 1
        o = cur_o; ms = cur_m; pos = cur_pos
        p0 = n; ochg = False
        r = rng.random()
        if multi and r < 0.18:
            ms = cur_m[:]
            j = rng.choice(multi)
            nv = rng.randrange(-2, len(modes[j]))
            while nv == ms[j]:
                nv = rng.randrange(-2, len(modes[j]))
            ms[j] = nv; p0 = pos[j]
        elif r < 0.26:
            i = rng.randrange(n - 1) if n > 1 else 0
            if n < 2: continue
            a_ = o[i]; b_ = o[i + 1]
            if a_ in predset[b_]: continue
            o = o[:]
            o[i] = b_; o[i + 1] = a_
            ochg = True; p0 = i
        else:
            j = -1; i = -1; npos = -1
            if r < 0.58 and duejobs:
                tard = [x for x in duejobs if cur_fin[x] > due[x]]
                if tard:
                    j = rng.choice(tard)
                    while rng.random() < 0.6:
                        bp = [p for p in preds[j] if cur_fin[p] >= cur_st[j]]
                        if not bp: break
                        j = rng.choice(bp)
                    i = pos[j]
                    lo = max([pos[p] for p in preds[j]] + [-1]) + 1
                    if lo >= i: continue
                    npos = rng.randint(max(lo, i - 2 * K - 5) if rng.random() < 0.5 else lo, i - 1)
            elif r < 0.66 and freejobs:
                j = rng.choice(freejobs)
                i = pos[j]
                hi = min([pos[s] for s in succs[j]] + [n]) - 1
                if hi <= i: continue
                npos = rng.randint(i + 1, hi)
            if j < 0:
                i = rng.randrange(n)
                j = o[i]
                lo = max([pos[p] for p in preds[j]] + [-1]) + 1
                hi = min([pos[s] for s in succs[j]] + [n]) - 1
                if hi <= lo: continue
                npos = rng.randint(lo, hi)
                if npos == i: continue
            o = o[:i] + o[i+1:]
            o.insert(npos, j)
            ochg = True
            p0 = min(i, npos)
            if r > 0.94 and multi:
                ms = cur_m[:]
                jj = rng.choice(multi)
                ms[jj] = rng.randrange(-2, len(modes[jj]))
                p0 = min(p0, pos[jj])
        thr = cur_c - T * log(1.0 - rng.random())
        res = decode(o, ms, p0, cur_ns, cur_st, cur_md, cur_fin, thr)
        if res is not None:
            c, st, md, fin, ns = res
            if c <= thr:
                cur_o = o; cur_m = ms; cur_c = c; cur_st = st; cur_md = md
                cur_fin = fin; cur_ns = ns
                if ochg:
                    np_ = [0]*n
                    for p_, j_ in enumerate(o): np_[j_] = p_
                    cur_pos = np_
                if c < best[0][0]:
                    best[0] = (c, o[:], ms[:], st, md); since = 0
        since += 1
        if since > stall:
            cur_c, cur_o, cur_m, cur_st, cur_md, cur_fin, cur_ns, cur_pos = load_best()
            since = 0
    c, o, ms, st, md = best[0]
    sch = {}
    for i in range(n):
        sch[jobs[i]["id"]] = {"start": int(st[i]), "mode": morig[i][md[i]]}
    return {"status": "ok", "schedule": sch}
